@Slf4j
class MenuOverlay extends Overlay
{
	private static final int NO_ITEM = -1;
	private static final int EXACT_CONTRADICTION_LOG_LIMIT = 20;
	private static final int IMAGE_CACHE_MISMATCH_LOG_LIMIT = 10;
	private static final boolean SUBMENU_TRACE_ENABLED = Boolean.getBoolean("rightclickstyler.submenuTrace");
	private static final int SUBMENU_TRACE_LIMIT = 24;

	/**
	 * How the exact-coverage reading ("new") compares with the probe's previous resolver
	 * ("old") on one frame.
	 */
	enum ExactComparison
	{
		/** The exact reading did not run: the draw never reached the marked root. */
		NOT_EVALUATED,
		/** Both resolved the same chain. */
		AGREE,
		/** Both resolved a chain, and the chains differ. Never rendered. */
		CONTRADICTORY,
		/** The old resolver proved a chain; the exact reading did not resolve one. */
		OLD_RESOLVED_NEW_UNRESOLVED,
		/** The old resolver was ambiguous; the exact reading resolved a chain. */
		OLD_AMBIGUOUS_NEW_RESOLVED,
		/** The old resolver was ambiguous and the exact reading did not resolve a chain. */
		BOTH_UNRESOLVED,
		/** A buffer, restore or geometry check failed, so neither reading may be used. */
		OLD_FAILED
	}

	enum SubmenuOutcome
	{
		READY_ROOT_ONLY,
		READY_WITH_CHILD,
		READY_WITH_NATIVE_DETACHED_CHILD,
		/**
		 * The pixels fit several chains (such as two siblings sharing one rectangle), and every
		 * one of them renders identically, so the frame is themed without knowing which one
		 * native drew.
		 */
		READY_WITH_EQUIVALENT_CHILD,
		/**
		 * The pixels fit several one-menu chains sharing one rectangle, and the native draw's
		 * own pixels in that rectangle exclude all but one of them ({@link NativeChildImages}).
		 */
		READY_WITH_NATIVE_IDENTIFIED_CHILD,
		FALLBACK_AMBIGUOUS,
		FALLBACK_INVALID_BOUNDS,
		FALLBACK_BUFFER_MISMATCH,
		FALLBACK_NATIVE_DRAW_MISSED,
		FALLBACK_RESTORE_FAILURE,
		FALLBACK_GEOMETRY_CHANGED,
		FALLBACK_TREE_DEPTH,
		FALLBACK_TREE_COUNT,
		FALLBACK_TREE_CYCLE,
		FALLBACK_COMPLEXITY,
		FALLBACK_RENDER_EXCEPTION,
		FALLBACK_PROBE_EXCEPTION,
		FALLBACK_SCROLLABLE,
		FALLBACK_TRANSIENT,
		/** The exact reading was unevidenced, unexplained or failed. */
		FALLBACK_EXACT_UNRESOLVED,
		/** The two resolvers proved different chains. Neither is drawn. */
		FALLBACK_EXACT_CONTRADICTION,
		FALLBACK_OTHER
	}

	private final Client client;
	private final RightClickStylerConfig config;
	private final ThemeManager themeManager;
	private final MenuRenderer renderer = new MenuRenderer();
	private final NativeSubmenuProbe probe = new NativeSubmenuProbe();
	/** Native images of child menus this menu opening proved; cleared with each opening. */
	private final NativeChildImages nativeChildImages = new NativeChildImages();
	private final long[] exactComparisons = new long[ExactComparison.values().length];
	private long exactContradictionLogs;
	private long exactContradictionSuppressed;
	private ExactComparison lastExactComparison = ExactComparison.NOT_EVALUATED;
	private SubmenuOutcome lastOutcome;
	private final long[] submenuOutcomes = new long[SubmenuOutcome.values().length];
	/**
	 * Reuse the themed image when every rendering input is unchanged. The probe and every
	 * check still run each frame. Tests can turn the cache off, or re-render every Nth hit and
	 * compare pixels; production never verifies.
	 */
	private boolean imageCacheEnabled = true;
	private int imageCacheVerifyEvery;
	private final SubmenuImageCache imageCache = new SubmenuImageCache();
	private SubmenuImageCache.Miss lastImageMiss;
	private final long[] imageMisses = new long[SubmenuImageCache.Miss.values().length];
	private long imageVerifyChecks;
	private long imageVerifyMismatchTotal;
	private BufferedImage verifyImage;
	private int[] verifyExpected = new int[0];
	private int[] verifyActual = new int[0];
	private final List<MenuRenderer.Row> rows = new ArrayList<>();
	private final List<MenuRenderer.Row> rowPool = new ArrayList<>();
	private final Rectangle bounds = new Rectangle();
	private final List<RowBuffer> submenuRows = new ArrayList<>();
	private BufferedImage submenuImage;
	private int preparedX;
	private int preparedY;
	private Menu preparedRoot;
	private PreparedMenuState preparedState;
	private boolean preparedScrollable;
	private int preparedScroll;
	private int preparedFirstRow;
	/**
	 * What the prepared image was drawn from, kept so that a structural change after the event
	 * is consumed can be proven not to change the image ({@link #imageMatchesLiveMenus}).
	 */
	private SubmenuTree preparedTree;
	/** The renderer inputs of every drawn menu, root first. */
	private SubmenuImageCache.Menu[] preparedMenus;
	/** Every chain the image stands for, or null when none can be re-proven at the final draw. */
	private int[][] preparedChains;
	private ScrollableMenuViewport preparedViewport;
	private Point preparedMouse;
	private boolean prepared;
	private boolean externallyConsumed;
	private long lastFailureLog;
	private long submenuBlits;
	/** Final draws whose live structure changed after consumption without changing the image. */
	private long submenuEquivalentBlits;
	private long submenuClosedDrops;
	private long submenuChangedDrops;
	/**
	 * A consumed frame failed its final draw in this menu opening. Submenus stay native, without
	 * being probed, for the rest of the opening; {@link #menuOpened} ends it.
	 */
	private boolean submenuBlitFailed;
	private int submenuTraceLogs;
	private final boolean[] tracedOutcomes = new boolean[SubmenuOutcome.values().length];

	/**
	 * Set after the first render failure. The plugin consumes {@code BeforeMenuRender}, so a render
	 * that throws would leave the menu invisible; once this is set we stop consuming and the vanilla
	 * menu is drawn for the rest of the session. Volatile because the plugin resets it from startUp.
	 */
	private volatile boolean failed;

	@Inject
	private MenuOverlay(Client client, RightClickStylerConfig config, ThemeManager themeManager)
	{
		this.client = client;
		this.config = config;
		this.themeManager = themeManager;
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPosition(OverlayPosition.DYNAMIC);
	}

	/** Tests only: production always uses the cache and never verifies a hit. */
	synchronized void setImageCache(boolean enabled, int verifyEvery)
	{
		imageCacheEnabled = enabled;
		imageCacheVerifyEvery = verifyEvery;
		imageCache.invalidate();
	}

	/** From startUp: a restart ends every failure state, except a failed opening still on screen. */
	void resetFailure()
	{
		failed = false;
		synchronized (this)
		{
			clearPrepared();
			imageCache.invalidate();
			nativeChildImages.clear();
			// No MenuOpened was seen for an open menu, so it may be the failed opening: keep it
			// native until the next opening. Reads one client flag; no rendering state.
			submenuBlitFailed = submenuBlitFailed && client.isMenuOpen();
		}
	}

	/**
	 * RuneLite posts MenuOpened from the client's root-menu opening, before the menu is marked
	 * open, on every opening; native submenu changes do not pass through it. It therefore ends
	 * the previous opening, however it closed, before anything of the new one is probed or drawn.
	 * RuneLite reuses the root Menu object, so the opening must also end any prepared frame.
	 */
	synchronized void menuOpened()
	{
		clearPrepared();
		nativeChildImages.clear();
		if (submenuBlitFailed)
		{
			// Nothing drawn for the failed opening is reused: the next image is rendered afresh.
			imageCache.invalidate();
			submenuBlitFailed = false;
		}
	}

	synchronized void discardPreparedAtEventStart()
	{
		clearPrepared();
	}

	synchronized void setExternallyConsumed(boolean consumed)
	{
		externallyConsumed = consumed;
	}

	private void recordOutcome(SubmenuOutcome outcome)
	{
		recordOutcome(outcome, "");
	}

	private void recordOutcome(SubmenuOutcome outcome, String detail)
	{
		if (SUBMENU_TRACE_ENABLED && outcome.name().startsWith("FALLBACK")
			&& !tracedOutcomes[outcome.ordinal()])
		{
			tracedOutcomes[outcome.ordinal()] = true;
			traceOutcome(outcome.name(), detail);
		}
		lastOutcome = outcome;
		submenuOutcomes[outcome.ordinal()]++;
	}

	/** Bounded opt-in outcome logging without inspecting menu entries on each frame. */
	private void traceOutcome(String state, String detail)
	{
		if (!SUBMENU_TRACE_ENABLED || submenuTraceLogs >= SUBMENU_TRACE_LIMIT)
		{
			return;
		}
		submenuTraceLogs++;
		log.info("RCS_SUBMENU outcome={} detail={}", state, Limits.truncate(detail == null ? "" : detail, 120));
	}

	private void traceFinalDrop(String detail)
	{
		traceOutcome("FINAL_DROP", detail);
	}

	/**
	 * Prepares the themed image for a menu with submenus or a scrollable root.
	 *
	 * @param frameMouse the one mouse sample taken when {@code BeforeMenuRender} began. It is the
	 * only mouse position used for this frame: the native probe proves which submenus are open
	 * in this client cycle, and that state cannot change until the next cycle, so the live
	 * pointer is never re-read to revalidate the frame.
	 */
	synchronized boolean prepareSubmenuFrame(Menu root, MenuEntry[] rootEntries, Point frameMouse)
	{
		prepared = false;
		preparedRoot = null;
		preparedState = null;
		if (!client.isMenuOpen())
		{
			recordOutcome(SubmenuOutcome.FALLBACK_TRANSIENT);
			return false;
		}
		boolean scrollable = client.isMenuScrollable();
		int scroll = scrollable ? client.getMenuScroll() : 0;
		if (submenuBlitFailed)
		{
			recordOutcome(SubmenuOutcome.FALLBACK_RENDER_EXCEPTION);
			return false;
		}
		boolean preparingTheme = false;
		try
		{
			int canvasWidth = client.getCanvasWidth();
			int canvasHeight = client.getCanvasHeight();
			if (canvasWidth <= 0 || canvasHeight <= 0
				|| (long) canvasWidth * canvasHeight > 8_388_608L)
			{
				recordOutcome(SubmenuOutcome.FALLBACK_INVALID_BOUNDS);
				return false;
			}
			ScrollableMenuViewport viewport = ScrollableMenuViewport.capture(
				new Rectangle(root.getMenuX(), root.getMenuY(), root.getMenuWidth(), root.getMenuHeight()),
				rootEntries.length,
				canvasWidth, canvasHeight, scrollable, scroll);
			if (viewport == null)
			{
				recordOutcome(SubmenuOutcome.FALLBACK_SCROLLABLE);
				return false;
			}
			SubmenuTree tree = SubmenuTree.capture(root, rootEntries,
				scrollable ? viewport.firstRow : 0);
			NativeSubmenuProbe.Result result = probe.probe(client, tree);
			if (result.state == NativeSubmenuProbe.State.GEOMETRY_CHANGED)
			{
				// Native drawing can update even a previously nonzero child rectangle.
				// Re-sample once against the current positions.
				tree = SubmenuTree.capture(root, root.getMenuEntries(),
					scrollable ? viewport.firstRow : 0);
				result = probe.probe(client, tree);
				viewport = ScrollableMenuViewport.capture(tree.nodes.get(0).bounds,
					tree.nodes.get(0).entries.length, canvasWidth, canvasHeight,
					scrollable, scroll);
			}
			// Pure classification: the rendering decision below depends on it.
			ExactComparison comparison = classifyExact(result);
			exactRecord(result, tree, comparison);
			if (viewport == null || client.isMenuScrollable() != scrollable
				|| (scrollable && client.getMenuScroll() != scroll))
			{
				recordOutcome(SubmenuOutcome.FALLBACK_SCROLLABLE);
				return false;
			}
			// The exact reading decides. Anything but one uniquely resolved chain on a
			// verified framebuffer stays native: no guess, no forced selection.
			SubmenuOutcome rejection = authoritativeRejection(result, tree);
			// Ambiguous pixels: theme only when every chain they fit renders identically.
			int[][] equivalent = rejection == SubmenuOutcome.FALLBACK_AMBIGUOUS
				? visuallyEquivalentAlternatives(result, tree, viewport, frameMouse, scroll, null) : null;
			// Otherwise, only the native draw's own pixels may tell the alternatives apart.
			int[] identified = null;
			if (rejection == SubmenuOutcome.FALLBACK_AMBIGUOUS && equivalent == null)
			{
				identified = nativeChildImages.identify(result, tree, null);
			}
			if (rejection == null && result.exact.chain.length == 1)
			{
				nativeChildImages.remember(result, tree, result.exact.chain[0]);
			}
			else if (identified != null)
			{
				nativeChildImages.remember(result, tree, identified[0]);
			}
			if (rejection != null && equivalent == null && identified == null)
			{
				recordOutcome(rejection, result.reason);
				return false;
			}
			int[] chain = equivalent != null ? equivalent[0] : identified != null ? identified : result.exact.chain;
			ScrollChildValidation childValidation = ScrollChildValidation.ATTACHED;
			for (int i = 0; scrollable && i < (equivalent != null ? equivalent.length : 1); i++)
			{
				// An ambiguous frame proves no single child, so a detached one is rejected here.
				childValidation = validateScrolledChild(tree, equivalent != null ? equivalent[i] : chain,
					viewport, canvasHeight, result);
				if (childValidation.reason != null)
				{
					recordOutcome(SubmenuOutcome.FALLBACK_SCROLLABLE);
					return false;
				}
			}
			Rectangle region = new Rectangle(tree.nodes.get(0).bounds);
			for (int candidate : chain)
			{
				region.add(tree.nodes.get(candidate + 1).bounds);
			}
			region.grow(3, 3);
			region = region.intersection(new Rectangle(0, 0, canvasWidth, canvasHeight));
			if (region.width <= 0 || region.height <= 0)
			{
				recordOutcome(SubmenuOutcome.FALLBACK_INVALID_BOUNDS);
				return false;
			}
			if (submenuImage == null || submenuImage.getWidth() != region.width
				|| submenuImage.getHeight() != region.height)
			{
				submenuImage = new BufferedImage(region.width, region.height, BufferedImage.TYPE_INT_ARGB);
				imageCache.invalidate();
			}
			// Every alternative's nodes, so a change to any of them before the blit drops the frame.
			PreparedMenuState state = equivalent != null ? PreparedMenuState.capture(tree, equivalent)
				: identified != null ? PreparedMenuState.capture(tree, result.exact.alternatives)
				: PreparedMenuState.capture(tree, chain);
			String mismatch = state.mismatchReason(client.getMenu());
			if (mismatch != null)
			{
				recordOutcome(SubmenuOutcome.FALLBACK_TRANSIENT, mismatch);
				return false;
			}
			preparingTheme = true;
			Theme theme = themeManager.effectiveTheme();
			Player player = client.getLocalPlayer();
			int localLevel = player == null ? 0 : player.getCombatLevel();
			SubmenuImageCache.Menu[] drawn = renderOrReuseSubmenuImage(tree, chain, viewport, region,
				frameMouse, scroll, theme, localLevel);
			// Structural state only: the frame's mouse sample is fixed, so pointer
			// movement since the sample is not a reason to discard native proof.
			boolean changed = !client.isMenuOpen()
				|| client.isMenuScrollable() != scrollable
				|| (scrollable && client.getMenuScroll() != scroll)
				|| state.mismatchReason(client.getMenu()) != null;
			if (changed)
			{
				recordOutcome(SubmenuOutcome.FALLBACK_TRANSIENT, "menu/scroll/entry changed after image render");
				return false;
			}
			preparedX = region.x;
			preparedY = region.y;
			preparedRoot = tree.root;
			preparedState = state;
			preparedScrollable = scrollable;
			preparedScroll = scroll;
			preparedFirstRow = scrollable ? viewport.firstRow : 0;
			preparedTree = tree;
			preparedMenus = drawn;
			// An identified child was told apart from its alternatives by native pixels that no
			// longer exist after consumption, so only a proven or equivalent chain is re-checked.
			preparedChains = equivalent != null ? equivalent : identified != null ? null : new int[][]{chain};
			preparedViewport = viewport;
			preparedMouse = frameMouse;
			prepared = true;
			SubmenuOutcome ready = equivalent != null ? SubmenuOutcome.READY_WITH_EQUIVALENT_CHILD
				: identified != null ? SubmenuOutcome.READY_WITH_NATIVE_IDENTIFIED_CHILD
				: chain.length == 0 ? SubmenuOutcome.READY_ROOT_ONLY
				: childValidation.detached ? SubmenuOutcome.READY_WITH_NATIVE_DETACHED_CHILD
				: SubmenuOutcome.READY_WITH_CHILD;
			recordOutcome(ready);
			return true;
		}
		catch (IllegalArgumentException e)
		{
			clearPrepared();
			recordOutcome(preparingTheme ? SubmenuOutcome.FALLBACK_RENDER_EXCEPTION
				: treeFailureOutcome(e.getMessage()));
			return false;
		}
		catch (RuntimeException e)
		{
			clearPrepared();
			recordOutcome(preparingTheme
				? SubmenuOutcome.FALLBACK_RENDER_EXCEPTION : SubmenuOutcome.FALLBACK_PROBE_EXCEPTION,
				e.getClass().getSimpleName() + ": " + e.getMessage());
			long now = System.nanoTime();
			if (now - lastFailureLog >= 5_000_000_000L)
			{
				lastFailureLog = now;
				log.warn("Submenu preparation failed; native menu retained", e);
			}
			return false;
		}
	}

	/**
	 * Compares the exact reading ("new") with the probe's previous resolver ("old"). Pure and
	 * total over every probe result, so the rendering decision can rely on it. An exact
	 * ERROR counts as unresolved: it never proves a chain.
	 */
	static ExactComparison classifyExact(NativeSubmenuProbe.Result result)
	{
		ExactCoverageResolver.Outcome exact = result.exact;
		if (exact == null || exact.state == ExactCoverageResolver.State.NOT_EVALUATED)
		{
			return ExactComparison.NOT_EVALUATED;
		}
		if (!result.framebufferVerified)
		{
			return ExactComparison.OLD_FAILED;
		}
		boolean resolved = exact.state == ExactCoverageResolver.State.RESOLVED;
		if (result.state == NativeSubmenuProbe.State.NO_CHILD
			|| result.state == NativeSubmenuProbe.State.ACTIVE)
		{
			return !resolved ? ExactComparison.OLD_RESOLVED_NEW_UNRESOLVED
				: Arrays.equals(exact.chain, result.activeChain) ? ExactComparison.AGREE
				: ExactComparison.CONTRADICTORY;
		}
		if (result.state == NativeSubmenuProbe.State.AMBIGUOUS)
		{
			return resolved ? ExactComparison.OLD_AMBIGUOUS_NEW_RESOLVED : ExactComparison.BOTH_UNRESOLVED;
		}
		return ExactComparison.OLD_FAILED;
	}

	/**
	 * The rendering gate: null only for one uniquely resolved, well-formed exact chain on
	 * a verified framebuffer that the previous resolver does not contradict. Every later
	 * structural, scroll and lifecycle check still applies to the chain it lets through.
	 */
	static SubmenuOutcome authoritativeRejection(NativeSubmenuProbe.Result result, SubmenuTree tree)
	{
		if (!result.framebufferVerified)
		{
			// Buffer, restore and geometry failures keep their existing outcomes.
			return failureOutcome(result);
		}
		ExactCoverageResolver.Outcome exact = result.exact;
		if (exact == null || exact.state == ExactCoverageResolver.State.AMBIGUOUS)
		{
			return SubmenuOutcome.FALLBACK_AMBIGUOUS;
		}
		if (exact.state != ExactCoverageResolver.State.RESOLVED || exact.explainingChains != 1
			|| !wellFormedChain(exact.chain, tree))
		{
			return SubmenuOutcome.FALLBACK_EXACT_UNRESOLVED;
		}
		if (classifyExact(result) == ExactComparison.CONTRADICTORY)
		{
			return SubmenuOutcome.FALLBACK_EXACT_CONTRADICTION;
		}
		return null;
	}

	/** Each member is a real candidate whose parent is the previous member (the root first). */
	private static boolean wellFormedChain(int[] chain, SubmenuTree tree)
	{
		int parent = -1;
		for (int candidate : chain)
		{
			if (candidate < 0 || candidate >= tree.candidateParents.size()
				|| tree.candidateParents.get(candidate) != parent)
			{
				return false;
			}
			parent = candidate;
		}
		return true;
	}

	/**
	 * The chains an ambiguous frame fits, when themeing it needs no choice between them: null
	 * unless the exact reading listed every explaining chain on a verified framebuffer, each is
	 * well formed, any chain the previous resolver proved is among them, and every one gives
	 * the renderer equal inputs for every menu it draws (bounds, header and its colour kind,
	 * every row's option, target, kind and arrow, and hovered row). Callbacks, entry identity
	 * and which entry opened a child are not rendering inputs, so siblings that differ only
	 * there theme identically. Menu Entry Swapper's left-click and shift-click submenus usually
	 * do not: each leaves out the op currently set for its own mode, so their rows differ even
	 * though their row counts, and so their rectangles at a clamped edge, are equal.
	 *
	 * <p>The root is the same node in every chain and its hover comes from the frame's mouse
	 * sample alone, so no root row is highlighted because of which child native drew.
	 */
	static int[][] visuallyEquivalentAlternatives(NativeSubmenuProbe.Result result, SubmenuTree tree,
		ScrollableMenuViewport viewport, Point mouse, int scroll)
	{
		return visuallyEquivalentAlternatives(result, tree, viewport, mouse, scroll, null);
	}

	/** @param why diagnostics only: receives the reason when the result is null; may be null */
	static int[][] visuallyEquivalentAlternatives(NativeSubmenuProbe.Result result, SubmenuTree tree,
		ScrollableMenuViewport viewport, Point mouse, int scroll, StringBuilder why)
	{
		ExactCoverageResolver.Outcome exact = result.exact;
		if (!result.framebufferVerified || exact == null
			|| exact.state != ExactCoverageResolver.State.AMBIGUOUS || exact.alternatives.length < 2
			|| exact.alternatives.length != exact.explainingChains)
		{
			if (why != null)
			{
				why.append(!result.framebufferVerified ? "framebuffer unverified"
					: exact == null ? "no exact reading"
					: exact.state != ExactCoverageResolver.State.AMBIGUOUS ? "exact " + exact.state
					: exact.hiddenCandidate >= 0 ? "hidden-grandchild guard: candidate " + exact.hiddenCandidate
						+ " could be drawn unseen beneath an explaining chain"
					: "alternatives incomplete " + exact.alternatives.length + "/" + exact.explainingChains);
			}
			return null;
		}
		int[][] alternatives = exact.alternatives;
		boolean previousProved = false;
		for (int[] alternative : alternatives)
		{
			if (!wellFormedChain(alternative, tree))
			{
				if (why != null)
				{
					why.append("malformed chain ").append(Arrays.toString(alternative));
				}
				return null;
			}
			previousProved |= Arrays.equals(alternative, result.activeChain);
		}
		if ((result.state == NativeSubmenuProbe.State.NO_CHILD
			|| result.state == NativeSubmenuProbe.State.ACTIVE) && !previousProved)
		{
			if (why != null)
			{
				why.append("previous resolver proved ").append(Arrays.toString(result.activeChain))
					.append(", not an alternative");
			}
			return null; // the previous resolver proved a chain the pixels do not fit
		}
		List<MenuRenderer.Row> rootRows = new ArrayList<>();
		SubmenuImageCache.Menu rootMenu = rootMenu(tree, viewport, mouse, scroll, rootRows);
		SubmenuImageCache.Menu[] first = drawnMenus(tree, alternatives[0], rootMenu, rootRows, mouse);
		for (int i = 1; i < alternatives.length; i++)
		{
			SubmenuImageCache.Menu[] other = drawnMenus(tree, alternatives[i], rootMenu, rootRows, mouse);
			if (SubmenuImageCache.menusDifference(first, other) != SubmenuImageCache.Miss.HIT)
			{
				if (why != null)
				{
					why.append("chains ").append(Arrays.toString(alternatives[0])).append(" and ")
						.append(Arrays.toString(alternatives[i])).append(" differ: ")
						.append(SubmenuImageCache.describeDifference(first, other));
				}
				return null;
			}
		}
		return alternatives;
	}

	/** The root's renderer inputs, filled as {@link #renderOrReuseSubmenuImage} fills them; fills {@code rootRows}. */
	private static SubmenuImageCache.Menu rootMenu(SubmenuTree tree, ScrollableMenuViewport viewport,
		Point mouse, int scroll, List<MenuRenderer.Row> rootRows)
	{
		SubmenuTree.Node root = tree.nodes.get(0);
		MenuRenderer.TargetKind rootKind = fillMenuRows(root, null, rootRows, new ArrayList<>());
		return SubmenuImageCache.menu(root.bounds, root.header, rootKind,
			scroll, viewport.hoverIndex(mouse), rootRows);
	}

	/**
	 * Whether the prepared image is still exactly the image preparation would draw for the live
	 * menus. Called only after the event was consumed and the strict final check failed, so the
	 * alternative is a frame with no menu at all.
	 *
	 * <p>True only when the live hierarchy has the prepared nodes (the same menu objects, opened
	 * from the same entries, with the same geometry) and, for every chain the image stands for,
	 * the renderer would now receive inputs equal to those it drew from. Native submenu state
	 * changes only in the client's per-cycle input step, and its geometry and links are
	 * unchanged, so the chain the probe proved is still the one open. What changed (for example
	 * a click callback, or the entries of a menu that is not drawn) is not a rendering input, so
	 * the image is pixel-identical to a fresh render of the live state and every native hitbox is
	 * where the image shows it. Any visible difference returns false; nothing is re-rendered.
	 */
	private boolean imageMatchesLiveMenus(Menu currentRoot)
	{
		if (preparedTree == null || preparedMenus == null || preparedChains == null)
		{
			return false;
		}
		SubmenuTree live;
		try
		{
			live = SubmenuTree.capture(currentRoot, currentRoot.getMenuEntries(), preparedFirstRow);
		}
		catch (IllegalArgumentException e)
		{
			return false; // the live hierarchy is outside the supported limits
		}
		if (!sameNodes(preparedTree, live))
		{
			return false;
		}
		for (int[] chain : preparedChains)
		{
			List<MenuRenderer.Row> rootRows = new ArrayList<>();
			SubmenuImageCache.Menu root = rootMenu(live, preparedViewport, preparedMouse, preparedScroll, rootRows);
			if (SubmenuImageCache.menusDifference(preparedMenus,
				drawnMenus(live, chain, root, rootRows, preparedMouse)) != SubmenuImageCache.Miss.HIT)
			{
				return false;
			}
		}
		return true;
	}

	/** The same menu objects in the same order, opened from the same entries, at the same bounds. */
	private static boolean sameNodes(SubmenuTree prepared, SubmenuTree live)
	{
		if (prepared.nodes.size() != live.nodes.size())
		{
			return false;
		}
		for (int i = 0; i < prepared.nodes.size(); i++)
		{
			SubmenuTree.Node a = prepared.nodes.get(i);
			SubmenuTree.Node b = live.nodes.get(i);
			if (a.menu != b.menu || a.parentNode != b.parentNode
				|| a.parentEntryIndex != b.parentEntryIndex || !a.bounds.equals(b.bounds))
			{
				return false;
			}
		}
		return true;
	}

	/** The renderer inputs of one chain, filled exactly as {@link #renderOrReuseSubmenuImage} fills them. */
	private static SubmenuImageCache.Menu[] drawnMenus(SubmenuTree tree, int[] chain,
		SubmenuImageCache.Menu rootMenu, List<MenuRenderer.Row> rootRows, Point mouse)
	{
		SubmenuImageCache.Menu[] menus = new SubmenuImageCache.Menu[chain.length + 1];
		menus[0] = rootMenu;
		List<MenuRenderer.Row> parentRows = rootRows;
		for (int depth = 1; depth <= chain.length; depth++)
		{
			SubmenuTree.Node node = menuNode(tree, chain, depth);
			MenuRenderer.Row parentRow = openingRow(tree, node, menuNode(tree, chain, depth - 1), parentRows);
			List<MenuRenderer.Row> rows = new ArrayList<>();
			MenuRenderer.TargetKind headerKind = fillMenuRows(node, parentRow, rows, new ArrayList<>());
			menus[depth] = SubmenuImageCache.menu(node.bounds, node.header, headerKind, 0,
				hoverIndex(node.bounds, rows.size(), mouse), rows);
			parentRows = rows;
		}
		return menus;
	}

	/** Bookkeeping only: nothing here reaches the rendering decision. */
	private void exactRecord(NativeSubmenuProbe.Result result, SubmenuTree tree, ExactComparison comparison)
	{
		lastExactComparison = comparison;
		exactComparisons[comparison.ordinal()]++;
		if (comparison == ExactComparison.CONTRADICTORY)
		{
			logContradiction(result, tree);
		}
	}

	/** Both resolvers proved a chain and they differ: logged a bounded number of times per session. */
	private void logContradiction(NativeSubmenuProbe.Result result, SubmenuTree tree)
	{
		if (exactContradictionLogs++ >= EXACT_CONTRADICTION_LOG_LIMIT)
		{
			exactContradictionSuppressed++;
			return;
		}
		try
		{
			log.warn("Submenu exact-coverage contradiction; native menu kept. probe={} probeChain={} exact={} exactChain={} covered={} scroll={} root={} canvas={}x{} candidates={} bounds={} parents={}",
				result.state + ": " + result.reason, chainBounds(tree, result.activeChain), result.exact,
				chainBounds(tree, result.exact.chain), chainBounds(tree, result.exact.covered),
				client.getMenuScroll(), tree.nodes.get(0).bounds, client.getCanvasWidth(), client.getCanvasHeight(),
				tree.candidateBounds.size(), tree.candidateBounds, tree.candidateParents);
		}
		catch (RuntimeException ignored)
		{
			// Logging must never affect the rendering decision.
		}
	}

	private static String chainBounds(SubmenuTree tree, int[] chain)
	{
		StringBuilder text = new StringBuilder("[");
		for (int candidate : chain)
		{
			if (candidate >= 0 && candidate < tree.candidateBounds.size())
			{
				Rectangle bounds = tree.candidateBounds.get(candidate);
				text.append(text.length() > 1 ? " " : "").append(candidate).append('=')
					.append(bounds.x).append(',').append(bounds.y).append(',')
					.append(bounds.width).append('x').append(bounds.height);
			}
		}
		return text.append(']').toString();
	}

	/**
	 * Fills the rows of every drawn menu, then renders them into {@link #submenuImage}, or
	 * keeps the image already there when the cache is enabled and every rendering input equals
	 * the inputs it was rendered from.
	 *
	 * @return the renderer inputs of every drawn menu, root first, as the image now holds them
	 */
	private SubmenuImageCache.Menu[] renderOrReuseSubmenuImage(SubmenuTree tree, int[] activeChain,
		ScrollableMenuViewport viewport, Rectangle region, Point mouse, int scroll,
		Theme theme, int localLevel)
	{
		int menus = activeChain.length + 1;
		int[] hovered = new int[menus];
		for (int depth = 0; depth < menus; depth++)
		{
			SubmenuTree.Node node = menuNode(tree, activeChain, depth);
			RowBuffer buffer = submenuRowBuffer(depth);
			// Shallower depths are filled first, so the opening row already holds this frame's state.
			MenuRenderer.Row parentRow = depth == 0 ? null : openingRow(tree, node,
				menuNode(tree, activeChain, depth - 1), submenuRowBuffer(depth - 1).rows);
			buffer.headerKind = fillMenuRows(node, parentRow, buffer.rows, buffer.pool);
			hovered[depth] = depth == 0
				? viewport.hoverIndex(mouse)
				: hoverIndex(node.bounds, buffer.rows.size(), mouse);
		}
		SubmenuImageCache.Menu[] drawn = new SubmenuImageCache.Menu[menus];
		for (int depth = 0; depth < menus; depth++)
		{
			SubmenuTree.Node node = menuNode(tree, activeChain, depth);
			RowBuffer buffer = submenuRowBuffer(depth);
			drawn[depth] = SubmenuImageCache.menu(node.bounds, node.header, buffer.headerKind,
				depth == 0 ? scroll : 0, hovered[depth], buffer.rows);
		}
		if (!imageCacheEnabled)
		{
			drawSubmenuImage(submenuImage, tree, activeChain, region, hovered, scroll, theme, localLevel);
			return drawn;
		}
		SubmenuImageCache.Key key = SubmenuImageCache.capture(theme, config, client.getModIcons(),
			localLevel, region, drawn);
		SubmenuImageCache.Miss miss = imageCache.lookup(key);
		lastImageMiss = miss;
		imageMisses[miss.ordinal()]++;
		if (miss == SubmenuImageCache.Miss.HIT)
		{
			if (imageCacheVerifyEvery > 0 && imageMisses[miss.ordinal()] % imageCacheVerifyEvery == 0
				&& !verifyReusedImage(tree, activeChain, region, hovered, scroll, theme, localLevel))
			{
				// A rendering input is missing from the key. Never show the stale image.
				imageCache.invalidate();
				drawSubmenuImage(submenuImage, tree, activeChain, region, hovered, scroll, theme, localLevel);
				imageCache.rendered(key);
			}
			return drawn;
		}
		// Invalid until the render completes, so a render that throws can never be reused.
		imageCache.invalidate();
		drawSubmenuImage(submenuImage, tree, activeChain, region, hovered, scroll, theme, localLevel);
		if (key != null)
		{
			imageCache.rendered(key);
		}
		return drawn;
	}

	private static SubmenuTree.Node menuNode(SubmenuTree tree, int[] activeChain, int depth)
	{
		return tree.nodes.get(depth == 0 ? 0 : activeChain[depth - 1] + 1);
	}

	/** Draws the rows already filled for each depth. */
	private void drawSubmenuImage(BufferedImage image, SubmenuTree tree, int[] activeChain,
		Rectangle region, int[] hovered, int scroll, Theme theme, int localLevel)
	{
		Graphics2D g = image.createGraphics();
		try
		{
			g.setComposite(AlphaComposite.Clear);
			g.fillRect(0, 0, region.width, region.height);
			g.setComposite(AlphaComposite.SrcOver);
			g.translate(-region.x, -region.y);
			for (int depth = 0; depth <= activeChain.length; depth++)
			{
				SubmenuTree.Node node = menuNode(tree, activeChain, depth);
				RowBuffer buffer = submenuRowBuffer(depth);
				renderer.render(g, client, theme, config, buffer.rows, node.bounds,
					hovered[depth], localLevel, node.header, buffer.headerKind, depth == 0 ? scroll : 0);
			}
		}
		finally
		{
			g.dispose();
		}
	}

	/** Renders the same inputs into a scratch image and compares every pixel. */
	private boolean verifyReusedImage(SubmenuTree tree, int[] activeChain, Rectangle region,
		int[] hovered, int scroll, Theme theme, int localLevel)
	{
		int width = region.width;
		int height = region.height;
		if (verifyImage == null || verifyImage.getWidth() != width || verifyImage.getHeight() != height)
		{
			verifyImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		}
		drawSubmenuImage(verifyImage, tree, activeChain, region, hovered, scroll, theme, localLevel);
		if (verifyExpected.length != width * height)
		{
			verifyExpected = new int[width * height];
			verifyActual = new int[width * height];
		}
		// getRGB copies through the raster, so the displayed image stays GPU-accelerable.
		verifyImage.getRGB(0, 0, width, height, verifyExpected, 0, width);
		submenuImage.getRGB(0, 0, width, height, verifyActual, 0, width);
		imageVerifyChecks++;
		if (Arrays.equals(verifyExpected, verifyActual))
		{
			return true;
		}
		if (imageVerifyMismatchTotal++ < IMAGE_CACHE_MISMATCH_LOG_LIMIT)
		{
			log.warn("Submenu image cache mismatch region={} chain={}: a rendering input is missing from the cache key; re-rendered",
				region, Arrays.toString(activeChain));
		}
		return false;
	}

	private static SubmenuOutcome treeFailureOutcome(String reason)
	{
		if (reason == null)
		{
			return SubmenuOutcome.FALLBACK_OTHER;
		}
		if (reason.startsWith("menu depth limit"))
		{
			return SubmenuOutcome.FALLBACK_TREE_DEPTH;
		}
		if (reason.startsWith("menu count limit")
			|| reason.startsWith("menu total entry count limit")
			|| reason.startsWith("invalid menu entry count"))
		{
			return SubmenuOutcome.FALLBACK_TREE_COUNT;
		}
		if (reason.startsWith("menu identity cycle"))
		{
			return SubmenuOutcome.FALLBACK_TREE_CYCLE;
		}
		if (reason.contains("bounds"))
		{
			return SubmenuOutcome.FALLBACK_INVALID_BOUNDS;
		}
		return SubmenuOutcome.FALLBACK_OTHER;
	}

	static String unsafeScrolledChild(SubmenuTree tree, int[] chain,
		ScrollableMenuViewport rootViewport, int canvasHeight)
	{
		return validateScrolledChild(tree, chain, rootViewport, canvasHeight, null).reason;
	}

	/**
	 * @param proof the probe result the chain came from. A detached child counts as natively
	 * drawn only when that result's exact reading resolved it: every marked pixel of its visible
	 * rectangle changed.
	 */
	static ScrollChildValidation validateScrolledChild(SubmenuTree tree, int[] chain,
		ScrollableMenuViewport rootViewport, int canvasHeight,
		NativeSubmenuProbe.Result proof)
	{
		boolean detached = false;
		for (int candidate : chain)
		{
			SubmenuTree.Node child = tree.nodes.get(candidate + 1);
			SubmenuTree.Node parent = tree.nodes.get(child.parentNode);
			if (child.entries.length == 0 || child.bounds.height > canvasHeight
				|| (long) child.entries.length * MenuRenderer.ROW_HEIGHT
					+ MenuRenderer.HEADER_HEIGHT > canvasHeight)
			{
				return ScrollChildValidation.reject("active child may need an unavailable submenu scroll offset");
			}
			int row = parent.entries.length - 1 - child.parentEntryIndex;
			int rowTop;
			if (child.parentNode == 0)
			{
				if (!rootViewport.containsRow(row))
				{
					return ScrollChildValidation.reject("active child parent row is outside the root viewport"
						+ " row=" + row + " scroll=" + rootViewport.scroll);
				}
				rowTop = rootViewport.rowTop(row);
			}
			else
			{
				rowTop = parent.bounds.y + MenuRenderer.HEADER_HEIGHT
					+ row * MenuRenderer.ROW_HEIGHT;
			}
			if (rowTop >= canvasHeight || rowTop + MenuRenderer.ROW_HEIGHT <= 0)
			{
				return ScrollChildValidation.reject("active child parent row is outside the canvas"
					+ " row=" + row + " rowTop=" + rowTop);
			}
			if (child.bounds.y >= rowTop + MenuRenderer.ROW_HEIGHT
				|| child.bounds.y + child.bounds.height <= rowTop)
			{
				// Native drawing can retain a child's old position for a scroll
				// transition. Theme it at that exact position only when the same
				// probe proves this child was actually drawn there.
				if (!exactlyDrawn(proof, candidate))
				{
					return ScrollChildValidation.reject("active child bounds are detached from its visible parent row"
						+ " row=" + row + " rowTop=" + rowTop + " child=" + child.bounds
						+ " exclusive=" + (proof == null || candidate >= proof.changed.length
							? 0 : proof.changed[candidate])
						+ " footprintMatches=" + (proof == null ? 0 : proof.footprintMatches)
						+ " exact=" + (proof == null ? "none" : proof.exact.state));
				}
				detached = true;
			}
		}
		return detached ? ScrollChildValidation.DETACHED : ScrollChildValidation.ATTACHED;
	}

	/** The probe's own exact reading resolved a chain containing this candidate. */
	private static boolean exactlyDrawn(NativeSubmenuProbe.Result proof, int candidate)
	{
		if (proof == null || !proof.restored || !proof.framebufferVerified
			|| proof.exact.state != ExactCoverageResolver.State.RESOLVED)
		{
			return false;
		}
		for (int proved : proof.exact.chain)
		{
			if (proved == candidate)
			{
				return true;
			}
		}
		return false;
	}

	static final class ScrollChildValidation
	{
		static final ScrollChildValidation ATTACHED = new ScrollChildValidation(null, false);
		static final ScrollChildValidation DETACHED = new ScrollChildValidation(null, true);
		final String reason;
		final boolean detached;

		private ScrollChildValidation(String reason, boolean detached)
		{
			this.reason = reason;
			this.detached = detached;
		}

		static ScrollChildValidation reject(String reason)
		{
			return new ScrollChildValidation(reason, false);
		}
	}

	private static SubmenuOutcome failureOutcome(NativeSubmenuProbe.Result result)
	{
		if (result.state == NativeSubmenuProbe.State.AMBIGUOUS)
		{
			return SubmenuOutcome.FALLBACK_AMBIGUOUS;
		}
		if (result.reason.startsWith("candidate pixel area limit"))
		{
			return SubmenuOutcome.FALLBACK_COMPLEXITY;
		}
		if ("framebuffer restoration failed".equals(result.reason))
		{
			return SubmenuOutcome.FALLBACK_RESTORE_FAILURE;
		}
		if ("native draw missed buffer".equals(result.reason))
		{
			return SubmenuOutcome.FALLBACK_NATIVE_DRAW_MISSED;
		}
		if (result.reason.contains("raster/provider")
			|| result.reason.contains("buffer identity")
			|| "invalid framebuffer".equals(result.reason))
		{
			return SubmenuOutcome.FALLBACK_BUFFER_MISMATCH;
		}
		if (result.state == NativeSubmenuProbe.State.GEOMETRY_CHANGED)
		{
			return SubmenuOutcome.FALLBACK_GEOMETRY_CHANGED;
		}
		if (result.reason.contains("geometry"))
		{
			return SubmenuOutcome.FALLBACK_INVALID_BOUNDS;
		}
		return SubmenuOutcome.FALLBACK_OTHER;
	}

	synchronized void clearPrepared()
	{
		prepared = false;
		preparedRoot = null;
		preparedState = null;
		preparedScrollable = false;
		preparedScroll = 0;
		preparedFirstRow = 0;
		preparedTree = null;
		preparedMenus = null;
		preparedChains = null;
		preparedViewport = null;
		preparedMouse = null;
	}

	private RowBuffer submenuRowBuffer(int depth)
	{
		while (submenuRows.size() <= depth)
		{
			submenuRows.add(new RowBuffer());
		}
		return submenuRows.get(depth);
	}

	private static final class RowBuffer
	{
		private final List<MenuRenderer.Row> rows = new ArrayList<>();
		private final List<MenuRenderer.Row> pool = new ArrayList<>();
		private MenuRenderer.TargetKind headerKind;
	}

	static boolean preparedFrameMatches(boolean menuOpen, Menu currentRoot, Menu preparedRoot)
	{
		return menuOpen && currentRoot == preparedRoot;
	}

	/**
	 * Whether the regular renderer should replace the vanilla menu. Scrollable roots and submenu
	 * trees are prepared by {@link #prepareSubmenuFrame} before this path is reached.
	 */
	boolean shouldDraw()
	{
		return drawableEntries() != null;
	}

	/**
	 * @return the open menu's entries, or null if we shouldn't replace it. The client copies the
	 * array on every call, so callers fetch it once.
	 */
	private MenuEntry[] drawableEntries()
	{
		if (!canInspectMenu(failed, client.isMenuOpen(), client.isMenuScrollable()))
		{
			return null;
		}
		Menu menu = client.getMenu();
		if (menu == null)
		{
			return null;
		}
		MenuEntry[] entries = menu.getMenuEntries();
		if (entries == null || entries.length == 0)
		{
			return null;
		}
		return containsSubMenu(entries) ? null : entries;
	}

	static boolean canInspectMenu(boolean failed, boolean open, boolean scrollable)
	{
		return !failed && open && !scrollable;
	}

	static boolean containsSubMenu(MenuEntry[] entries)
	{
		for (MenuEntry entry : entries)
		{
			if (entry != null && entry.getSubMenu() != null)
			{
				return true;
			}
		}
		return false;
	}

	@Override
	public synchronized Dimension render(Graphics2D graphics)
	{
		if (externallyConsumed)
		{
			externallyConsumed = false;
			clearPrepared();
			return null;
		}
		if (prepared)
		{
			try
			{
				boolean open = client.isMenuOpen();
				Menu currentRoot = open ? client.getMenu() : null;
				// The event is already consumed, so a drop here leaves this frame without a
				// menu. Only structural changes may cause it; the pointer is never read here.
				boolean rootChanged = open && (!preparedFrameMatches(true, currentRoot, preparedRoot)
					|| client.isMenuScrollable() != preparedScrollable
					|| (preparedScrollable && client.getMenuScroll() != preparedScroll)
					|| preparedState == null);
				String change = !open ? null : rootChanged ? "root or scroll"
					: preparedState.mismatchReason(currentRoot);
				// A change that leaves every rendering input, link and rectangle as prepared does
				// not change the image, so that image is still the live menu's.
				boolean equivalent = change != null && !rootChanged && imageMatchesLiveMenus(currentRoot);
				if (!open)
				{
					submenuClosedDrops++;
					traceFinalDrop("menu closed after event consumed");
				}
				else if (change != null && !equivalent)
				{
					submenuChangedDrops++;
					submenuBlitFailed = true;
					traceFinalDrop(change + " changed after event consumed");
				}
				else if (graphics.drawImage(submenuImage, preparedX, preparedY, null))
				{
					submenuBlits++;
					if (equivalent)
					{
						submenuEquivalentBlits++;
						traceOutcome("FINAL_EQUIVALENT", change + " changed after event consumed; image unchanged");
					}
				}
				else
				{
					submenuBlitFailed = true;
					traceFinalDrop("drawImage returned false after event consumed");
				}
			}
			catch (RuntimeException e)
			{
				submenuBlitFailed = true;
				traceFinalDrop(e.getClass().getSimpleName() + ": " + e.getMessage());
				log.warn("Submenu final image draw failed; native submenus until the menu is next opened", e);
			}
			finally
			{
				clearPrepared();
			}
			return null;
		}
		MenuEntry[] entries = drawableEntries();
		if (entries == null)
		{
			return null;
		}
		try
		{
			renderMenu(graphics, client.getMenu(), entries);
		}
		catch (RuntimeException e)
		{
			failed = true;
			log.warn("Right Click Styler failed to draw the menu; using the vanilla menu for the rest of this session", e);
		}
		return null;
	}

	private void renderMenu(Graphics2D graphics, Menu menu, MenuEntry[] entries)
	{
		setNativeBounds(bounds, menu);
		Theme theme = themeManager.effectiveTheme();

		fillRows(entries);

		int hoverIndex = hoverIndex(client.getMouseCanvasPosition());
		Player local = client.getLocalPlayer();
		int localLevel = local != null ? local.getCombatLevel() : 0;
		renderer.render(graphics, client, theme, config, rows, bounds, hoverIndex, localLevel);
	}

	static void setNativeBounds(Rectangle target, Menu menu)
	{
		target.setBounds(menu.getMenuX(), menu.getMenuY(), menu.getMenuWidth(), menu.getMenuHeight());
	}

	/**
	 * Entries are stored bottom-up; rows are drawn top-down. A null entry still occupies a row so
	 * the hover maths stays aligned with the vanilla click areas.
	 *
	 */
	private void fillRows(MenuEntry[] entries)
	{
		fillRows(entries, null, null, rows, rowPool);
	}

	private static void fillRows(MenuEntry[] entries, boolean[] childFlags,
		boolean[] childOpensLeft,
		List<MenuRenderer.Row> rows, List<MenuRenderer.Row> rowPool)
	{
		fillRows(entries, childFlags, childOpensLeft, rows, rowPool, null, null);
	}

	/** The already-filled row whose entry opened {@code node}, or null when it cannot be matched. */
	static MenuRenderer.Row openingRow(SubmenuTree tree, SubmenuTree.Node node, SubmenuTree.Node parent,
		List<MenuRenderer.Row> parentRows)
	{
		if (node.parentNode < 0 || node.parentNode >= tree.nodes.size()
			|| tree.nodes.get(node.parentNode) != parent)
		{
			return null;
		}
		int slot = parent.entries.length - 1 - node.parentEntryIndex;
		return slot >= 0 && slot < parentRows.size() ? parentRows.get(slot) : null;
	}

	/**
	 * Fills one drawn menu. A child menu takes target context from the row that opened it: its
	 * header, and any child entry repeating that row's target, colour like that row does.
	 *
	 * @param parentRow the opening row, null for the root
	 * @return the header's target kind, or null when the header is not the opening row's target
	 */
	static MenuRenderer.TargetKind fillMenuRows(SubmenuTree.Node node, MenuRenderer.Row parentRow,
		List<MenuRenderer.Row> rows, List<MenuRenderer.Row> rowPool)
	{
		MenuRenderer.TargetKind parentKind = parentRow == null ? null : parentRow.kind();
		String parentPlainTarget = null;
		if (parentKind != null && parentKind != MenuRenderer.TargetKind.OTHER && parentRow.target() != null)
		{
			parentPlainTarget = Text.removeTags(parentRow.target()).trim();
		}
		boolean inherits = parentPlainTarget != null && !parentPlainTarget.isEmpty();
		fillRows(node.entries, node.childFlags, node.childOpensLeft, rows, rowPool,
			inherits ? parentKind : null, inherits ? parentPlainTarget : null);
		return parentRow != null && node.headerFromTarget ? parentKind : null;
	}

	/**
	 * A child entry with no actor, object or item of its own that repeats the opening row's
	 * target (optionally followed by appended text, such as an ID suffix) names that same thing,
	 * so it takes that row's kind. Every other child keeps its own classification.
	 */
	static MenuRenderer.TargetKind childKind(MenuEntry entry, MenuRenderer.TargetKind parentKind,
		String parentPlainTarget)
	{
		MenuRenderer.TargetKind own = classify(entry);
		if (own != MenuRenderer.TargetKind.OTHER || parentKind == null || parentPlainTarget == null
			|| parentPlainTarget.isEmpty())
		{
			return own;
		}
		String target = entry.getTarget();
		if (target == null || !target.contains(parentPlainTarget))
		{
			return own;
		}
		String plain = Text.removeTags(target).trim();
		return plain.equals(parentPlainTarget) || plain.startsWith(parentPlainTarget + " ")
			? parentKind : own;
	}

	private static void fillRows(MenuEntry[] entries, boolean[] childFlags,
		boolean[] childOpensLeft,
		List<MenuRenderer.Row> rows, List<MenuRenderer.Row> rowPool,
		MenuRenderer.TargetKind parentKind, String parentPlainTarget)
	{
		rows.clear();
		for (int i = entries.length - 1; i >= 0; i--)
		{
			int slot = rows.size();
			if (slot == rowPool.size())
			{
				rowPool.add(new MenuRenderer.Row(null, null, MenuRenderer.TargetKind.OTHER));
			}
			MenuRenderer.Row row = rowPool.get(slot);
			MenuEntry entry = entries[i];
			if (entry != null)
			{
				row.set(entry.getOption(), entry.getTarget(),
					parentKind == null ? classifyWithItemOwner(entry, entries)
						: childKind(entry, parentKind, parentPlainTarget),
					childFlags != null && childFlags[i],
					childOpensLeft != null && childOpensLeft[i]);
			}
			else
			{
				row.set(null, null, MenuRenderer.TargetKind.OTHER);
			}
			rows.add(row);
		}
	}

	private int hoverIndex(Point mouse)
	{
		return hoverIndex(bounds, rows.size(), mouse);
	}

	static int hoverIndex(Rectangle bounds, int rowCount, Point mouse)
	{
		if (mouse == null || mouse.getX() < bounds.x || mouse.getX() >= bounds.x + bounds.width)
		{
			return -1;
		}
		int relativeY = mouse.getY() - (bounds.y + MenuRenderer.HEADER_HEIGHT);
		if (relativeY < 0)
		{
			return -1;
		}
		int index = relativeY / MenuRenderer.ROW_HEIGHT;
		return index < rowCount ? index : -1;
	}

	static MenuRenderer.TargetKind classify(MenuEntry entry)
	{
		if (entry.getNpc() != null)
		{
			return MenuRenderer.TargetKind.NPC;
		}
		if (entry.getPlayer() != null)
		{
			return MenuRenderer.TargetKind.PLAYER;
		}
		MenuAction type = entry.getType();
		if (isGameObjectAction(type))
		{
			return MenuRenderer.TargetKind.OBJECT;
		}
		if (isGroundItemAction(type) || heldItemId(entry) != NO_ITEM)
		{
			return MenuRenderer.TargetKind.ITEM;
		}
		return MenuRenderer.TargetKind.OTHER;
	}

	/** RuneLite inventory plugins copy the Examine target into a new submenu parent. */
	private static MenuRenderer.TargetKind classifyWithItemOwner(MenuEntry entry, MenuEntry[] entries)
	{
		MenuRenderer.TargetKind own = classify(entry);
		if (own != MenuRenderer.TargetKind.OTHER || entry.getType() != MenuAction.RUNELITE
			|| entry.getSubMenu() == null || entry.getTarget() == null)
		{
			return own;
		}
		String target = Text.removeTags(entry.getTarget()).trim();
		if (target.isEmpty())
		{
			return own;
		}
		boolean itemOwner = false;
		for (MenuEntry candidate : entries)
		{
			if (candidate == null || candidate == entry || candidate.getTarget() == null
				|| !target.equals(Text.removeTags(candidate.getTarget()).trim()))
			{
				continue;
			}
			MenuRenderer.TargetKind candidateKind = classify(candidate);
			if (candidateKind == MenuRenderer.TargetKind.ITEM && heldItemId(candidate) != NO_ITEM)
			{
				itemOwner = true;
			}
			else if (candidateKind != MenuRenderer.TargetKind.OTHER)
			{
				return own;
			}
		}
		return itemOwner ? MenuRenderer.TargetKind.ITEM : own;
	}

	/**
	 * Container ops carry their item's id. A worn equipment slot's ops belong to the slot layer,
	 * which holds no item of its own, so the worn item is read from the slot's item child, as
	 * RuneLite's Menu Entry Swapper does.
	 */
	static int heldItemId(MenuEntry entry)
	{
		int itemId = entry.getItemId();
		MenuAction type = entry.getType();
		if (itemId != NO_ITEM || (type != MenuAction.CC_OP && type != MenuAction.CC_OP_LOW_PRIORITY))
		{
			return itemId;
		}
		Widget slot = entry.getWidget();
		if (slot == null || !isWornEquipmentSlot(slot.getId()))
		{
			return NO_ITEM;
		}
		Widget item = slot.getChild(1);
		return item != null && item.getItemId() > NO_ITEM ? item.getItemId() : NO_ITEM;
	}

	/** The equipment tab's eleven worn slots; its buttons and other components are not items. */
	static boolean isWornEquipmentSlot(int componentId)
	{
		switch (componentId)
		{
			case InterfaceID.Wornitems.SLOT0:
			case InterfaceID.Wornitems.SLOT1:
			case InterfaceID.Wornitems.SLOT2:
			case InterfaceID.Wornitems.SLOT3:
			case InterfaceID.Wornitems.SLOT4:
			case InterfaceID.Wornitems.SLOT5:
			case InterfaceID.Wornitems.SLOT7:
			case InterfaceID.Wornitems.SLOT9:
			case InterfaceID.Wornitems.SLOT10:
			case InterfaceID.Wornitems.SLOT12:
			case InterfaceID.Wornitems.SLOT13:
				return true;
			default:
				return false;
		}
	}

	static boolean isGameObjectAction(MenuAction type)
	{
		if (type == null)
		{
			return false;
		}
		switch (type)
		{
			case ITEM_USE_ON_GAME_OBJECT:
			case WIDGET_TARGET_ON_GAME_OBJECT:
			case GAME_OBJECT_FIRST_OPTION:
			case GAME_OBJECT_SECOND_OPTION:
			case GAME_OBJECT_THIRD_OPTION:
			case GAME_OBJECT_FOURTH_OPTION:
			case GAME_OBJECT_FIFTH_OPTION:
			case EXAMINE_OBJECT:
				return true;
			default:
				return false;
		}
	}

	private static boolean isGroundItemAction(MenuAction type)
	{
		if (type == null)
		{
			return false;
		}
		switch (type)
		{
			case ITEM_USE_ON_GROUND_ITEM:
			case WIDGET_TARGET_ON_GROUND_ITEM:
			case GROUND_ITEM_FIRST_OPTION:
			case GROUND_ITEM_SECOND_OPTION:
			case GROUND_ITEM_THIRD_OPTION:
			case GROUND_ITEM_FOURTH_OPTION:
			case GROUND_ITEM_FIFTH_OPTION:
			case EXAMINE_ITEM_GROUND:
				return true;
			default:
				return false;
		}
	}
}

package com.rightclickstyler;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.AbstractMap;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.IndexedSprite;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

/**
 * Draws a themed menu. Shared by the live overlay and the sidebar preview, which each resolve their
 * own bounds/hover row and pass in plain {@link Row}s instead of real menu entries.
 * <p>
 * Each caller owns its own instance and only ever uses it from one thread (the overlay from the
 * client thread, the preview from the EDT), so the caches here need no synchronisation. The preview
 * passes a null {@code Client}, so nothing here may touch the client off the client thread.
 */
final class MenuRenderer
{
	// Excludes '<' from the tag body so a stray '<' in text doesn't swallow the following real tag.
	private static final Pattern TAG = Pattern.compile("<([^<>]*)>");
	private static final Pattern COL = Pattern.compile("col=([0-9a-fA-F]{1,6})", Pattern.CASE_INSENSITIVE);
	private static final Pattern IMG = Pattern.compile("img=(\\d{1,4})", Pattern.CASE_INSENSITIVE);
	private static final Pattern LEVEL = Pattern.compile("\\(level-(-?\\d{1,4})\\)", Pattern.CASE_INSENSITIVE);
	// Whitespace followed only by tags/whitespace up to the end, i.e. visually trailing.
	private static final Pattern TRAILING_SPACE = Pattern.compile("\\s+(?=(?:<[^<>]*>|\\s)*$)");
	private static final Pattern WHITESPACE_RUN = Pattern.compile("\\s+");
	private static final String CLOSE_COL = "/col";

	// The game's own menu geometry. Its click rows use these, so ours must too.
	static final int HEADER_HEIGHT = 19;
	static final int ROW_HEIGHT = 15;

	private static final String HEADER_TEXT = "Choose Option";
	private static final Color DEFAULT_TAG_COLOUR = Color.YELLOW;
	private static final Color NATIVE_ITEM_COLOUR = new Color(0xFF9040);
	private static final Color NATIVE_OBJECT_COLOUR = Color.CYAN;
	private static final Color TEXT_SHADOW_COLOUR = Color.BLACK;
	private static final Color HIT_ROW_COLOUR = Color.MAGENTA;
	private static final int TEXT_SHADOW_OFFSET = 1;
	private static final int SUBMENU_RIGHT_RESERVE = 16;
	private static final int ICON_GAP = 1;
	private static final int TEXT_EDGE_PADDING = 4;
	private static final String ELLIPSIS = "...";
	private static final int HOVER_BAR_WIDTH = 3;
	private static final int OUTLINE_INSET = 1;
	private static final int MAX_ENTRY_LENGTH = 512;
	// Large enough that a big menu's entries all fit, so a full menu never thrashes the cache.
	private static final int SEGMENT_CACHE_SIZE = 256;
	private static final int MAX_ALPHA = 255;
	private static final double PERCENT = 100.0;

	// Drop shadow: SHADOW_LAYERS offset copies, fading out with distance.
	private static final int SHADOW_LAYERS = 3;
	private static final Color[] SHADOW_COLOURS = {
		new Color(0, 0, 0, 45), new Color(0, 0, 0, 30), new Color(0, 0, 0, 15)
	};

	private final Map<Integer, BufferedImage> modIconCache = new HashMap<>();
	private final Map<Integer, IndexedSprite> modIconSprites = new HashMap<>();
	private final Map<String, OptionSegments> optionCache = boundedCache();
	private final Map<String, List<Run>> targetCache = boundedCache();
	// Kept apart from targetCache so hiding combat levels never runs a regex per frame.
	private final Map<String, List<Run>> strippedTargetCache = boundedCache();
	private final RoundRectangle2D.Float menuShape = new RoundRectangle2D.Float();
	private final RoundRectangle2D.Float scratchShape = new RoundRectangle2D.Float();
	private final Rectangle boxBounds = new Rectangle();
	private final TargetColours targetColours = new TargetColours();

	// Derived from the theme, rebuilt only when it changes.
	private Theme theme;
	// The game pads some text with extra spaces that only line up in its own fonts, so the standard
	// fonts show each run of spaces as one. Parsed text depends on this, so the caches are cleared
	// when it flips.
	private boolean collapseSpaces;
	private Font font;
	private Font boldFont;
	private Color bgColour;
	private Color headerColour;
	private Color hoverColour;

	private String cachedRulesRaw;
	private Map<String, Color> cachedRules = Collections.emptyMap();

	// Set by prepare() for the current call; shared by drawing and measuring.
	private Client client;
	private Object modIconSource;
	private FontMetrics metrics;
	private FontMetrics highlightMetrics;
	private Map<String, Color> rules;
	private boolean boldHighlights;
	private boolean hideLevel;
	private int textOffsetX;
	/**
	 * @param client null when not on the client thread; {@code <img>} tags are then skipped
	 * @param localCombatLevel used to colour combat levels in Custom mode
	 */
	void render(Graphics2D graphics, Client client, Theme theme, RightClickStylerConfig config,
		List<Row> rows, Rectangle bounds, int hoverIndex, int localCombatLevel)
	{
		render(graphics, client, theme, config, rows, bounds, hoverIndex, localCombatLevel, HEADER_TEXT);
	}

	void render(Graphics2D graphics, Client client, Theme theme, RightClickStylerConfig config,
		List<Row> rows, Rectangle bounds, int hoverIndex, int localCombatLevel, String headerText)
	{
		render(graphics, client, theme, config, rows, bounds, hoverIndex,
			localCombatLevel, headerText, 0);
	}

	void render(Graphics2D graphics, Client client, Theme theme, RightClickStylerConfig config,
		List<Row> rows, Rectangle bounds, int hoverIndex, int localCombatLevel,
		String headerText, int scrollRows)
	{
		render(graphics, client, theme, config, rows, bounds, hoverIndex,
			localCombatLevel, headerText, null, scrollRows);
	}

	/**
	 * @param headerKind the target kind of a header that repeats the opening row's target, so
	 * its native target colour follows Custom target colours like that row; null for any other
	 * header, whose tags are drawn as written
	 */
	void render(Graphics2D graphics, Client client, Theme theme, RightClickStylerConfig config,
		List<Row> rows, Rectangle bounds, int hoverIndex, int localCombatLevel,
		String headerText, TargetKind headerKind, int scrollRows)
	{
		// Work on a copy so no colour/font/clip change leaks to other overlays or Swing children.
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			prepare(g, client, theme, config);
			targetColours.load(config, localCombatLevel);
			renderMenu(g, config, rows, bounds, hoverIndex, headerText, headerKind, scrollRows);
		}
		finally
		{
			g.dispose();
		}
	}

	private void prepare(Graphics2D graphics, Client client, Theme theme, RightClickStylerConfig config)
	{
		boolean themeChanged = theme != this.theme;
		if (themeChanged)
		{
			if (theme.font.isScalable() != collapseSpaces)
			{
				collapseSpaces = !collapseSpaces;
				optionCache.clear();
				targetCache.clear();
				strippedTargetCache.clear();
			}
			this.theme = theme;
			font = buildFont(theme.font, theme.fontSize);
			boldFont = buildBoldFont(theme.font, theme.fontSize);
			int alpha = (int) Math.round(theme.opacity * MAX_ALPHA / PERCENT);
			bgColour = ColorUtil.colorWithAlpha(theme.bg, alpha);
			headerColour = ColorUtil.colorWithAlpha(theme.header, alpha);
			hoverColour = ColorUtil.colorWithAlpha(theme.hover,
				(int) Math.round(theme.hoverOpacity * MAX_ALPHA / PERCENT));
		}
		Object currentIcons = client == null ? null : client.getModIcons();
		if (currentIcons != modIconSource)
		{
			modIconCache.clear();
			modIconSprites.clear();
			modIconSource = currentIcons;
		}
		this.client = client;
		metrics = graphics.getFontMetrics(font);

		boolean highlights = config.highlightsEnabled();
		boolean bold = highlights && config.highlightsBold();
		Map<String, Color> newRules = highlights ? rules(config.highlightRules()) : Collections.emptyMap();
		boolean hide = config.combatLevelMode() == CombatLevelMode.HIDE;
		int offset = Limits.textOffsetX(config);
		highlightMetrics = bold ? graphics.getFontMetrics(boldFont) : metrics;
		boldHighlights = bold;
		rules = newRules;
		hideLevel = hide;
		textOffsetX = offset;
	}

	private void renderMenu(Graphics2D graphics, RightClickStylerConfig config, List<Row> rows, Rectangle bounds,
		int hoverIndex, String headerText, TargetKind headerKind, int scrollRows)
	{
		int baselineNudge = Limits.baselineNudge(config);

		// Rows always sit on the game's click rows; hiding the header just trims the box above them.
		Rectangle box = bounds;
		if (!theme.showHeader)
		{
			box = boxBounds;
			box.setBounds(bounds.x, bounds.y + HEADER_HEIGHT, bounds.width, bounds.height - HEADER_HEIGHT);
		}

		drawShadow(graphics, box);
		Shape shape = menuShape(box);
		graphics.setColor(bgColour);
		graphics.fill(shape);

		Shape previousClip = graphics.getClip();
		graphics.clip(shape);
		if (theme.showHeader)
		{
			// Header and hover fills use source-over on the menu background. Each
			// fill's alpha compounds with the background where they overlap.
			graphics.setColor(headerColour);
			graphics.fillRect(bounds.x, bounds.y, bounds.width, HEADER_HEIGHT);
			graphics.setFont(font);
			drawHeader(graphics, headerText == null ? HEADER_TEXT : headerText,
				headerText == null ? null : headerKind, bounds,
				bounds.y + centreOffset(HEADER_HEIGHT, baselineNudge));
		}
		drawRows(graphics, config, rows, bounds, hoverIndex,
			bounds.y + HEADER_HEIGHT, baselineNudge, scrollRows);
		graphics.setClip(previousClip);

		drawBorder(graphics, box);
	}

	private void drawRows(Graphics2D graphics, RightClickStylerConfig config, List<Row> rows, Rectangle bounds,
		int hoverIndex, int firstRowY, int baselineNudge, int scrollRows)
	{
		boolean showHitRows = config.showHitRows();
		int rowTextOffsetY = centreOffset(ROW_HEIGHT, baselineNudge);
		Rectangle visible = graphics.getClipBounds();

		for (int rowIndex = scrollRows; rowIndex < rows.size(); rowIndex++)
		{
			int rowY = firstRowY + (rowIndex - scrollRows) * ROW_HEIGHT;
			if (visible != null && rowY >= visible.y + visible.height)
			{
				break;
			}
			boolean hovered = rowIndex == hoverIndex;
			if (hovered)
			{
				drawHover(graphics, bounds.x, rowY, bounds.width);
			}
			if (showHitRows)
			{
				graphics.setColor(HIT_ROW_COLOUR);
				graphics.drawRect(bounds.x, rowY, bounds.width - 1, ROW_HEIGHT - 1);
			}
			Row row = rows.get(rowIndex);
			int startX = rowStartX(bounds, row);
			int maxX = rowMaxX(bounds, row);
			int available = maxX - startX;
			int measured = layoutRow(null, row, 0, 0, Integer.MAX_VALUE, hovered);
			if (shouldCompress(available, measured))
			{
				// The game's rectangle was sized with its own font. Keep its click and submenu
				// geometry while fitting the selected font's complete row into that rectangle.
				Graphics2D fitted = (Graphics2D) graphics.create();
				try
				{
					fitted.translate(startX, 0);
					fitted.scale((double) available / measured, 1);
					keepRunScaleProportional(fitted);
					layoutRow(fitted, row, 0, rowY + rowTextOffsetY, measured, hovered);
				}
				finally
				{
					fitted.dispose();
				}
			}
			else
			{
				layoutRow(graphics, row, startX, rowY + rowTextOffsetY, maxX, hovered);
			}
			if (row.hasSubMenu)
			{
				int arrowX = bounds.x + bounds.width - 9;
				int arrowY = rowY + ROW_HEIGHT / 2;
				graphics.setColor(hovered ? theme.accent : theme.text);
				int tipX = arrowX + 4;
				graphics.drawLine(arrowX, arrowY - 4, tipX, arrowY);
				graphics.drawLine(tipX, arrowY, arrowX, arrowY + 4);
			}
		}
	}

	private int rowStartX(Rectangle bounds, Row row)
	{
		return bounds.x + textOffsetX;
	}

	private int rowMaxX(Rectangle bounds, Row row)
	{
		return row.hasSubMenu
			? bounds.x + bounds.width - Math.max(SUBMENU_RIGHT_RESERVE, textOffsetX) - TEXT_SHADOW_OFFSET
			: plainMaxX(bounds);
	}

	/** The right edge of text in a row without a right-hand submenu arrow, and in the header. */
	private int plainMaxX(Rectangle bounds)
	{
		return bounds.x + bounds.width - Math.max(TEXT_EDGE_PADDING, textOffsetX) - TEXT_SHADOW_OFFSET;
	}

	/**
	 * The RuneScape fonts are pixel fonts whose hinting snaps a horizontally scaled glyph to the
	 * next whole pixel size, so a fit of even 1px drew every glyph about 6% narrower while each run
	 * still started at its scaled position, opening gaps between option, target and coloured spans.
	 * Fractional metrics keep their advances at the scaled measured widths.
	 */
	private void keepRunScaleProportional(Graphics2D fitted)
	{
		if (!theme.font.isScalable())
		{
			fitted.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_ON);
		}
	}

	private static boolean shouldCompress(int available, int measured)
	{
		return available > 0 && measured > available;
	}

	/**
	 * Draws a row's option and target, or only measures them when {@code graphics} is null.
	 *
	 * @return the x position just after the row's content
	 */
	private int layoutRow(Graphics2D graphics, Row row, int startX, int textY, int maxX, boolean hovered)
	{
		OptionSegments option = optionSegments(row.option);
		Color highlight = rules.get(option.key);
		FontMetrics optionMetrics = highlight != null ? highlightMetrics : metrics;
		if (graphics != null)
		{
			graphics.setFont(optionMetrics.getFont());
		}

		int x = startX;
		boolean optionVisible = !option.plain.trim().isEmpty();
		if (!optionVisible)
		{
			for (Run run : option.runs)
			{
				if (run.iconIndex >= 0)
				{
					optionVisible = true;
					break;
				}
			}
		}
		if (optionVisible && hovered && theme.hoverStyle == HoverStyle.TEXT)
		{
			x += drawFittedRun(graphics, optionMetrics, option.plain, x, textY,
				theme.accent, maxX);
		}
		else if (optionVisible && highlight != null)
		{
			x += drawFittedRun(graphics, optionMetrics, option.plain, x, textY,
				highlight, maxX);
		}
		else if (optionVisible)
		{
			List<Run> runs = option.runs;
			for (int i = 0; i < runs.size(); i++)
			{
				if (x >= maxX)
				{
					return x;
				}
				Run run = runs.get(i);
				if (run.iconIndex >= 0)
				{
					int iconWidth = drawIcon(null, optionMetrics, run.iconIndex, x, textY);
					if (x + iconWidth > maxX)
					{
						return maxX;
					}
					x += drawIcon(graphics, optionMetrics, run.iconIndex, x, textY);
				}
				else
				{
					x += drawFittedRun(graphics, optionMetrics, run.text, x, textY,
						run.tagColour != null ? run.tagColour : theme.text, maxX);
				}
			}
		}

		if (row.target == null || row.target.isEmpty())
		{
			return x;
		}
		if (graphics != null)
		{
			graphics.setFont(font);
		}
		boolean targetOnly = x == startX;
		if (!targetOnly)
		{
			x += metrics.charWidth(' ');
		}
		List<Run> runs = targetRuns(row.target);
		for (int i = 0; i < runs.size(); i++)
		{
			if (x >= maxX)
			{
				return x;
			}
			Run run = runs.get(i);
			if (run.iconIndex >= 0)
			{
				int iconWidth = drawIcon(null, metrics, run.iconIndex, x, textY);
				if (x + iconWidth > maxX)
				{
					return maxX;
				}
				x += drawIcon(graphics, metrics, run.iconIndex, x, textY);
				targetOnly = false;
				continue;
			}
			String text = targetOnly ? run.text.stripLeading() : run.text;
			if (text.isEmpty())
			{
				continue;
			}
			Color colour = graphics != null ? targetColours.resolve(run, row.kind) : null;
			x += drawFittedRun(graphics, metrics, text, x, textY, colour, maxX);
			targetOnly = false;
		}
		return x;
	}

	private Map<String, Color> rules(String raw)
	{
		if (raw == null)
		{
			return Collections.emptyMap();
		}
		if (!raw.equals(cachedRulesRaw))
		{
			cachedRulesRaw = raw;
			cachedRules = HighlightRules.parseLookup(raw);
		}
		return cachedRules;
	}

	private Shape menuShape(Rectangle bounds)
	{
		if (theme.radius == 0)
		{
			return bounds;
		}
		menuShape.setRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, theme.radius, theme.radius);
		return menuShape;
	}

	private void drawShadow(Graphics2D graphics, Rectangle bounds)
	{
		if (!theme.showShadow)
		{
			return;
		}
		for (int i = SHADOW_LAYERS; i >= 1; i--)
		{
			scratchShape.setRoundRect(bounds.x + i, bounds.y + i, bounds.width, bounds.height, theme.radius, theme.radius);
			graphics.setColor(SHADOW_COLOURS[i - 1]);
			graphics.fill(scratchShape);
		}
	}

	private void drawBorder(Graphics2D graphics, Rectangle bounds)
	{
		if (!theme.showBorder)
		{
			return;
		}
		graphics.setColor(theme.border);
		if (theme.radius > 0)
		{
			scratchShape.setRoundRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1, theme.radius, theme.radius);
			graphics.draw(scratchShape);
		}
		else
		{
			graphics.drawRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
		}
	}

	private void drawHover(Graphics2D graphics, int x, int rowY, int width)
	{
		switch (theme.hoverStyle)
		{
			case FILL:
				graphics.setColor(hoverColour);
				graphics.fillRect(x, rowY, width, ROW_HEIGHT);
				break;
			case BAR:
				graphics.setColor(hoverColour);
				graphics.fillRect(x, rowY, width, ROW_HEIGHT);
				graphics.setColor(theme.accent);
				graphics.fillRect(x, rowY, HOVER_BAR_WIDTH, ROW_HEIGHT);
				break;
			case OUTLINE:
				graphics.setColor(theme.accent);
				graphics.drawRect(x + OUTLINE_INSET, rowY + OUTLINE_INSET,
					width - 1 - OUTLINE_INSET * 2, ROW_HEIGHT - 1 - OUTLINE_INSET * 2);
				break;
			case TEXT:
				// drawn as an accent-coloured option in layoutRow
				break;
			case NONE:
			default:
				break;
		}
	}

	private int centreOffset(int boxHeight, int nudge)
	{
		return (boxHeight - (metrics.getAscent() + metrics.getDescent())) / 2 + metrics.getAscent() + nudge;
	}

	/**
	 * The game draws its header at the same x as its rows, in a rectangle sized to fit it, so the
	 * header shares a plain row's text box and is fitted the same way when the selected font or
	 * text offset needs more room than that box.
	 */
	private void drawHeader(Graphics2D graphics, String raw, TargetKind kind, Rectangle bounds, int y)
	{
		if (raw.isEmpty())
		{
			return;
		}
		List<Run> runs = optionSegments(raw).runs;
		int startX = bounds.x + textOffsetX;
		int available = plainMaxX(bounds) - startX;
		if (available <= 0)
		{
			return;
		}
		int measured = layoutHeader(null, runs, kind, 0, y);
		if (shouldCompress(available, measured))
		{
			Graphics2D fitted = (Graphics2D) graphics.create();
			try
			{
				fitted.translate(startX, 0);
				fitted.scale((double) available / measured, 1);
				keepRunScaleProportional(fitted);
				layoutHeader(fitted, runs, kind, 0, y);
			}
			finally
			{
				fitted.dispose();
			}
		}
		else
		{
			layoutHeader(graphics, runs, kind, startX, y);
		}
	}

	/**
	 * Draws the header's runs, or only measures them when {@code graphics} is null.
	 *
	 * @return the header's width
	 */
	private int layoutHeader(Graphics2D graphics, List<Run> runs, TargetKind kind, int startX, int y)
	{
		int x = startX;
		for (Run run : runs)
		{
			x += run.iconIndex >= 0
				? drawIcon(graphics, metrics, run.iconIndex, x, y)
				: drawRun(graphics, metrics, run.text, x, y, graphics == null ? null : headerRunColour(run, kind));
		}
		return x - startX;
	}

	/**
	 * A target-derived header colours its tagged spans exactly as the opening row's target does,
	 * so a Custom target colour also reaches it. An untagged item target uses the Custom Item
	 * colour. Other untagged text, and headers that are not target text, keep the header colour.
	 */
	private Color headerRunColour(Run run, TargetKind kind)
	{
		if (run.tagColour == null)
		{
			return kind == TargetKind.ITEM && targetColours.targetMode == TargetMode.CUSTOM
				? targetColours.resolve(run, kind) : theme.headerText;
		}
		return kind == null ? run.tagColour : targetColours.resolve(run, kind);
	}

	private int drawFittedRun(Graphics2D graphics, FontMetrics fontMetrics,
		String text, int x, int y, Color colour, int maxX)
	{
		int available = maxX - x;
		if (text.isEmpty() || available <= 0)
		{
			return 0;
		}
		if (fontMetrics.stringWidth(text) <= available)
		{
			return drawRun(graphics, fontMetrics, text, x, y, colour);
		}
		int ellipsisWidth = fontMetrics.stringWidth(ELLIPSIS);
		if (ellipsisWidth <= available)
		{
			String visible = fitPrefix(text, fontMetrics, available - ellipsisWidth);
			drawRun(graphics, fontMetrics, visible + ELLIPSIS, x, y, colour);
		}
		return available;
	}

	private static String fitPrefix(String text, FontMetrics fontMetrics, int maxWidth)
	{
		if (maxWidth <= 0)
		{
			return "";
		}
		if (fontMetrics.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		int low = 0;
		int high = text.codePointCount(0, text.length());
		while (low < high)
		{
			int middle = (low + high + 1) >>> 1;
			int end = text.offsetByCodePoints(0, middle);
			if (fontMetrics.stringWidth(text.substring(0, end)) <= maxWidth)
			{
				low = middle;
			}
			else
			{
				high = middle - 1;
			}
		}
		return text.substring(0, text.offsetByCodePoints(0, low));
	}

	/**
	 * @return the run's width; nothing is drawn when {@code graphics} is null
	 */
	private int drawRun(Graphics2D graphics, FontMetrics fontMetrics, String text, int x, int y, Color colour)
	{
		if (text.isEmpty())
		{
			return 0;
		}
		if (graphics != null)
		{
			if (theme.textShadow)
			{
				graphics.setColor(TEXT_SHADOW_COLOUR);
				graphics.drawString(text, x + TEXT_SHADOW_OFFSET, y + TEXT_SHADOW_OFFSET);
			}
			graphics.setColor(colour);
			graphics.drawString(text, x, y);
		}
		return fontMetrics.stringWidth(text);
	}

	/**
	 * @return the icon's width plus spacing; nothing is drawn when {@code graphics} is null
	 */
	private int drawIcon(Graphics2D graphics, FontMetrics fontMetrics, int index, int x, int y)
	{
		BufferedImage icon = modIcon(index);
		if (icon == null)
		{
			return 0;
		}
		int height = Math.max(1, fontMetrics.getAscent());
		int width = Math.max(1, icon.getWidth() * height / icon.getHeight());
		if (graphics != null)
		{
			graphics.drawImage(icon, x, y - height, width, height, null);
		}
		return width + ICON_GAP;
	}

	private BufferedImage modIcon(int index)
	{
		IndexedSprite[] icons = client != null ? client.getModIcons() : null;
		IndexedSprite sprite = icons != null && index >= 0 && index < icons.length ? icons[index] : null;
		if (sprite == null)
		{
			modIconCache.remove(index);
			modIconSprites.remove(index);
			return null;
		}
		BufferedImage cached = modIconCache.get(index);
		if (cached != null && modIconSprites.get(index) == sprite)
		{
			return cached;
		}
		BufferedImage built = buildModIcon(sprite);
		if (built != null)
		{
			modIconCache.put(index, built);
			modIconSprites.put(index, sprite);
		}
		return built;
	}

	private static BufferedImage buildModIcon(IndexedSprite sprite)
	{
		int width = sprite.getWidth();
		int height = sprite.getHeight();
		byte[] pixels = sprite.getPixels();
		int[] palette = sprite.getPalette();
		if (width <= 0 || height <= 0 || pixels == null || palette == null)
		{
			return null;
		}
		int[] argb = new int[width * height];
		for (int i = 0; i < pixels.length && i < argb.length; i++)
		{
			int paletteIndex = pixels[i] & 0xFF;
			argb[i] = paletteIndex == 0 || paletteIndex >= palette.length ? 0 : (0xFF000000 | palette[paletteIndex]);
		}
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		image.setRGB(0, 0, width, height, argb, 0, width);
		return image;
	}

	static Font buildFont(FontChoice choice, int size)
	{
		if (choice.isScalable())
		{
			return new Font(choice.family, Font.PLAIN, size);
		}
		switch (choice)
		{
			case RS_SMALL:
				return FontManager.getRunescapeSmallFont();
			case RS_BOLD:
				return FontManager.getRunescapeBoldFont();
			case RS_REGULAR:
			default:
				return FontManager.getRunescapeFont();
		}
	}

	private static Font buildBoldFont(FontChoice choice, int size)
	{
		return choice.isScalable() ? new Font(choice.family, Font.BOLD, size) : FontManager.getRunescapeBoldFont();
	}

	private OptionSegments optionSegments(String raw)
	{
		String key = clean(raw);
		OptionSegments segments = optionCache.get(key);
		if (segments == null)
		{
			String plain = Text.removeTags(key);
			// Rules match the option as the game spells it, so only the displayed text is collapsed.
			segments = new OptionSegments(parseRuns(key), collapse(plain), plain.toLowerCase(Locale.ROOT).trim());
			optionCache.put(key, segments);
		}
		return segments;
	}

	private List<Run> targetRuns(String raw)
	{
		String key = clean(raw);
		Map<String, List<Run>> cache = hideLevel ? strippedTargetCache : targetCache;
		List<Run> runs = cache.get(key);
		if (runs == null)
		{
			runs = new ArrayList<>();
			for (Run run : parseRuns(hideLevel ? stripLevel(key) : key))
			{
				splitLevel(run, runs);
			}
			cache.put(key, runs);
		}
		return runs;
	}

	/**
	 * Each visible text run of a target paired with the colour a row of {@code kind} draws it
	 * in, in drawing order. Package-private so tests can check every span without a Graphics.
	 */
	List<Map.Entry<String, Color>> targetRunColours(RightClickStylerConfig config, String target,
		TargetKind kind, int localCombatLevel)
	{
		targetColours.load(config, localCombatLevel);
		List<Map.Entry<String, Color>> resolved = new ArrayList<>();
		for (Run run : targetRuns(target))
		{
			if (run.iconIndex < 0 && !run.text.trim().isEmpty())
			{
				resolved.add(new AbstractMap.SimpleImmutableEntry<>(run.text, targetColours.resolve(run, kind)));
			}
		}
		return resolved;
	}

	private static String clean(String raw)
	{
		return raw == null ? "" : Limits.truncate(raw, MAX_ENTRY_LENGTH);
	}

	/**
	 * Removes any {@code (level-N)} segment and the whitespace it leaves trailing the name.
	 */
	private static String stripLevel(String target)
	{
		Matcher matcher = LEVEL.matcher(target);
		if (!matcher.find())
		{
			return target;
		}
		return TRAILING_SPACE.matcher(matcher.replaceAll("")).replaceAll("");
	}

	/**
	 * Splits on {@code <col=..>}, {@code </col>} and {@code <img=N>} tags. Every other tag (and any
	 * unparseable one) is stripped, so unknown markup never shows up as literal text.
	 */
	private List<Run> parseRuns(String raw)
	{
		List<Run> runs = new ArrayList<>();
		Matcher matcher = TAG.matcher(raw);
		int last = 0;
		Color current = null;
		int colourSpan = -1;
		boolean uncolouredPrefix = false;
		// A colour tag only starts a new span once the current one has shown text, so a tag
		// that immediately replaces another (or follows only an icon) keeps the same span.
		boolean spanHasText = false;
		while (matcher.find())
		{
			if (matcher.start() > last)
			{
				String text = collapse(raw.substring(last, matcher.start()));
				runs.add(new Run(text, current, colourSpan));
				boolean visible = !text.trim().isEmpty();
				uncolouredPrefix |= colourSpan < 0 && visible;
				spanHasText |= colourSpan >= 0 && visible;
			}
			last = matcher.end();

			String inner = matcher.group(1);
			Matcher col = COL.matcher(inner);
			Matcher img = IMG.matcher(inner);
			if (col.matches())
			{
				current = new Color(Integer.parseInt(col.group(1), 16));
				if (colourSpan < 0)
				{
					colourSpan = uncolouredPrefix ? 1 : 0;
				}
				else if (spanHasText)
				{
					colourSpan++;
				}
				spanHasText = false;
			}
			else if (inner.equalsIgnoreCase(CLOSE_COL))
			{
				current = null;
			}
			else if (img.matches())
			{
				runs.add(Run.icon(Integer.parseInt(img.group(1))));
			}
		}
		if (last < raw.length())
		{
			runs.add(new Run(collapse(raw.substring(last)), current, colourSpan));
		}
		return runs;
	}

	private String collapse(String text)
	{
		return collapseSpaces ? WHITESPACE_RUN.matcher(text).replaceAll(" ") : text;
	}

	private static void splitLevel(Run run, List<Run> out)
	{
		if (run.iconIndex >= 0)
		{
			out.add(run);
			return;
		}
		Matcher matcher = LEVEL.matcher(run.text);
		int last = 0;
		while (matcher.find())
		{
			if (matcher.start() > last)
			{
				out.add(new Run(run.text.substring(last, matcher.start()), run.tagColour, run.colourSpan));
			}
			out.add(new Run(matcher.group(), run.tagColour, run.colourSpan,
				true, Integer.parseInt(matcher.group(1)), -1));
			last = matcher.end();
		}
		if (last == 0)
		{
			out.add(run);
		}
		else if (last < run.text.length())
		{
			out.add(new Run(run.text.substring(last), run.tagColour, run.colourSpan));
		}
	}

	private static <V> Map<String, V> boundedCache()
	{
		return new LinkedHashMap<String, V>(SEGMENT_CACHE_SIZE, 0.75f, true)
		{
			@Override
			protected boolean removeEldestEntry(Map.Entry<String, V> eldest)
			{
				return size() > SEGMENT_CACHE_SIZE;
			}
		};
	}

	/**
	 * One row to draw. The overlay builds these from real menu entries, the preview from fixed
	 * samples. {@code kind} drives Custom target colouring.
	 */
	static final class Row
	{
		private String option;
		private String target;
		private TargetKind kind;
		private boolean hasSubMenu;
		private boolean submenuOpensLeft;

		Row(String option, String target, TargetKind kind)
		{
			set(option, target, kind);
		}

		/**
		 * Lets the overlay reuse rows across frames instead of allocating them.
		 *
		 */
		void set(String option, String target, TargetKind kind)
		{
			this.option = option;
			this.target = target;
			this.kind = kind;
			this.hasSubMenu = false;
			this.submenuOpensLeft = false;
		}

		void set(String option, String target, TargetKind kind, boolean hasSubMenu, boolean opensLeft)
		{
			set(option, target, kind);
			this.hasSubMenu = hasSubMenu;
			this.submenuOpensLeft = opensLeft;
		}

		// Read by the submenu image cache, whose key is exactly what a row draws.
		String option()
		{
			return option;
		}

		String target()
		{
			return target;
		}

		TargetKind kind()
		{
			return kind;
		}

		/** Kind, submenu arrow and arrow side, packed for comparison. */
		int flags()
		{
			return (kind == null ? 7 : kind.ordinal()) << 2 | (hasSubMenu ? 2 : 0) | (submenuOpensLeft ? 1 : 0);
		}
	}

	enum TargetKind
	{
		NPC,
		PLAYER,
		ITEM,
		OBJECT,
		OTHER
	}

	/**
	 * Target colour settings, read from config once per render rather than once per text run.
	 */
	private static final class TargetColours
	{
		private TargetMode targetMode;
		private CombatLevelMode levelMode;
		private int localLevel;
		private Color npc;
		private Color player;
		private Color item;
		private Color object;
		private Color other;
		private Color lower;
		private Color same;
		private Color higher;

		private void load(RightClickStylerConfig config, int localCombatLevel)
		{
			targetMode = config.targetMode();
			levelMode = config.combatLevelMode();
			localLevel = localCombatLevel;
			if (targetMode == TargetMode.CUSTOM)
			{
				npc = config.npcColour();
				player = config.playerColour();
				item = config.itemColour();
				object = config.objectColour();
				other = config.otherColour();
			}
			if (levelMode == CombatLevelMode.CUSTOM)
			{
				lower = config.lowerLevelColour();
				same = config.sameLevelColour();
				higher = config.higherLevelColour();
			}
		}

		private Color resolve(Run run, TargetKind kind)
		{
			Color tagColour = run.tagColour != null ? run.tagColour : DEFAULT_TAG_COLOUR;
			if (run.isLevel)
			{
				if (levelMode == CombatLevelMode.CUSTOM)
				{
					return orDefault(run.level < localLevel ? lower : run.level > localLevel ? higher : same, tagColour);
				}
				return tagColour;
			}
			if (targetMode != TargetMode.CUSTOM)
			{
				return tagColour;
			}
			// Native target tags are the category defaults. A different colour, or a
			// later span within the target, is intentional formatting to preserve.
			if (run.tagColour != null && (run.colourSpan > 0
				|| !isNativeTargetColour(run.tagColour, kind)))
			{
				return run.tagColour;
			}
			switch (kind)
			{
				case NPC:
					return orDefault(npc, tagColour);
				case PLAYER:
					return orDefault(player, tagColour);
				case ITEM:
					return orDefault(item, tagColour);
				case OBJECT:
					return orDefault(object, tagColour);
				case OTHER:
				default:
					return orDefault(other, tagColour);
			}
		}

		private static boolean isNativeTargetColour(Color colour, TargetKind kind)
		{
			switch (kind)
			{
				case NPC:
					return DEFAULT_TAG_COLOUR.equals(colour);
				case PLAYER:
					return Color.WHITE.equals(colour);
				case ITEM:
					return NATIVE_ITEM_COLOUR.equals(colour);
				case OBJECT:
					return NATIVE_OBJECT_COLOUR.equals(colour);
				case OTHER:
				default:
					return DEFAULT_TAG_COLOUR.equals(colour) || Color.WHITE.equals(colour);
			}
		}

		private static Color orDefault(Color colour, Color fallback)
		{
			return colour != null ? colour : fallback;
		}
	}

	private static final class OptionSegments
	{
		private final List<Run> runs;
		private final String plain;
		private final String key;

		private OptionSegments(List<Run> runs, String plain, String key)
		{
			this.runs = runs;
			this.plain = plain;
			this.key = key;
		}
	}

	private static final class Run
	{
		private final String text;
		private final Color tagColour;
		private final int colourSpan;
		private final boolean isLevel;
		private final int level;
		private final int iconIndex;

		private Run(String text, Color tagColour, int colourSpan)
		{
			this(text, tagColour, colourSpan, false, 0, -1);
		}

		private Run(String text, Color tagColour, int colourSpan, boolean isLevel, int level, int iconIndex)
		{
			this.text = text;
			this.tagColour = tagColour;
			this.colourSpan = colourSpan;
			this.isLevel = isLevel;
			this.level = level;
			this.iconIndex = iconIndex;
		}

		private static Run icon(int index)
		{
			return new Run("", null, -1, false, 0, index);
		}
	}
}

package com.rightclickstyler;

import java.awt.Rectangle;
import java.util.Arrays;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import net.runelite.api.MenuEntry;

/**
 * Tells apart child menus that share one rectangle by what the native draw itself put in it.
 *
 * <p>The probe already proves that exactly one of several one-menu chains was drawn (exact
 * AMBIGUOUS, every explaining chain listed, none able to hide a grandchild), and that each
 * fills its whole rectangle and draws nothing else outside the root. Those chains differ only
 * in which menu native filled the shared rectangle with. Native draws a menu as a fixed
 * function of its size, its opener's text and each row's option, target and arrow, plus the
 * pointer's row highlight, which only turns a row's base text colour from white to yellow.
 * So a menu's native pixels, read in one frame where the probe proved it alone was drawn, are
 * what native draws for those contents in any later frame, except for yellow.
 *
 * <p>Each such image is remembered by those contents (never by position, entry identity or
 * hash). In an ambiguous frame, a remembered alternative whose image differs from the
 * captured pixels anywhere neither is yellow, while its header (identical by construction
 * among the alternatives) matches exactly, was not drawn. When every alternative but one is
 * excluded that way, and the remaining one matches its own image or has none, the remaining
 * one is the menu native drew. Anything short of that is inconclusive and stays native.
 */
final class NativeChildImages
{
	/** Opaque yellow: the native hover colour of a row's base text. */
	static final int HOVER_TEXT = 0xFFFF00;
	/** The native header bar and its text end above the first row's text. */
	static final int HEADER_BAND = 17;
	private static final int MAX_IMAGES = 16;
	private static final long MAX_STORED_PIXELS = 262_144;

	private final LinkedHashMap<Contents, int[]> images = new LinkedHashMap<>();
	private long storedPixels;

	void clear()
	{
		images.clear();
		storedPixels = 0;
	}

	int size()
	{
		return images.size();
	}

	/**
	 * Remembers candidate {@code candidate}'s native pixels from a frame where it alone was
	 * drawn in its rectangle: the exact reading resolved it, or {@link #identify} did.
	 */
	void remember(NativeSubmenuProbe.Result result, SubmenuTree tree, int candidate)
	{
		NativeSubmenuProbe.NativeCapture capture = result.framebufferVerified ? result.nativeCapture : null;
		int k = capture == null ? -1 : capture.indexOf(candidate);
		if (k < 0 || eligibility(tree, candidate, capture, k) != null)
		{
			return;
		}
		Rectangle r = capture.bounds(k);
		int[] image = new int[r.width * r.height];
		for (int dy = 0; dy < r.height; dy++)
		{
			for (int dx = 0; dx < r.width; dx++)
			{
				image[dy * r.width + dx] = capture.pixel(k, dx, dy) & 0xFFFFFF;
			}
		}
		Contents key = Contents.of(tree, candidate);
		int[] previous = images.remove(key);
		if (previous != null)
		{
			storedPixels -= previous.length;
		}
		images.put(key, image);
		storedPixels += image.length;
		Iterator<Map.Entry<Contents, int[]>> eldest = images.entrySet().iterator();
		while ((images.size() > MAX_IMAGES || storedPixels > MAX_STORED_PIXELS) && eldest.hasNext())
		{
			int[] dropped = eldest.next().getValue();
			if (dropped == image)
			{
				break;
			}
			storedPixels -= dropped.length;
			eldest.remove();
		}
	}

	/**
	 * The one alternative of an ambiguous frame that native drew, decided only by the native
	 * pixels; null when that is not proven.
	 *
	 * @param why diagnostics only: receives the reason when the result is null; may be null
	 */
	int[] identify(NativeSubmenuProbe.Result result, SubmenuTree tree, StringBuilder why)
	{
		ExactCoverageResolver.Outcome exact = result.exact;
		if (!result.framebufferVerified || exact == null
			|| exact.state != ExactCoverageResolver.State.AMBIGUOUS || exact.alternatives.length < 2
			|| exact.alternatives.length != exact.explainingChains)
		{
			return reject(why, "alternatives not exact");
		}
		NativeSubmenuProbe.NativeCapture capture = result.nativeCapture;
		if (capture == null)
		{
			return reject(why, "no native capture");
		}
		int[][] alternatives = exact.alternatives;
		boolean previousProved = false;
		Rectangle shared = null;
		String header = null;
		for (int[] alternative : alternatives)
		{
			if (alternative.length != 1 || alternative[0] < 0
				|| alternative[0] >= tree.candidateParents.size()
				|| tree.candidateParents.get(alternative[0]) != -1)
			{
				return reject(why, "alternative " + Arrays.toString(alternative) + " is not one root child");
			}
			previousProved |= Arrays.equals(alternative, result.activeChain);
			int candidate = alternative[0];
			int k = capture.indexOf(candidate);
			if (k < 0)
			{
				return reject(why, "candidate " + candidate + " not captured");
			}
			String ineligible = eligibility(tree, candidate, capture, k);
			if (ineligible != null)
			{
				return reject(why, "candidate " + candidate + " " + ineligible);
			}
			SubmenuTree.Node node = tree.nodes.get(candidate + 1);
			if (shared == null)
			{
				shared = node.bounds;
				header = Contents.openerHeader(tree, node);
			}
			else if (!shared.equals(node.bounds))
			{
				// Separate rectangles: each capture would also hold the other's pixels.
				return reject(why, "alternatives do not share one rectangle");
			}
			else if (!Objects.equals(header, Contents.openerHeader(tree, node)))
			{
				return reject(why, "alternative headers differ");
			}
		}
		if ((result.state == NativeSubmenuProbe.State.NO_CHILD
			|| result.state == NativeSubmenuProbe.State.ACTIVE) && !previousProved)
		{
			return reject(why, "previous resolver proved " + Arrays.toString(result.activeChain)
				+ ", not an alternative");
		}
		int remaining = -1;
		StringBuilder verdicts = why == null ? null : new StringBuilder();
		for (int i = 0; i < alternatives.length; i++)
		{
			int candidate = alternatives[i][0];
			int k = capture.indexOf(candidate);
			int[] image = images.get(Contents.of(tree, candidate));
			Verdict verdict = image == null ? Verdict.UNKNOWN : compare(capture, k, image);
			if (verdicts != null)
			{
				verdicts.append(verdicts.length() == 0 ? "" : " ").append('#').append(candidate)
					.append('=').append(verdict);
			}
			if (verdict == Verdict.STALE)
			{
				return reject(why, "#" + candidate + " remembered header differs from the native header");
			}
			if (verdict == Verdict.EXCLUDED)
			{
				continue;
			}
			if (remaining >= 0)
			{
				return reject(why, "more than one alternative fits the native pixels: " + verdicts);
			}
			remaining = i;
		}
		if (remaining < 0)
		{
			return reject(why, "no alternative fits the native pixels: " + verdicts);
		}
		return alternatives[remaining];
	}

	enum Verdict
	{
		UNKNOWN, MATCHES, EXCLUDED, STALE
	}

	/**
	 * Yellow is ignored on either side: it is the only colour the pointer changes. The header
	 * is compared exactly first, since every alternative draws the same header.
	 */
	private static Verdict compare(NativeSubmenuProbe.NativeCapture capture, int k, int[] image)
	{
		Rectangle r = capture.bounds(k);
		for (int dy = 0; dy < HEADER_BAND; dy++)
		{
			for (int dx = 0; dx < r.width; dx++)
			{
				if ((capture.pixel(k, dx, dy) & 0xFFFFFF) != image[dy * r.width + dx])
				{
					return Verdict.STALE;
				}
			}
		}
		for (int dy = HEADER_BAND; dy < r.height; dy++)
		{
			for (int dx = 0; dx < r.width; dx++)
			{
				int now = capture.pixel(k, dx, dy) & 0xFFFFFF;
				int then = image[dy * r.width + dx];
				if (now != then && now != HOVER_TEXT && then != HOVER_TEXT)
				{
					return Verdict.EXCLUDED;
				}
			}
		}
		return Verdict.MATCHES;
	}

	/**
	 * Null when the capture is a whole native draw of this menu at its natural height: every
	 * pixel on the canvas and outside the root, none left unwritten, and no submenu scroll.
	 */
	private static String eligibility(SubmenuTree tree, int candidate,
		NativeSubmenuProbe.NativeCapture capture, int k)
	{
		SubmenuTree.Node node = tree.nodes.get(candidate + 1);
		Rectangle r = capture.bounds(k);
		if (!r.equals(node.bounds) || node.entries.length == 0
			|| r.height != MenuRenderer.HEADER_HEIGHT + 3 + node.entries.length * MenuRenderer.ROW_HEIGHT)
		{
			return "not at its natural height";
		}
		for (int dy = 0; dy < r.height; dy++)
		{
			for (int dx = 0; dx < r.width; dx++)
			{
				if (!capture.usable(k, dx, dy))
				{
					return "partly off canvas or over the root";
				}
			}
		}
		return capture.painted(k) ? null : "not wholly drawn";
	}

	private static int[] reject(StringBuilder why, String reason)
	{
		if (why != null)
		{
			why.append(reason);
		}
		return null;
	}

	/** Everything native draws a child menu from, apart from its position and the pointer. */
	static final class Contents
	{
		private final int width;
		private final int height;
		private final String header;
		private final String[] options;
		private final String[] targets;
		private final boolean[] submenus;

		private Contents(int width, int height, String header, String[] options, String[] targets,
			boolean[] submenus)
		{
			this.width = width;
			this.height = height;
			this.header = header;
			this.options = options;
			this.targets = targets;
			this.submenus = submenus;
		}

		static Contents of(SubmenuTree tree, int candidate)
		{
			SubmenuTree.Node node = tree.nodes.get(candidate + 1);
			int count = node.entries.length;
			String[] options = new String[count];
			String[] targets = new String[count];
			boolean[] submenus = new boolean[count];
			for (int i = 0; i < count; i++)
			{
				MenuEntry entry = node.entries[i];
				options[i] = entry == null ? null : entry.getOption();
				targets[i] = entry == null ? null : entry.getTarget();
				submenus[i] = node.childFlags[i];
			}
			return new Contents(node.bounds.width, node.bounds.height, openerHeader(tree, node),
				options, targets, submenus);
		}

		/** The opening entry's target: the text native heads a child menu with. */
		static String openerHeader(SubmenuTree tree, SubmenuTree.Node node)
		{
			MenuEntry opener = tree.nodes.get(node.parentNode).entries[node.parentEntryIndex];
			return opener == null ? null : opener.getTarget();
		}

		@Override
		public boolean equals(Object o)
		{
			if (!(o instanceof Contents))
			{
				return false;
			}
			Contents c = (Contents) o;
			return width == c.width && height == c.height && Objects.equals(header, c.header)
				&& Arrays.equals(options, c.options) && Arrays.equals(targets, c.targets)
				&& Arrays.equals(submenus, c.submenus);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(width, height, header, Arrays.hashCode(options), Arrays.hashCode(targets),
				Arrays.hashCode(submenus));
		}
	}
}

package com.rightclickstyler;

import java.awt.Rectangle;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.BufferProvider;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.Rasterizer;

/** Native menu draw probe. Every framebuffer write is undone in finally. */
final class NativeSubmenuProbe
{
	private static final int SENTINEL = 0x13579BDF;
	private static final int MARGIN = 2;
	private static final int EDGE_TOLERANCE = 3;
	private static final long MAX_FOOTPRINT_SCAN_PIXELS = 1_048_576;
	// At most 8 MiB of exclusive witness positions, plus bounded shared storage.
	private static final long MAX_CANDIDATE_AREA_PIXELS = 2_097_152;
	private int[] snapshot = new int[0];

	/** Test hook: every scratch mask is back to zero between passes. */
	boolean scratchClean()
	{
		for (byte b : footprintMask)
		{
			if (b != 0)
			{
				return false;
			}
		}
		return exactResolver.maskClean();
	}

	private short[] overlapCoverage = new short[0];
	private byte[] footprintMask = new byte[0];
	private int[] footprintPositions = new int[0];
	private int[] changedFootprint = new int[0];
	private final int[] segments = new int[4];
	private int[] exclusivePool = new int[0];
	private int[] sharedPool = new int[0];
	private int lastVisibleCandidates;
	private long lastCandidatePixels;
	private final ExactCoverageResolver exactResolver = new ExactCoverageResolver();
	private ExactCoverageResolver.Outcome lastExact = ExactCoverageResolver.Outcome.NOT_EVALUATED;
	private boolean lastFramebufferVerified;
	/** Bounded like the candidate area: at most a few child rectangles are copied. */
	private static final long MAX_CAPTURE_PIXELS = 1_048_576;
	private int[] capturePool = new int[0];
	private NativeCapture lastCapture;

	Result probe(Client client, SubmenuTree tree)
	{
		Rasterizer raster = client.getRasterizer();
		BufferProvider provider = client.getBufferProvider();
		if (raster == null || provider == null)
		{
			return Result.failure(State.UNSUPPORTED, "raster/provider mismatch");
		}
		int[] pixels = raster.getPixels();
		int width = raster.getWidth();
		int height = raster.getHeight();
		if (pixels == null || pixels != provider.getPixels()
			|| width != provider.getWidth() || height != provider.getHeight()
			|| width <= 0 || height <= 0 || (long) width * height > pixels.length)
		{
			return Result.failure(State.UNSUPPORTED, "raster/provider mismatch");
		}
		Result result = samplePixels(pixels, width, height, tree,
			() -> client.drawOriginalMenu(255));
		Rasterizer afterRaster = client.getRasterizer();
		BufferProvider afterProvider = client.getBufferProvider();
		if (afterRaster == null || afterProvider == null || afterRaster.getPixels() != pixels
			|| afterProvider.getPixels() != pixels || afterRaster.getWidth() != width
			|| afterRaster.getHeight() != height || afterProvider.getWidth() != width
			|| afterProvider.getHeight() != height)
		{
			Result failure = Result.failure(State.FAILURE, "buffer identity or dimensions changed during draw");
			failure.drawPasses = result.drawPasses;
			failure.visibleCandidates = result.visibleCandidates;
			failure.candidatePixels = result.candidatePixels;
			return failure;
		}
		return result;
	}

	/** Also used by isolated synthetic tests. */
	static Result probePixels(int[] pixels, int width, int height, SubmenuTree tree, Runnable nativeDraw)
	{
		return new NativeSubmenuProbe().samplePixels(pixels, width, height, tree, nativeDraw);
	}

	Result samplePixels(int[] pixels, int width, int height, SubmenuTree tree, Runnable nativeDraw)
	{
		Result result = samplePixelsPass(pixels, width, height, tree, nativeDraw);
		result.visibleCandidates = lastVisibleCandidates;
		result.candidatePixels = lastCandidatePixels;
		result.exact = lastExact;
		result.framebufferVerified = lastFramebufferVerified;
		result.nativeCapture = lastFramebufferVerified ? lastCapture : null;
		return result;
	}

	private Result samplePixelsPass(int[] pixels, int width, int height,
		SubmenuTree tree, Runnable nativeDraw)
	{
		lastVisibleCandidates = 0;
		lastCandidatePixels = 0;
		lastExact = ExactCoverageResolver.Outcome.NOT_EVALUATED;
		lastFramebufferVerified = false;
		lastCapture = null;
		if (pixels == null || width <= 0 || height <= 0 || (long) width * height > pixels.length)
		{
			return Result.failure(State.UNSUPPORTED, "invalid framebuffer");
		}
		List<Rectangle> candidates = tree.candidateBounds;
		Rectangle canvas = new Rectangle(0, 0, width, height);
		Rectangle root = tree.nodes.get(0).bounds.intersection(canvas);
		int[] visibleCandidates = new int[candidates.size()];
		int visibleCount = 0;
		long totalVisibleArea = 0;
		for (int i = 0; i < candidates.size(); i++)
		{
			Rectangle child = candidates.get(i).intersection(canvas);
			if (child.width > 0 && child.height > 0)
			{
				totalVisibleArea += (long) child.width * child.height;
				if (totalVisibleArea > MAX_CANDIDATE_AREA_PIXELS)
				{
					return Result.failure(State.UNSUPPORTED, "candidate pixel area limit exceeded area="
						+ totalVisibleArea + " limit=" + MAX_CANDIDATE_AREA_PIXELS);
				}
				visibleCandidates[visibleCount++] = i;
			}
		}
		lastVisibleCandidates = visibleCount;
		lastCandidatePixels = totalVisibleArea;
		if (overlapCoverage.length != pixels.length)
		{
			overlapCoverage = new short[pixels.length];
		}
		// A root-only frame reads coverage only inside the root. Avoid clearing
		// the entire framebuffer when every child has dormant or offscreen bounds.
		if (visibleCount > 0)
		{
			Arrays.fill(overlapCoverage, (short) 0);
		}
		else
		{
			clearCoverage(overlapCoverage, width, root.x, root.y,
				root.x + root.width, root.y + root.height);
		}
		for (int j = 0; j < visibleCount; j++)
		{
			Rectangle r = candidates.get(visibleCandidates[j]);
			int left = Math.max(0, r.x - MARGIN);
			int top = Math.max(0, r.y - MARGIN);
			int right = Math.min(width, r.x + r.width + MARGIN);
			int bottom = Math.min(height, r.y + r.height + MARGIN);
			for (int y = top; y < bottom; y++)
			{
				int position = y * width + left;
				for (int x = left; x < right; x++)
				{
					overlapCoverage[position++]++;
				}
			}
		}
		int[] counts = new int[candidates.size()];
		int[] changes = new int[candidates.size()];
		int[] sharedCounts = new int[candidates.size()];
		int[] sharedChanges = new int[candidates.size()];
		boolean[] dormant = new boolean[candidates.size()];
		boolean complex = false;
		long candidateArea = 0;
		// Every candidate's exclusive (and shared) positions live contiguously in one retained
		// pool, candidate i at [from[i], from[i] + count[i]).
		int[] exclusiveFrom = new int[candidates.size()];
		int[] sharedFrom = new int[candidates.size()];
		int exclusiveUsed = 0;
		int sharedUsed = 0;
		for (int i = 0; i < candidates.size(); i++)
		{
			Rectangle nativeBounds = candidates.get(i);
			Rectangle child = nativeBounds.intersection(canvas);
			if (nativeBounds.width == 0 || nativeBounds.height == 0
				|| child.width <= 0 || child.height <= 0)
			{
				dormant[i] = true;
				continue;
			}
			// Reserve this candidate's upper bound (every position it scans) before scanning, so
			// the inner loop has no call and works on locals. The pool then holds the actual
			// exclusive positions so far (at most one per pixel) plus one candidate's area.
			long bound = 0;
			for (int y = child.y + MARGIN; y < child.y + child.height - MARGIN; y++)
			{
				int parts = ExactCoverageResolver.outsideRoot(root, MARGIN, y,
					child.x + MARGIN, child.x + child.width - MARGIN, segments);
				for (int s = 0; s < parts; s++)
				{
					bound += segments[2 * s + 1] - segments[2 * s];
				}
			}
			if (exclusiveUsed + bound > exclusivePool.length)
			{
				exclusivePool = grow(exclusivePool, exclusiveUsed + bound, 2L * pixels.length);
			}
			int[] pool = exclusivePool;
			short[] coverage = overlapCoverage;
			int from = exclusiveUsed;
			int n = from;
			for (int y = child.y + MARGIN; y < child.y + child.height - MARGIN; y++)
			{
				int row = y * width;
				int parts = ExactCoverageResolver.outsideRoot(root, MARGIN, y,
					child.x + MARGIN, child.x + child.width - MARGIN, segments);
				for (int s = 0; s < parts; s++)
				{
					int to = segments[2 * s + 1];
					for (int x = segments[2 * s]; x < to; x++)
					{
						if (coverage[row + x] == 1)
						{
							pool[n++] = row + x;
						}
					}
				}
			}
			exclusiveUsed = n;
			exclusiveFrom[i] = from;
			counts[i] = n - from;
			if (counts[i] == 0)
			{
				complex = true;
				// Overlapping siblings can have no exclusive pixels. Sample their visible
				// area outside the root to prove a dormant child was not drawn.
				int insetX = Math.min(MARGIN, (child.width - 1) / 2);
				int insetY = Math.min(MARGIN, (child.height - 1) / 2);
				// Count first (per row, from the segment ends), reserve once, then fill.
				long needed = 0;
				for (int y = child.y + insetY; y < child.y + child.height - insetY; y++)
				{
					int parts = ExactCoverageResolver.outsideRoot(root, MARGIN, y,
						child.x + insetX, child.x + child.width - insetX, segments);
					for (int s = 0; s < parts; s++)
					{
						needed += segments[2 * s + 1] - segments[2 * s];
					}
				}
				if (sharedUsed + needed > sharedPool.length)
				{
					// Bounded: the visible candidate area is at most MAX_CANDIDATE_AREA_PIXELS.
					sharedPool = grow(sharedPool, sharedUsed + needed, MAX_CANDIDATE_AREA_PIXELS);
				}
				int[] shared = sharedPool;
				int sharedStart = sharedUsed;
				int m = sharedStart;
				for (int y = child.y + insetY; y < child.y + child.height - insetY; y++)
				{
					int row = y * width;
					int parts = ExactCoverageResolver.outsideRoot(root, MARGIN, y,
						child.x + insetX, child.x + child.width - insetX, segments);
					for (int s = 0; s < parts; s++)
					{
						int to = segments[2 * s + 1];
						for (int x = segments[2 * s]; x < to; x++)
						{
							shared[m++] = row + x;
						}
					}
				}
				sharedUsed = m;
				sharedFrom[i] = sharedStart;
				sharedCounts[i] = m - sharedStart;
			}
			candidateArea += (long) child.width * child.height;
		}
		// Read only after the scan, so a pool that grew mid-scan is referenced in its final form.
		int[] exclusiveList = exclusivePool;
		int[] sharedList = sharedPool;
		boolean footprintEnabled = complex && candidateArea <= MAX_FOOTPRINT_SCAN_PIXELS;
		int[] visibleArea = null;
		int[] visibleMinX = null;
		int[] visibleMinY = null;
		int[] visibleMaxX = null;
		int[] visibleMaxY = null;
		if (footprintEnabled)
		{
			visibleArea = new int[candidates.size()];
			visibleMinX = new int[candidates.size()];
			visibleMinY = new int[candidates.size()];
			visibleMaxX = new int[candidates.size()];
			visibleMaxY = new int[candidates.size()];
			Arrays.fill(visibleMinX, width);
			Arrays.fill(visibleMinY, height);
			Arrays.fill(visibleMaxX, -1);
			Arrays.fill(visibleMaxY, -1);
			int capacity = (int) Math.min(pixels.length, candidateArea);
			if (footprintMask.length != pixels.length)
			{
				footprintMask = new byte[pixels.length];
			}
			if (footprintPositions.length < capacity)
			{
				// Grow by half again (to at most one position per pixel), so a run of slightly
				// larger menus does not reallocate on each one.
				int grown = (int) Math.min(pixels.length,
					Math.max(capacity, footprintPositions.length + (long) footprintPositions.length / 2));
				footprintPositions = new int[grown];
				changedFootprint = new int[grown];
			}
		}

		if (snapshot.length != pixels.length)
		{
			snapshot = new int[pixels.length];
		}
		int[] before = snapshot;
		System.arraycopy(pixels, 0, before, 0, pixels.length);
		int rootWitness = 0;
		int rootChanged = 0;
		int footprintCount = 0;
		int footprintChanged = 0;
		boolean restored;
		try
		{
			for (int y = root.y; y < root.y + root.height; y++)
			{
				for (int x = root.x; x < root.x + root.width; x++)
				{
					if (overlapCoverage[y * width + x] == 0)
					{
						pixels[y * width + x] = SENTINEL;
						rootWitness++;
					}
				}
			}
			// A shared sample is candidate i's inset visible area outside the root, the exact
			// region the footprint marking below writes for every non-dormant candidate, so
			// when footprint marking runs these writes would be repeated before the native draw.
			boolean writeShared = !footprintEnabled;
			for (int i = 0; i < candidates.size(); i++)
			{
				for (int j = exclusiveFrom[i], end = j + counts[i]; j < end; j++)
				{
					pixels[exclusiveList[j]] = SENTINEL;
				}
				if (writeShared)
				{
					for (int j = sharedFrom[i], end = j + sharedCounts[i]; j < end; j++)
					{
						pixels[sharedList[j]] = SENTINEL;
					}
				}
			}
			if (footprintEnabled)
			{
				// One marker over the union, so overlap never counts as evidence
				// for a particular child. This uses the existing native draw.
				for (int i = 0; i < candidates.size(); i++)
				{
					if (dormant[i])
					{
						continue;
					}
					Rectangle child = candidates.get(i).intersection(canvas);
					int insetX = Math.min(MARGIN, (child.width - 1) / 2);
					int insetY = Math.min(MARGIN, (child.height - 1) / 2);
					// Per row, the visible area and bounds come from the segment ends (the
					// per-pixel min/max of the same x and y values).
					int area = 0;
					int minX = visibleMinX[i];
					int minY = visibleMinY[i];
					int maxX = visibleMaxX[i];
					int maxY = visibleMaxY[i];
					for (int y = child.y + insetY; y < child.y + child.height - insetY; y++)
					{
						int row = y * width;
						int parts = ExactCoverageResolver.outsideRoot(root, MARGIN, y,
							child.x + insetX, child.x + child.width - insetX, segments);
						for (int s = 0; s < parts; s++)
						{
							int from = segments[2 * s];
							int to = segments[2 * s + 1];
							area += to - from;
							minX = Math.min(minX, from);
							maxX = Math.max(maxX, to - 1);
							minY = Math.min(minY, y);
							maxY = Math.max(maxY, y);
							for (int x = from; x < to; x++)
							{
								int position = row + x;
								if (footprintMask[position] == 0)
								{
									footprintMask[position] = 1;
									footprintPositions[footprintCount++] = position;
									pixels[position] = SENTINEL;
								}
							}
						}
					}
					visibleArea[i] += area;
					visibleMinX[i] = minX;
					visibleMinY[i] = minY;
					visibleMaxX[i] = maxX;
					visibleMaxY[i] = maxY;
				}
			}
			nativeDraw.run();
			for (int y = root.y; y < root.y + root.height; y++)
			{
				for (int x = root.x; x < root.x + root.width; x++)
				{
					if (overlapCoverage[y * width + x] == 0
						&& pixels[y * width + x] != SENTINEL)
					{
						rootChanged++;
					}
				}
			}
			for (int i = 0; i < candidates.size(); i++)
			{
				for (int j = exclusiveFrom[i], end = j + counts[i]; j < end; j++)
				{
					if (pixels[exclusiveList[j]] != SENTINEL)
					{
						changes[i]++;
					}
				}
				for (int j = sharedFrom[i], end = j + sharedCounts[i]; j < end; j++)
				{
					if (pixels[sharedList[j]] != SENTINEL)
					{
						sharedChanges[i]++;
					}
				}
			}
			if (footprintEnabled)
			{
				for (int i = 0; i < footprintCount; i++)
				{
					int position = footprintPositions[i];
					if (pixels[position] != SENTINEL)
					{
						changedFootprint[footprintChanged++] = position;
					}
				}
			}
			if (rootChanged > 0)
			{
				// Reads the marked pixels before the restore; it cannot throw or write pixels.
				int[][] positions;
				int[] sizes;
				if (footprintEnabled)
				{
					// With footprint marking on, the footprint list already holds every marked
					// position outside the root, each once. For a non-dormant candidate its
					// exclusive positions lie in its MARGIN-inset area (inset >= the footprint's
					// min(MARGIN, (size - 1) / 2)), and its shared positions are exactly its
					// footprint area; dormant candidates mark nothing. The resolver reads its
					// input only as a set, so the outcome is the same.
					positions = new int[][]{footprintPositions};
					sizes = new int[]{footprintCount};
				}
				else
				{
					positions = new int[][]{exclusiveList, sharedList, footprintPositions};
					sizes = new int[]{exclusiveUsed, sharedUsed, footprintCount};
				}
				lastExact = exactResolver.resolve(pixels, width, height, SENTINEL, root, MARGIN,
					candidates, tree.candidateParents, dormant, positions, sizes);
				// Still before the restore: the native draw's own pixels for the child menus the
				// reading proved or could not tell apart. Copying cannot throw or write pixels.
				lastCapture = captureNative(pixels, width, height, root, candidates, lastExact);
			}
		}
		finally
		{
			System.arraycopy(before, 0, pixels, 0, before.length);
			for (int i = 0; i < footprintCount; i++)
			{
				footprintMask[footprintPositions[i]] = 0;
			}
			restored = Arrays.equals(before, pixels);
		}
		if (restored)
		{
			if (geometryChanged(tree.nodes.get(0).menu, tree.nodes.get(0).bounds))
			{
				return Result.afterDraw(State.GEOMETRY_CHANGED, "root geometry changed during probe",
					counts, changes, sharedCounts, sharedChanges, true);
			}
			for (int i = 0; i < candidates.size(); i++)
			{
				if (geometryChanged(tree.nodes.get(i + 1).menu, candidates.get(i)))
				{
					return Result.afterDraw(State.GEOMETRY_CHANGED, "child geometry changed during probe",
						counts, changes, sharedCounts, sharedChanges, true);
				}
			}
		}
		if (!restored || rootWitness == 0 || rootChanged == 0)
		{
			return Result.afterDraw(!restored ? State.FAILURE
				: rootWitness == 0 ? State.AMBIGUOUS : State.FAILURE,
				!restored ? "framebuffer restoration failed"
					: rootWitness == 0 ? "ambiguous root geometry" : "native draw missed buffer",
				counts, changes, sharedCounts, sharedChanges, restored);
		}
		// Restored exactly, every rectangle unchanged by the draw, and the draw reached the
		// marked root: the evidence describes this frame. Every result below is a reading of it.
		lastFramebufferVerified = true;
		int[] chain = activeChain(tree.candidateParents, changes);
		if (chain == null)
		{
			if (footprintEnabled)
			{
				FootprintResolution footprint = resolveFootprint(width, tree, dormant,
					visibleArea, visibleMinX, visibleMinY, visibleMaxX, visibleMaxY,
					footprintChanged);
				if (footprint.matches == 1 && matchesExclusiveEvidence(footprint.chain, changes))
				{
					return new Result(footprint.chain.length == 0 ? State.NO_CHILD : State.ACTIVE,
						"footprint matched", footprint.chain, counts, changes, sharedCounts, sharedChanges, true)
						.withFootprint(footprint);
				}
				return Result.afterDraw(State.AMBIGUOUS, "ambiguous detection footprintMatches="
					+ footprint.matches, counts, changes, sharedCounts, sharedChanges, true)
					.withFootprint(footprint);
			}
			return Result.afterDraw(State.AMBIGUOUS, "ambiguous detection",
				counts, changes, sharedCounts, sharedChanges, true);
		}
		int unresolved = -1;
		for (int i = 0; i < candidates.size(); i++)
		{
			if (!dormant[i] && counts[i] == 0 && couldBeOnChain(i, tree.candidateParents, chain)
				&& (sharedCounts[i] == 0 || sharedChanges[i] > 0))
			{
				unresolved = i;
				break;
			}
		}
		if (unresolved >= 0)
		{
			if (!footprintEnabled)
			{
				return Result.afterDraw(State.AMBIGUOUS, "footprint scan limit exceeded",
					counts, changes, sharedCounts, sharedChanges, true);
			}
			FootprintResolution footprint = resolveFootprint(width, tree, dormant,
				visibleArea, visibleMinX, visibleMinY, visibleMaxX, visibleMaxY,
				footprintChanged);
			if (footprint.matches == 1 && matchesExclusiveEvidence(footprint.chain, changes))
			{
				return new Result(footprint.chain.length == 0 ? State.NO_CHILD : State.ACTIVE,
					"footprint matched", footprint.chain, counts, changes, sharedCounts, sharedChanges, true)
					.withFootprint(footprint);
			}
			return Result.afterDraw(State.AMBIGUOUS, "ambiguous geometry index=" + unresolved
				+ " bounds=" + candidates.get(unresolved) + " shared=" + sharedCounts[unresolved]
				+ " changed=" + sharedChanges[unresolved] + " footprintMatches=" + footprint.matches,
				counts, changes, sharedCounts, sharedChanges, true).withFootprint(footprint);
		}
		return new Result(chain.length == 0 ? State.NO_CHILD : State.ACTIVE,
			"sampled", chain, counts, changes, sharedCounts, sharedChanges, true);
	}

	/**
	 * Copies the native draw's pixels of each one-menu chain the exact reading resolved (one) or
	 * listed as an alternative (several): the evidence {@link NativeChildImages} compares. Longer
	 * chains are not captured, since a deeper menu overdraws its parent.
	 */
	private NativeCapture captureNative(int[] pixels, int width, int height, Rectangle root,
		List<Rectangle> candidates, ExactCoverageResolver.Outcome exact)
	{
		int[] wanted;
		if (exact.state == ExactCoverageResolver.State.RESOLVED && exact.chain.length == 1)
		{
			wanted = new int[]{exact.chain[0]};
		}
		else if (exact.state == ExactCoverageResolver.State.AMBIGUOUS && exact.alternatives.length >= 2)
		{
			wanted = new int[exact.alternatives.length];
			for (int i = 0; i < wanted.length; i++)
			{
				if (exact.alternatives[i].length != 1)
				{
					return null;
				}
				wanted[i] = exact.alternatives[i][0];
			}
		}
		else
		{
			return null;
		}
		long total = 0;
		for (int candidate : wanted)
		{
			Rectangle r = candidates.get(candidate);
			total += (long) r.width * r.height;
		}
		if (total > MAX_CAPTURE_PIXELS)
		{
			return null;
		}
		if (capturePool.length < total)
		{
			capturePool = new int[(int) total];
		}
		int[] offsets = new int[wanted.length];
		Rectangle[] bounds = new Rectangle[wanted.length];
		int offset = 0;
		for (int k = 0; k < wanted.length; k++)
		{
			Rectangle r = new Rectangle(candidates.get(wanted[k]));
			bounds[k] = r;
			offsets[k] = offset;
			Arrays.fill(capturePool, offset, offset + r.width * r.height, 0);
			int fromX = Math.max(0, r.x);
			int toX = Math.min(width, r.x + r.width);
			for (int y = Math.max(0, r.y); y < Math.min(height, r.y + r.height) && fromX < toX; y++)
			{
				System.arraycopy(pixels, y * width + fromX, capturePool,
					offset + (y - r.y) * r.width + (fromX - r.x), toX - fromX);
			}
			offset += r.width * r.height;
		}
		return new NativeCapture(capturePool, wanted, offsets, bounds, new Rectangle(root), width, height);
	}

	/**
	 * The native draw's pixels of some child rectangles, read after the draw and before the
	 * restore. It shares the probe's pool, so it is valid only until the next probe.
	 */
	static final class NativeCapture
	{
		private final int[] pool;
		private final int[] candidates;
		private final int[] offsets;
		private final Rectangle[] bounds;
		private final Rectangle root;
		private final int canvasWidth;
		private final int canvasHeight;

		private NativeCapture(int[] pool, int[] candidates, int[] offsets, Rectangle[] bounds,
			Rectangle root, int canvasWidth, int canvasHeight)
		{
			this.pool = pool;
			this.candidates = candidates;
			this.offsets = offsets;
			this.bounds = bounds;
			this.root = root;
			this.canvasWidth = canvasWidth;
			this.canvasHeight = canvasHeight;
		}

		/** The capture index of a candidate, or -1. */
		int indexOf(int candidate)
		{
			for (int k = 0; k < candidates.length; k++)
			{
				if (candidates[k] == candidate)
				{
					return k;
				}
			}
			return -1;
		}

		Rectangle bounds(int k)
		{
			return bounds[k];
		}

		/**
		 * The pixel at {@code (dx, dy)} inside capture {@code k}'s rectangle drew only that menu:
		 * on the canvas and outside the root, which native fills and writes only within its own
		 * rectangle.
		 */
		boolean usable(int k, int dx, int dy)
		{
			int x = bounds[k].x + dx;
			int y = bounds[k].y + dy;
			return x >= 0 && y >= 0 && x < canvasWidth && y < canvasHeight && !root.contains(x, y);
		}

		int pixel(int k, int dx, int dy)
		{
			return pool[offsets[k] + dy * bounds[k].width + dx];
		}

		/** Every usable pixel was written by the native draw (none still holds the sentinel). */
		boolean painted(int k)
		{
			Rectangle r = bounds[k];
			for (int dy = 0; dy < r.height; dy++)
			{
				for (int dx = 0; dx < r.width; dx++)
				{
					if (usable(k, dx, dy) && pixel(k, dx, dy) == SENTINEL)
					{
						return false;
					}
				}
			}
			return true;
		}
	}

	/** Pool growth: at least {@code needed}, otherwise doubling, never past {@code cap}. */
	private static int[] grow(int[] pool, long needed, long cap)
	{
		long size = Math.max(needed, Math.min(cap, Math.max(4096L, 2L * pool.length)));
		return Arrays.copyOf(pool, (int) size);
	}

	private static void clearCoverage(short[] coverage, int width,
		int left, int top, int right, int bottom)
	{
		if (right <= left || bottom <= top)
		{
			return;
		}
		for (int y = top; y < bottom; y++)
		{
			Arrays.fill(coverage, y * width + left, y * width + right, (short) 0);
		}
	}

	private static boolean geometryChanged(Menu menu, Rectangle bounds)
	{
		return menu.getMenuX() != bounds.x || menu.getMenuY() != bounds.y
			|| menu.getMenuWidth() != bounds.width || menu.getMenuHeight() != bounds.height;
	}

	private static boolean couldBeOnChain(int candidate, List<Integer> parents, int[] chain)
	{
		int parent = parents.get(candidate);
		if (parent < 0)
		{
			return chain.length == 0 || chain[0] == candidate;
		}
		for (int depth = 0; depth < chain.length; depth++)
		{
			if (chain[depth] == parent)
			{
				return depth + 1 == chain.length || chain[depth + 1] == candidate;
			}
		}
		return false;
	}

	private static boolean matchesExclusiveEvidence(int[] chain, int[] changes)
	{
		for (int i = 0; i < changes.length; i++)
		{
			if (changes[i] > 0)
			{
				boolean onChain = false;
				for (int member : chain)
				{
					onChain |= member == i;
				}
				if (!onChain)
				{
					return false;
				}
			}
		}
		return true;
	}

	/** Resolve only the cases that exclusive witnesses cannot identify. */
	private FootprintResolution resolveFootprint(int width, SubmenuTree tree, boolean[] dormant,
		int[] visibleArea, int[] minX, int[] minY, int[] maxX, int[] maxY, int changedCount)
	{
		int size = tree.candidateBounds.size();
		if (changedCount == 0)
		{
			for (int i = 0; i < size; i++)
			{
				if (!dormant[i] && visibleArea[i] == 0)
				{
					return new FootprintResolution(new int[0], 0, null, 0);
				}
			}
			return new FootprintResolution(new int[0], 1, null, 0);
		}
		int actualMinX = width;
		int actualMinY = Integer.MAX_VALUE;
		int actualMaxX = -1;
		int actualMaxY = -1;
		int[] hits = new int[size];
		for (int j = 0; j < changedCount; j++)
		{
			int x = changedFootprint[j] % width;
			int y = changedFootprint[j] / width;
			actualMinX = Math.min(actualMinX, x);
			actualMinY = Math.min(actualMinY, y);
			actualMaxX = Math.max(actualMaxX, x);
			actualMaxY = Math.max(actualMaxY, y);
			for (int i = 0; i < size; i++)
			{
				Rectangle candidate = tree.candidateBounds.get(i);
				if (x >= candidate.x && x < candidate.x + candidate.width
					&& y >= candidate.y && y < candidate.y + candidate.height)
				{
					hits[i]++;
				}
			}
		}
		Rectangle actual = new Rectangle(actualMinX, actualMinY,
			actualMaxX - actualMinX + 1, actualMaxY - actualMinY + 1);
		int[] reverse = new int[size];
		int[] selected = new int[0];
		int matches = 0;
		for (int leaf = 0; leaf < size; leaf++)
		{
			int depth = 0;
			int current = leaf;
			int expectedMinX = width;
			int expectedMinY = Integer.MAX_VALUE;
			int expectedMaxX = -1;
			int expectedMaxY = -1;
			boolean valid = true;
			while (current >= 0)
			{
				if (dormant[current])
				{
					valid = false;
					break;
				}
				reverse[depth++] = current;
				if (visibleArea[current] > 0)
				{
					expectedMinX = Math.min(expectedMinX, minX[current]);
					expectedMinY = Math.min(expectedMinY, minY[current]);
					expectedMaxX = Math.max(expectedMaxX, maxX[current]);
					expectedMaxY = Math.max(expectedMaxY, maxY[current]);
					if ((long) hits[current] * 100 < (long) visibleArea[current] * 90)
					{
						valid = false;
					}
				}
				current = tree.candidateParents.get(current);
			}
			if (!valid || expectedMaxX < 0
				|| Math.abs(actualMinX - expectedMinX) > EDGE_TOLERANCE
				|| Math.abs(actualMinY - expectedMinY) > EDGE_TOLERANCE
				|| Math.abs(actualMaxX - expectedMaxX) > EDGE_TOLERANCE
				|| Math.abs(actualMaxY - expectedMaxY) > EDGE_TOLERANCE)
			{
				continue;
			}
			for (int j = 0; j < changedCount; j++)
			{
				int x = changedFootprint[j] % width;
				int y = changedFootprint[j] / width;
				boolean covered = false;
				for (int k = 0; k < depth; k++)
				{
					covered |= containsWithMargin(tree.candidateBounds.get(reverse[k]), x, y);
				}
				if (!covered)
				{
					valid = false;
					break;
				}
			}
			if (valid)
			{
				matches++;
				if (matches == 1)
				{
					selected = new int[depth];
					for (int j = 0; j < depth; j++)
					{
						selected[j] = reverse[depth - 1 - j];
					}
				}
			}
		}
		return new FootprintResolution(selected, matches, actual, changedCount);
	}

	private static final class FootprintResolution
	{
		private final int[] chain;
		private final int matches;
		private final Rectangle bounds;
		private final int changedPixels;

		private FootprintResolution(int[] chain, int matches, Rectangle bounds, int changedPixels)
		{
			this.chain = chain;
			this.matches = matches;
			this.bounds = bounds;
			this.changedPixels = changedPixels;
		}
	}

	private static int[] activeChain(List<Integer> parents, int[] changed)
	{
		int[] chain = new int[changed.length];
		int size = 0;
		int parent = -1;
		while (true)
		{
			int next = -1;
			for (int i = 0; i < changed.length; i++)
			{
				if (changed[i] > 0 && parents.get(i) == parent)
				{
					if (next >= 0)
					{
						return null;
					}
					next = i;
				}
			}
			if (next < 0)
			{
				int hits = 0;
				for (int changedCount : changed)
				{
					if (changedCount > 0)
					{
						hits++;
					}
				}
				return hits == size ? Arrays.copyOf(chain, size) : null;
			}
			chain[size++] = next;
			parent = next;
		}
	}

	private static boolean containsWithMargin(Rectangle r, int x, int y)
	{
		return x >= r.x - MARGIN && x < r.x + r.width + MARGIN
			&& y >= r.y - MARGIN && y < r.y + r.height + MARGIN;
	}

	enum State
	{
		NO_CHILD, ACTIVE, AMBIGUOUS, UNSUPPORTED, GEOMETRY_CHANGED, FAILURE
	}

	static final class Result
	{
		final State state;
		final String reason;
		final int[] activeChain;
		final int[] witnesses;
		final int[] changed;
		final int[] sharedWitnesses;
		final int[] sharedChanged;
		final boolean restored;
		/** 1 when the native draw ran for this result, otherwise 0. */
		int drawPasses;
		int visibleCandidates;
		long candidatePixels;
		int footprintMatches;
		int footprintChangedPixels;
		Rectangle footprintBounds;
		ExactCoverageResolver.Outcome exact = ExactCoverageResolver.Outcome.NOT_EVALUATED;
		/** The native pixels of resolved or alternative one-menu chains; null when none. */
		NativeCapture nativeCapture;

		/**
		 * The framebuffer was restored exactly, no menu rectangle changed during the draw, and
		 * the native draw reached the marked root. False for every buffer, restore and geometry
		 * failure, including a later buffer identity failure, which builds a fresh result.
		 */
		boolean framebufferVerified;

		private Result(State state, String reason, int[] activeChain, int[] witnesses,
			int[] changed, int[] sharedWitnesses, int[] sharedChanged, boolean drew, boolean restored)
		{
			this.state = state;
			this.reason = reason;
			this.activeChain = activeChain;
			this.witnesses = witnesses;
			this.changed = changed;
			this.sharedWitnesses = sharedWitnesses;
			this.sharedChanged = sharedChanged;
			this.restored = restored;
			this.drawPasses = drew ? 1 : 0;
		}

		/** A result read after the native draw. */
		private Result(State state, String reason, int[] activeChain, int[] witnesses,
			int[] changed, int[] sharedWitnesses, int[] sharedChanged, boolean restored)
		{
			this(state, reason, activeChain, witnesses, changed, sharedWitnesses, sharedChanged, true, restored);
		}

		private Result withFootprint(FootprintResolution footprint)
		{
			footprintMatches = footprint.matches;
			footprintChangedPixels = footprint.changedPixels;
			footprintBounds = footprint.bounds;
			return this;
		}

		private static Result failure(State state, String reason)
		{
			return new Result(state, reason, new int[0], new int[0],
				new int[0], new int[0], new int[0], false, false);
		}

		private static Result afterDraw(State state, String reason,
			int[] witnesses, int[] changed, int[] sharedWitnesses, int[] sharedChanged, boolean restored)
		{
			return new Result(state, reason, new int[0], witnesses, changed,
				sharedWitnesses, sharedChanged, true, restored);
		}
	}
}

package com.rightclickstyler;

import java.util.Objects;
import java.util.function.Consumer;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;

/**
 * The public menu structure that produced one prepared image.
 *
 * <p>The mouse is deliberately not part of this state. RuneLite's native submenu state only
 * changes in the client's per-cycle input step, never while a frame is being prepared or
 * drawn, so a pointer movement during preparation cannot invalidate the native probe. The
 * themed hover row comes from the single mouse sample taken when {@code BeforeMenuRender}
 * begins; a later movement is picked up by the next frame's probe.
 */
final class PreparedMenuState
{
	private final SubmenuTree tree;
	private final EntryState[][] selectedEntries;
	private final int[] selectedNodes;

	/** @param nodes the root (0) first, then each selected menu's node index once */
	private PreparedMenuState(SubmenuTree tree, int[] nodes)
	{
		this.tree = tree;
		this.selectedNodes = nodes;
		this.selectedEntries = new EntryState[selectedNodes.length][];
		for (int depth = 0; depth < selectedNodes.length; depth++)
		{
			MenuEntry[] entries = tree.nodes.get(selectedNodes[depth]).entries;
			EntryState[] snapshot = new EntryState[entries.length];
			for (int i = 0; i < entries.length; i++)
			{
				snapshot[i] = entries[i] == null ? null : new EntryState(entries[i]);
			}
			selectedEntries[depth] = snapshot;
		}
	}

	static PreparedMenuState capture(SubmenuTree tree, int[] activeChain)
	{
		return capture(tree, new int[][]{activeChain});
	}

	/**
	 * Every menu of every chain, so the frame drops if any of them changes. Used for visually
	 * equivalent alternatives, where any one of the chains may be the one native drew.
	 */
	static PreparedMenuState capture(SubmenuTree tree, int[][] chains)
	{
		int[] nodes = new int[tree.nodes.size()];
		boolean[] seen = new boolean[tree.nodes.size()];
		int count = 1;
		seen[0] = true;
		for (int[] chain : chains)
		{
			for (int candidate : chain)
			{
				int node = candidate + 1;
				if (!seen[node])
				{
					seen[node] = true;
					nodes[count++] = node;
				}
			}
		}
		return new PreparedMenuState(tree, java.util.Arrays.copyOf(nodes, count));
	}

	boolean matches(Menu currentRoot)
	{
		return mismatchReason(currentRoot) == null;
	}

	/**
	 * @return why the current public menu structure no longer matches the prepared image, or
	 * null when root identity, every node's geometry, the selected submenu links and the
	 * selected menus' entries are all unchanged.
	 */
	String mismatchReason(Menu currentRoot)
	{
		if (currentRoot != tree.root)
		{
			return "root identity";
		}
		for (SubmenuTree.Node node : tree.nodes)
		{
			Menu menu = node.menu;
			if (menu.getMenuX() != node.bounds.x || menu.getMenuY() != node.bounds.y
				|| menu.getMenuWidth() != node.bounds.width
				|| menu.getMenuHeight() != node.bounds.height)
			{
				return "geometry node=" + tree.nodes.indexOf(node);
			}
		}
		for (int depth = 0; depth < selectedNodes.length; depth++)
		{
			SubmenuTree.Node node = tree.nodes.get(selectedNodes[depth]);
			if (node.parentNode >= 0)
			{
				MenuEntry[] parentEntries = tree.nodes.get(node.parentNode).menu.getMenuEntries();
				if (parentEntries == null || node.parentEntryIndex >= parentEntries.length
					|| parentEntries[node.parentEntryIndex] == null
					|| parentEntries[node.parentEntryIndex].getSubMenu() != node.menu)
				{
					return "submenu link depth=" + depth + " entry=" + node.parentEntryIndex;
				}
			}
			MenuEntry[] current = node.menu.getMenuEntries();
			EntryState[] expected = selectedEntries[depth];
			if (current == null || current.length != expected.length)
			{
				return "entry count depth=" + depth;
			}
			for (int i = 0; i < current.length; i++)
			{
				if (expected[i] == null ? current[i] != null : current[i] == null)
				{
					return "entry presence depth=" + depth + " index=" + i;
				}
				if (expected[i] != null)
				{
					String field = expected[i].mismatchField(current[i]);
					if (field != null)
					{
						return "entry " + field + " depth=" + depth + " index=" + i;
					}
				}
			}
		}
		return null;
	}

	private static final class EntryState
	{
		private final String option;
		private final String target;
		private final Menu subMenu;
		private final MenuAction type;
		private final Consumer<MenuEntry> callback;
		private final int identifier;
		private final int param0;
		private final int param1;
		private final int worldViewId;
		private final int itemId;
		private final boolean forceLeftClick;
		private final boolean deprioritized;

		private EntryState(MenuEntry entry)
		{
			option = entry.getOption();
			target = entry.getTarget();
			subMenu = entry.getSubMenu();
			type = entry.getType();
			callback = entry.onClick();
			identifier = entry.getIdentifier();
			param0 = entry.getParam0();
			param1 = entry.getParam1();
			worldViewId = entry.getWorldViewId();
			itemId = entry.getItemId();
			forceLeftClick = entry.isForceLeftClick();
			deprioritized = entry.isDeprioritized();
		}

		private String mismatchField(MenuEntry entry)
		{
			if (!Objects.equals(option, entry.getOption()))
			{
				return "option";
			}
			if (!Objects.equals(target, entry.getTarget()))
			{
				return "target";
			}
			if (subMenu != entry.getSubMenu())
			{
				return "submenu";
			}
			if (type != entry.getType())
			{
				return "type";
			}
			if (callback != entry.onClick())
			{
				return "callback";
			}
			if (identifier != entry.getIdentifier())
			{
				return "identifier";
			}
			if (param0 != entry.getParam0())
			{
				return "param0";
			}
			if (param1 != entry.getParam1())
			{
				return "param1";
			}
			if (worldViewId != entry.getWorldViewId())
			{
				return "worldViewId";
			}
			if (itemId != entry.getItemId())
			{
				return "itemId";
			}
			if (forceLeftClick != entry.isForceLeftClick())
			{
				return "forceLeftClick";
			}
			if (deprioritized != entry.isDeprioritized())
			{
				return "deprioritized";
			}
			return null;
		}
	}
}

