	/**
	 * Saves a global (non-theme) setting. The preview reads these from config, so refresh it after.
	 */
	private void setGlobal(String key, Object value)
	{
		configManager.setConfiguration(RightClickStylerConfig.GROUP, key, value);
		preview.refresh();
	}

	private ColorJButton globalColourButton(Supplier<Color> getter, String title, String key)
	{
		ColorJButton button = colourButton(getter.get(), title, NOTHING, c -> setGlobal(key, c));
		globalControlRefreshers.add(() -> setColourButton(button, getter.get()));
		return button;
	}

	private JCheckBox globalCheckBox(BooleanSupplier getter, String key)
	{
		JCheckBox checkbox = new JCheckBox();
		checkbox.setSelected(getter.getAsBoolean());
		// setSelected doesn't fire action events, so refreshing can't write back to config.
		checkbox.addActionListener(e -> setGlobal(key, checkbox.isSelected()));
		globalControlRefreshers.add(() -> checkbox.setSelected(getter.getAsBoolean()));
		return checkbox;
	}

	/**
	 * A global mode combo whose dependent controls are only enabled in the mode that uses them.
	 */
	private <E extends Enum<E>> JComboBox<E> modeCombo(E[] modes, Supplier<E> getter, E customMode, String key,
		JComponent... dependentControls)
	{
		JComboBox<E> combo = new JComboBox<>(modes);
		combo.setRenderer(new TitleCaseListCellRenderer());
		combo.setSelectedItem(getter.get());
		Runnable updateEnabled = () ->
		{
			boolean custom = combo.getSelectedItem() == customMode;
			setModeControlsEnabled(custom, dependentControls);
		};
		updateEnabled.run();
		combo.addActionListener(e ->
		{
			if (!refreshing)
			{
				setGlobal(key, combo.getSelectedItem());
			}
			updateEnabled.run();
		});
		globalControlRefreshers.add(() ->
		{
			combo.setSelectedItem(getter.get());
			updateEnabled.run();
		});
		return combo;
	}

	static void setModeControlsEnabled(boolean enabled, JComponent... controls)
	{
		for (JComponent control : controls)
		{
			control.setEnabled(enabled);
			if (control instanceof JPanel)
			{
				for (Component child : control.getComponents())
				{
					child.setEnabled(enabled);
				}
			}
		}
	}

	private JSpinner globalIntSpinner(IntSupplier getter, int min, int max, String key)
	{
		JSpinner spinner = new JSpinner(new SpinnerNumberModel(getter.getAsInt(), min, max, 1));
		spinnerFieldWidth(spinner);
		Timer commit = new Timer(SPINNER_COMMIT_DELAY_MS, e -> setGlobal(key, spinner.getValue()));
		commit.setRepeats(false);
		spinner.addChangeListener(e ->
		{
			if (!refreshing)
			{
				commit.restart();
			}
		});
		globalControlRefreshers.add(() ->
		{
			// A pending edit would otherwise land after the reset and undo it.
			commit.stop();
			spinner.setValue(getter.getAsInt());
		});
		return spinner;
	}

	// --- Action highlight rules editor ---

	private static final class EditableRule
	{
		private String option;
		private Color colour;

		private EditableRule(String option, Color colour)
		{
			this.option = option;
			this.colour = colour;
		}
	}

	/**
	 * Writes every current rule to config, skipping blank option names. Blank rows stay in the
	 * UI while they're being edited; they just aren't saved yet.
	 */
	private void persistRules()
	{
		StringBuilder sb = new StringBuilder();
		for (EditableRule rule : rules)
		{
			if (rule.option.trim().isEmpty())
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append('\n');
			}
			sb.append(rule.option.trim()).append('=').append(hex(rule.colour));
		}
		setGlobal(RightClickStylerConfig.KEY_HIGHLIGHT_RULES, sb.toString());
	}

	private void loadRules()
	{
		rules.clear();
		rulesPanel.removeAll();
		for (HighlightRules.Rule parsed : HighlightRules.parse(config.highlightRules()))
		{
			EditableRule rule = new EditableRule(parsed.option, parsed.colour);
			rules.add(rule);
			rulesPanel.add(ruleRow(rule, false));
		}
		rulesPanel.revalidate();
		rulesPanel.repaint();
		updateAddRuleEnabled();
	}

	private void addNewRule()
	{
		if (rules.size() >= Limits.MAX_RULES)
		{
			return;
		}
		EditableRule rule = new EditableRule(NEW_RULE_OPTION, NEW_RULE_COLOUR);
		rules.add(rule);
		rulesPanel.add(ruleRow(rule, true));
		rulesPanel.revalidate();
		rulesPanel.repaint();
		updateAddRuleEnabled();
	}

	private void updateAddRuleEnabled()
	{
		addRuleButton.setEnabled(rules.size() < Limits.MAX_RULES);
	}

	private JPanel ruleRow(EditableRule rule, boolean focusField)
	{
		JPanel panel = new JPanel(new BorderLayout(ROW_GAP, 0));

		JTextField optionField = new JTextField(rule.option);
		optionField.setBorder(BorderFactory.createEmptyBorder(FIELD_PADDING, FIELD_PADDING, FIELD_PADDING, FIELD_PADDING));
		Runnable commit = () ->
		{
			String option = Limits.truncate(optionField.getText().trim(), Limits.MAX_RULE_OPTION_LENGTH);
			// Enter followed by focus loss would otherwise write the same value twice
			if (!option.equals(rule.option))
			{
				rule.option = option;
				persistRules();
			}
		};
		optionField.addActionListener(e -> commit.run());
		optionField.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				commit.run();
			}
		});

		ColorJButton colourBtn = colourButton(rule.colour, "Rule colour", c -> rule.colour = c, c -> persistRules());

		JButton remove = new JButton("✕");
		remove.setToolTipText("Remove rule");
		remove.setMargin(REMOVE_INSETS);
		remove.addActionListener(e ->
		{
			rules.remove(rule);
			rulesPanel.remove(panel);
			rulesPanel.revalidate();
			rulesPanel.repaint();
			persistRules();
			updateAddRuleEnabled();
		});

		JPanel right = new JPanel(new BorderLayout(ROW_GAP, 0));
		right.add(colourBtn, BorderLayout.WEST);
		right.add(remove, BorderLayout.EAST);

		panel.add(optionField, BorderLayout.CENTER);
		panel.add(right, BorderLayout.EAST);

		if (focusField)
		{
			SwingUtilities.invokeLater(() ->
			{
				optionField.requestFocusInWindow();
				optionField.selectAll();
			});
		}

		return panel;
	}

	// --- Shared widgets ---

	/**
	 * @param onChange called live while the picker is dragged; must not persist
	 * @param onCommit called once when the picker closes
	 */
	private ColorJButton colourButton(Color initial, String title, Consumer<Color> onChange, Consumer<Color> onCommit)
	{
		ColorJButton button = new ColorJButton(hex(initial), initial);
		button.setFocusable(false);
		button.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (!button.isEnabled())
				{
					return;
				}
				RuneliteColorPicker picker = colorPickerManager.create(button, button.getColor(), title, true);
				long openedProfileRevision = profileRevision;
				picker.setLocationRelativeTo(button);
				picker.setOnColorChange(c ->
				{
					if (openedProfileRevision != profileRevision)
					{
						return;
					}
					setColourButton(button, c);
					onChange.accept(c);
				});
				picker.setOnClose(c ->
				{
					if (openedProfileRevision == profileRevision)
					{
						onCommit.accept(c);
					}
				});
				picker.setVisible(true);
			}
		});
		return button;
	}

	private static void setColourButton(ColorJButton button, Color colour)
	{
		button.setColor(colour);
		button.setText(hex(colour));
	}

	private static String hex(Color colour)
	{
		return "#" + ColorUtil.colorToHexCode(colour).toUpperCase(Locale.ROOT);
	}

	private static JPanel row(String label, JComponent control)
	{
		return row(label, null, control);
	}

	private static JPanel row(String label, String tooltip, JComponent control)
	{
		JPanel panel = new JPanel(new BorderLayout());
		JLabel text = new JLabel(label);
		if (tooltip != null)
		{
			text.setToolTipText(tooltip);
		}
		panel.add(text, BorderLayout.CENTER);
		panel.add(control, BorderLayout.EAST);
		return panel;
	}

	private static void spinnerFieldWidth(JSpinner spinner)
	{
		Component editor = spinner.getEditor();
		if (editor instanceof JSpinner.DefaultEditor)
		{
			((JSpinner.DefaultEditor) editor).getTextField().setColumns(SPINNER_COLUMNS);
		}
	}

	// --- Refresh / theme actions ---

	private void refresh()
	{
		refreshing = true;
		try
		{
			themeCombo.removeAllItems();
			for (Theme theme : themeManager.builtIns())
			{
				themeCombo.addItem(theme);
			}
			for (Theme theme : themeManager.userThemes())
			{
				themeCombo.addItem(theme);
			}

			selectActiveTheme();

			for (Runnable r : themeControlRefreshers)
			{
				r.run();
			}

			updateEditButtons();
			preview.refresh();
		}
		finally
		{
			refreshing = false;
		}
	}

	// Callers must hold the refreshing guard so the combo's listener ignores this change.
	private void selectActiveTheme()
	{
		String activeId = themeManager.activeId();
		for (int i = 0; i < themeCombo.getItemCount(); i++)
		{
			if (themeCombo.getItemAt(i).id.equals(activeId))
			{
				themeCombo.setSelectedIndex(i);
				return;
			}
		}
	}

	/**
	 * @return true if there are no unsaved edits, or the user chose to discard them
	 */
	private boolean confirmDiscardEdits()
	{
		if (!themeManager.isEdited())
		{
			return true;
		}
		return confirm("Discard unsaved changes to " + themeManager.active().name + "?", "Unsaved changes", "Discard");
	}

	/**
	 * Reverts the working theme to its saved version, asking {@code confirm} first only when
	 * that would discard unsaved edits.
	 *
	 * @return true if the theme was reverted; false if the user cancelled and nothing changed
	 */
	static boolean revertEdits(ThemeManager themeManager, BooleanSupplier confirm)
	{
		if (themeManager.isEdited() && !confirm.getAsBoolean())
		{
			return false;
		}
		themeManager.revert();
		return true;
	}

	private boolean confirmRevert()
	{
		return confirm("Revert " + themeManager.active().name + "? Your unsaved changes will be lost and the "
			+ "last saved version restored.", "Revert changes", "Revert changes");
	}

	/**
	 * A warning dialog with {@code action} and Cancel, where Cancel has the focus.
	 *
	 * @return true if the user chose {@code action}
	 */
	private boolean confirm(String message, String title, String action)
	{
		Object[] options = {action, "Cancel"};
		return JOptionPane.showOptionDialog(this, message, title, JOptionPane.DEFAULT_OPTION,
			JOptionPane.WARNING_MESSAGE, null, options, options[1]) == 0;
	}

	/**
	 * What Reset all settings changes: every global setting returns to its default and the default
	 * theme is selected. Saved themes ({@code userThemes}) and the sidebar button toggle are kept.
	 */
	static void resetAllSettings(Consumer<String> unset, ThemeManager themeManager)
	{
		for (String key : GLOBAL_SETTING_KEYS)
		{
			unset.accept(key);
		}
		themeManager.applyTheme(BuiltInThemes.DEFAULT_ID);
	}

	/**
	 * Restores every global setting to its default and switches to the default theme, dropping
	 * unsaved edits. Saved themes are kept.
	 */
	private void promptResetAll()
	{
		if (!confirm("Reset all settings to default? Your saved themes are kept.", "Reset all settings", "Reset"))
		{
			return;
		}
		resetAllSettings(key -> configManager.unsetConfiguration(RightClickStylerConfig.GROUP, key), themeManager);

		refreshing = true;
		try
		{
			for (Runnable r : globalControlRefreshers)
			{
				r.run();
			}
		}
		finally
		{
			refreshing = false;
		}
		refresh();
	}

	private void promptSaveAsNew()
	{
		String name = JOptionPane.showInputDialog(this, "Theme name:", "Save as new theme", JOptionPane.PLAIN_MESSAGE);
		if (name != null && !name.trim().isEmpty())
		{
			if (!themeManager.saveAsNew(name))
			{
				showThemesFull();
			}
			refresh();
		}
	}

	private void promptRename()
	{
		String name = JOptionPane.showInputDialog(this, "New name:", themeManager.active().name);
		if (name != null && !name.trim().isEmpty())
		{
			themeManager.rename(name);
			refresh();
		}
	}

	private void promptDelete()
	{
		Theme active = themeManager.active();
		int result = JOptionPane.showConfirmDialog(this, "Delete \"" + active.name + "\"?", "Delete theme",
			JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
		if (result == JOptionPane.YES_OPTION)
		{
			themeManager.delete(active.id);
			refresh();
		}
	}

	private void exportActive()
	{
		String payload = themeManager.exportWorking();
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(payload), null);
		}
		catch (RuntimeException e)
		{
			// the clipboard is OS-owned and can be unavailable or busy
			JOptionPane.showMessageDialog(this, "Couldn't copy the theme to the clipboard.", "Export failed",
				JOptionPane.ERROR_MESSAGE);
			return;
		}
		moreButton.setText(COPIED_LABEL);
		copiedFlash.restart();
	}

	private void promptImport()
	{
		String clipboardText = "";
		try
		{
			Clipboard clipboard = Toolkit.getDefaultToolkit().getSystemClipboard();
			if (clipboard.isDataFlavorAvailable(DataFlavor.stringFlavor))
			{
				clipboardText = (String) clipboard.getData(DataFlavor.stringFlavor);
			}
		}
		catch (UnsupportedFlavorException | IOException | RuntimeException ignored)
		{
			// the clipboard is OS-owned and can fail in many ways; just leave the field blank
		}

		String payload = (String) JOptionPane.showInputDialog(this, "Paste exported theme:", "Import theme",
			JOptionPane.PLAIN_MESSAGE, null, null, clipboardText);
		if (payload == null || payload.trim().isEmpty() || !confirmDiscardEdits())
		{
			return;
		}

		String error = themeManager.importTheme(payload);
		if (error != null)
		{
			JOptionPane.showMessageDialog(this, error, "Import failed", JOptionPane.ERROR_MESSAGE);
			return;
		}
		refresh();
	}

	private void showThemesFull()
	{
		JOptionPane.showMessageDialog(this, ThemeManager.ERROR_FULL, "Too many themes", JOptionPane.WARNING_MESSAGE);
	}
}

package com.rightclickstyler;

import com.google.inject.Provides;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Menu;
import net.runelite.api.MenuEntry;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.events.BeforeMenuRender;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOpened;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
	name = RightClickStylerPlugin.NAME
)
public class RightClickStylerPlugin extends Plugin
{
	static final String NAME = "Right Click Styler";
	private static final String INTERFACE_STYLES_GROUP = "interfaceStyles";
	private static final String HD_MENU_KEY = "hdMenu";
	private static final String MENU_ALPHA_KEY = "menuAlpha";
	// PluginManager stores each plugin's enabled state under its lowercased class name in the
	// "runelite" group. Interface Styles is off by default.
	private static final String INTERFACE_STYLES_PLUGIN_KEY = "interfacestylesplugin";
	private static final String INTERFACE_STYLES_WARNING = NAME
		+ ": turn off Interface Styles' High detail menu and set its Menu alpha to 255.";
	private static final int NAV_PRIORITY = 5;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MenuOverlay menuOverlay;

	@Inject
	private ConfigManager configManager;

	@Inject
	private RightClickStylerConfig config;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private LocalPlayerSnapshot localPlayer;

	@Inject
	private ThemeManager themeManager;

	@Inject
	private StylePublisher stylePublisher;

	// Created in startUp() rather than injected: RuneLite installs its look and feel after plugins
	// load, and Swing components built before that keep the default light styling. Volatile because
	// ConfigChanged can arrive on any thread.
	private volatile RightClickStylerPanel panel;
	// Volatile because ConfigChanged can arrive on any thread.
	private volatile NavigationButton navigationButton;
	// Once per session, and only once it could actually be seen. Client thread only, apart from the
	// reset in shutDown.
	private volatile boolean warnedAboutInterfaceStylesConflict;
	private volatile boolean running;
	private boolean preparingSubmenu;

	@Override
	protected void startUp()
	{
		// Reload before building the panel so enabling the plugin always uses the active profile.
		// Register the overlay only after the panel has been built successfully.
		themeManager.reload();
		panel = getInjector().getInstance(RightClickStylerPanel.class);
		navigationButton = NavigationButton.builder()
			.tooltip(NAME)
			.icon(ImageUtil.loadImageResource(RightClickStylerPlugin.class, "panel_icon.png"))
			.priority(NAV_PRIORITY)
			.panel(panel)
			.build();
		updateSidebarButton();

		menuOverlay.resetFailure();
		overlayManager.add(menuOverlay);

		updateInterfaceStylesWarning();
		running = true;
		stylePublisher.start();
	}

	@Override
	protected void shutDown()
	{
		running = false;
		stylePublisher.stop();
		menuOverlay.clearPrepared();
		overlayManager.remove(menuOverlay);
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
			navigationButton = null;
		}
		panel = null;
		warnedAboutInterfaceStylesConflict = false;
		localPlayer.setOnChange(null);
		localPlayer.clear();
	}

	@Subscribe
	public void onBeforeMenuRender(BeforeMenuRender event)
	{
		menuOverlay.setExternallyConsumed(event.isConsumed());
		if (event.isConsumed())
		{
			menuOverlay.discardPreparedAtEventStart();
			return;
		}
		// Consume only a frame our overlay will draw. RuneLite's OverlayRenderer draws no overlay
		// unless the client is logged in, and once shutDown begins the overlay is being removed
		// (the EventBus is unregistered first, but a post already under way can still arrive).
		if (!running || client.getGameState() != GameState.LOGGED_IN)
		{
			menuOverlay.discardPreparedAtEventStart();
			return;
		}
		if (handleSubmenuFrame(event))
		{
			return;
		}
		if (menuOverlay.shouldDraw())
		{
			event.consume();
		}
	}

	/** @return true when the submenu path owns this event: a menu with submenus or a scrollable root. */
	boolean handleSubmenuFrame(BeforeMenuRender event)
	{
		if (preparingSubmenu)
		{
			return true;
		}
		// The only mouse read for this frame. getMouseCanvasPosition follows the AWT thread
		// live, while native submenu state is fixed for the cycle, so preparation and the
		// final draw both use this sample instead of re-reading the pointer.
		Point frameMouse = client.getMouseCanvasPosition();
		menuOverlay.discardPreparedAtEventStart();
		if (!client.isMenuOpen())
		{
			return false;
		}
		Menu root = client.getMenu();
		MenuEntry[] entries = root == null ? null : root.getMenuEntries();
		if (entries == null
			|| !(MenuOverlay.containsSubMenu(entries) || client.isMenuScrollable()))
		{
			return false;
		}
		preparingSubmenu = true;
		try
		{
			if (menuOverlay.prepareSubmenuFrame(root, entries, frameMouse))
			{
				// Final: native drawing is skipped once this returns. A structural change
				// before the overlay draws keeps the image only if it cannot change it; any
				// other change, or a failed draw, leaves this one frame without a menu and
				// keeps the rest of this menu opening native. drawOriginalMenu is called only
				// here, where native drawing itself happens: the overlay pass cannot read the
				// rasterizer clip such a late native draw would depend on.
				event.consume();
			}
		}
		finally
		{
			preparingSubmenu = false;
		}
		return true;
	}

	/** Each root-menu opening: the only point at which a failed opening's native fallback ends. */
	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		menuOverlay.menuOpened();
	}

	// Polled each tick so level-ups reach the preview; this also covers login, where the local player
	// is often still null on the LOGGED_IN event.
	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player player = client.getLocalPlayer();
		if (player != null)
		{
			localPlayer.set(player.getCombatLevel());
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			localPlayer.clear();
		}
		else if (event.getGameState() == GameState.LOGGED_IN)
		{
			warnInChatOnce();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (RightClickStylerConfig.GROUP.equals(event.getGroup())
			&& RightClickStylerConfig.KEY_SHOW_SIDEBAR_BUTTON.equals(event.getKey()))
		{
			updateSidebarButton();
			return;
		}
		if ((INTERFACE_STYLES_GROUP.equals(event.getGroup())
			&& (HD_MENU_KEY.equals(event.getKey()) || MENU_ALPHA_KEY.equals(event.getKey())))
			|| (RuneLiteConfig.GROUP_NAME.equals(event.getGroup()) && INTERFACE_STYLES_PLUGIN_KEY.equals(event.getKey())))
		{
			updateInterfaceStylesWarning();
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		if (!running)
		{
			return;
		}
		RightClickStylerPanel expectedPanel = panel;
		SwingUtilities.invokeLater(() ->
		{
			if (!running || panel != expectedPanel)
			{
				return;
			}
			themeManager.reload();
			RightClickStylerPanel current = panel;
			if (current != null)
			{
				current.reloadFromConfig();
			}
			updateSidebarButton();
			updateInterfaceStylesWarning();
		});
	}

	@Override
	public void resetConfiguration()
	{
		RightClickStylerPanel expectedPanel = panel;
		Runnable reload = () ->
		{
			if (expectedPanel == null)
			{
				if (!running)
				{
					themeManager.reload();
				}
				return;
			}
			if (!running || panel != expectedPanel)
			{
				return;
			}
			themeManager.reload();
			expectedPanel.reloadFromConfig();
			updateSidebarButton();
			updateInterfaceStylesWarning();
		};

		if (SwingUtilities.isEventDispatchThread())
		{
			reload.run();
		}
		else
		{
			SwingUtilities.invokeLater(reload);
		}
	}

	@Provides
	RightClickStylerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RightClickStylerConfig.class);
	}

	// ClientToolbar hands both calls to the EDT, and adding or removing twice is harmless.
	private void updateSidebarButton()
	{
		NavigationButton button = navigationButton;
		if (button == null)
		{
			return;
		}
		if (config.showSidebarButton())
		{
			clientToolbar.addNavigation(button);
		}
		else
		{
			clientToolbar.removeNavigation(button);
		}
	}

	/**
	 * Interface Styles conflicts while enabled with its high-detail menu on or its menu alpha not 255.
	 */
	private boolean isInterfaceStylesConflictActive()
	{
		if (!Boolean.parseBoolean(configManager.getConfiguration(RuneLiteConfig.GROUP_NAME, INTERFACE_STYLES_PLUGIN_KEY)))
		{
			return false;
		}
		if (Boolean.parseBoolean(configManager.getConfiguration(INTERFACE_STYLES_GROUP, HD_MENU_KEY)))
		{
			return true;
		}
		Integer menuAlpha = configManager.getConfiguration(INTERFACE_STYLES_GROUP, MENU_ALPHA_KEY, Integer.class);
		return menuAlpha != null && menuAlpha != 255;
	}

	// Called from startUp and ConfigChanged, neither of which is guaranteed to be on the EDT or the
	// client thread.
	private void updateInterfaceStylesWarning()
	{
		boolean active = isInterfaceStylesConflictActive();
		RightClickStylerPanel current = panel;
		if (current != null)
		{
			SwingUtilities.invokeLater(() -> current.setInterfaceStylesWarningVisible(active));
		}
		if (active)
		{
			clientThread.invokeLater(this::warnInChatOnce);
		}
	}

	// Client thread only. Skipped until logged in, so the one warning isn't spent where nobody sees it.
	private void warnInChatOnce()
	{
		if (warnedAboutInterfaceStylesConflict || client.getGameState() != GameState.LOGGED_IN
			|| !isInterfaceStylesConflictActive())
		{
			return;
		}
		warnedAboutInterfaceStylesConflict = true;
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", INTERFACE_STYLES_WARNING, null);
	}
}

package com.rightclickstyler;

import java.awt.Rectangle;
import net.runelite.api.Point;

/** The visible root rows, using RuneLite's public entry scroll offset. */
final class ScrollableMenuViewport
{
	final int scroll;
	final int firstRow;
	final int endRow;
	private final Rectangle bounds;
	private final int canvasHeight;

	private ScrollableMenuViewport(Rectangle bounds, int canvasHeight, int scroll,
		int endRow)
	{
		this.bounds = bounds;
		this.canvasHeight = canvasHeight;
		this.scroll = scroll;
		this.firstRow = scroll;
		this.endRow = endRow;
	}

	static ScrollableMenuViewport capture(Rectangle bounds, int entries, int canvasWidth,
		int canvasHeight, boolean scrollable, int scroll)
	{
		if (bounds == null || entries <= 0 || canvasWidth <= 0 || canvasHeight <= 0
			|| bounds.width <= 0 || bounds.height <= 0 || bounds.x >= canvasWidth
			|| bounds.y >= canvasHeight || bounds.x + bounds.width <= 0)
		{
			return null;
		}
		if (!scrollable && scroll != 0)
		{
			return null;
		}
		if (scrollable)
		{
			// The inspected RuneLite client sets scrollability when the full native
			// menu height exceeds the canvas, and clamps the offset in 15px rows.
			int excess = bounds.height - canvasHeight;
			if (excess <= 0 || scroll < 0 || scroll >= entries
				|| scroll > ((long) excess + MenuRenderer.ROW_HEIGHT - 1) / MenuRenderer.ROW_HEIGHT)
			{
				return null;
			}
		}
		int rowSpace = canvasHeight - (bounds.y + MenuRenderer.HEADER_HEIGHT);
		if (rowSpace <= 0)
		{
			return null;
		}
		int slots = (rowSpace + MenuRenderer.ROW_HEIGHT - 1) / MenuRenderer.ROW_HEIGHT;
		int end = Math.min(entries, scroll + slots);
		return end > scroll ? new ScrollableMenuViewport(bounds, canvasHeight, scroll, end) : null;
	}

	boolean containsRow(int row)
	{
		return row >= firstRow && row < endRow;
	}

	int rowTop(int row)
	{
		return bounds.y + MenuRenderer.HEADER_HEIGHT
			+ (row - scroll) * MenuRenderer.ROW_HEIGHT;
	}

	int hoverIndex(Point mouse)
	{
		if (mouse == null || mouse.getX() < bounds.x
			|| mouse.getX() >= bounds.x + bounds.width
			|| mouse.getY() >= canvasHeight || mouse.getY() >= bounds.y + bounds.height)
		{
			return -1;
		}
		int relativeY = mouse.getY() - (bounds.y + MenuRenderer.HEADER_HEIGHT);
		if (relativeY < 0)
		{
			return -1;
		}
		int row = scroll + relativeY / MenuRenderer.ROW_HEIGHT;
		return containsRow(row) ? row : -1;
	}
}

package com.rightclickstyler;

import java.awt.Color;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.events.ClientTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PluginMessage;

@Singleton
final class StylePublisher
{
	static final String NAMESPACE = "right-click-styler";
	private final EventBus eventBus;
	private final ClientThread clientThread;
	private final ThemeManager themes;
	private volatile boolean active;
	private Theme lastSent;

	@Inject
	StylePublisher(EventBus eventBus, ClientThread clientThread, ThemeManager themes)
	{
		this.eventBus = eventBus;
		this.clientThread = clientThread;
		this.themes = themes;
	}

	void start()
	{
		active = true;
		eventBus.register(this);
		clientThread.invokeLater(this::publish);
	}

	void stop()
	{
		active = false;
		eventBus.unregister(this);
		clientThread.invokeLater(() ->
		{
			if (!active)
			{
				lastSent = null;
				Map<String, Object> inactive = new LinkedHashMap<>();
				inactive.put("version", 1);
				inactive.put("active", Boolean.FALSE);
				eventBus.post(new PluginMessage(NAMESPACE, "style", Collections.unmodifiableMap(inactive)));
			}
		});
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (active && themes.effectiveTheme() != lastSent)
		{
			publish();
		}
	}

	@Subscribe
	public void onPluginMessage(PluginMessage event)
	{
		if (NAMESPACE.equals(event.getNamespace()) && "style-request".equals(event.getName()))
		{
			clientThread.invokeLater(this::publish);
		}
	}

	private void publish()
	{
		if (!active)
		{
			return;
		}
		Theme theme = themes.effectiveTheme();
		lastSent = theme;
		eventBus.post(new PluginMessage(NAMESPACE, "style", snapshot(theme)));
	}

	static Map<String, Object> snapshot(Theme theme)
	{
		Map<String, Object> values = new LinkedHashMap<>();
		values.put("version", 1);
		values.put("active", true);
		values.put("font", MenuRenderer.buildFont(theme.font, theme.fontSize));
		values.put("text", theme.text);
		values.put("background", new Color(theme.bg.getRed(), theme.bg.getGreen(), theme.bg.getBlue(),
			(int) Math.round(theme.opacity * 255d / 100d)));
		values.put("border", theme.border);
		values.put("radius", theme.radius);
		values.put("showBorder", theme.showBorder);
		values.put("showShadow", theme.showShadow);
		values.put("textShadow", theme.textShadow);
		return Collections.unmodifiableMap(values);
	}
}

package com.rightclickstyler;

import java.awt.Rectangle;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;
import net.runelite.api.IndexedSprite;

/**
 * Reuse of the submenu's themed image. The probe, the exact-coverage
 * decision and every structural and lifecycle check still run on every frame; only the theme
 * render is skipped, and only when every input that render reads is equal to the inputs of the
 * image already in the buffer.
 *
 * <p>The key is the complete input of {@link MenuRenderer} as the overlay calls it: the theme
 * (immutable, compared by identity), every plugin config item, a copy of the mod-icon array
 * (compared sprite by sprite, so replacing a sprite in place is a miss),
 * the local combat level, the image region, and for each drawn menu its
 * bounds, header, root scroll offset, hovered row and every row's option, target, kind and
 * submenu arrow. Contents are compared by value, never by menu or entry identity, and never by
 * hash, so no collision can reuse a wrong image.
 */
final class SubmenuImageCache
{
	/** Why an image could not be reused; {@link #HIT} when it was. */
	enum Miss
	{
		HIT, EMPTY, UNCACHEABLE, THEME, CONFIG, ICONS, LEVEL, REGION, CHAIN, BOUNDS, HEADER, SCROLL,
		HOVER, ROWS
	}

	// Explicit config snapshot. Keep this list in sync with RightClickStylerConfig when adding
	// settings that affect rendering. Theme values are captured by the immutable theme reference.
	private static final int CONFIG_ITEM_COUNT = 18;

	private Key cached;

	/** The rendered image no longer matches {@link #cached}: reallocated, or a render began. */
	void invalidate()
	{
		cached = null;
	}

	Miss lookup(Key key)
	{
		if (key == null)
		{
			return Miss.UNCACHEABLE;
		}
		return cached == null ? Miss.EMPTY : cached.difference(key);
	}

	/** Call only after the image has been completely rendered from {@code key}'s inputs. */
	void rendered(Key key)
	{
		cached = key;
	}

	/**
	 * @return the key, or null when an input cannot be read reliably (the frame then renders
	 * uncached and nothing is stored)
	 */
	static Key capture(Theme theme, RightClickStylerConfig config, IndexedSprite[] modIcons, int localLevel,
		Rectangle region, Menu[] menus)
	{
		Object[] values;
		try
		{
			values = new Object[]{
				config.showSidebarButton(), config.activeTheme(),
				config.highlightsEnabled(), config.highlightsBold(), config.highlightRules(),
				config.targetMode(), config.npcColour(), config.playerColour(),
				config.itemColour(), config.objectColour(), config.otherColour(),
				config.combatLevelMode(), config.lowerLevelColour(), config.sameLevelColour(),
				config.higherLevelColour(), config.textOffsetX(), config.baselineNudge(),
				config.showHitRows()
			};
		}
		catch (RuntimeException e)
		{
			return null;
		}
		return new Key(theme, values, modIcons, localLevel, new Rectangle(region), menus);
	}

	/** One drawn menu, captured from the rows the renderer is about to draw. */
	static Menu menu(Rectangle bounds, String header, int scroll, int hovered, List<MenuRenderer.Row> rows)
	{
		return menu(bounds, header, null, scroll, hovered, rows);
	}

	/** @param headerKind how the header's target colours resolve; see {@link MenuRenderer} */
	static Menu menu(Rectangle bounds, String header, MenuRenderer.TargetKind headerKind, int scroll,
		int hovered, List<MenuRenderer.Row> rows)
	{
		int count = rows.size();
		String[] options = new String[count];
		String[] targets = new String[count];
		int[] flags = new int[count];
		for (int i = 0; i < count; i++)
		{
			MenuRenderer.Row row = rows.get(i);
			options[i] = row.option();
			targets[i] = row.target();
			flags[i] = row.flags();
		}
		return new Menu(new Rectangle(bounds), header, headerKind, scroll, hovered, options, targets, flags);
	}

	static final class Menu
	{
		private final Rectangle bounds;
		private final String header;
		private final MenuRenderer.TargetKind headerKind;
		private final int scroll;
		private final int hovered;
		private final String[] options;
		private final String[] targets;
		private final int[] flags;

		private Menu(Rectangle bounds, String header, MenuRenderer.TargetKind headerKind, int scroll,
			int hovered, String[] options, String[] targets, int[] flags)
		{
			this.bounds = bounds;
			this.header = header;
			this.headerKind = headerKind;
			this.scroll = scroll;
			this.hovered = hovered;
			this.options = options;
			this.targets = targets;
			this.flags = flags;
		}
	}

	static final class Key
	{
		private final Theme theme;
		private final Object[] config;
		private final IndexedSprite[] modIcons;
		private final int localLevel;
		private final Rectangle region;
		private final Menu[] menus;

		private Key(Theme theme, Object[] config, IndexedSprite[] modIcons, int localLevel, Rectangle region, Menu[] menus)
		{
			this.theme = theme;
			this.config = config;
			this.modIcons = modIcons == null ? null : modIcons.clone();
			this.localLevel = localLevel;
			this.region = region;
			this.menus = menus;
		}

		/** The first input class that differs, cheapest checks first; HIT when all are equal. */
		Miss difference(Key other)
		{
			if (theme != other.theme)
			{
				return Miss.THEME;
			}
			if (!Arrays.equals(config, other.config))
			{
				return Miss.CONFIG;
			}
			if (!Arrays.equals(modIcons, other.modIcons))
			{
				return Miss.ICONS;
			}
			if (localLevel != other.localLevel)
			{
				return Miss.LEVEL;
			}
			if (!region.equals(other.region))
			{
				return Miss.REGION;
			}
			return menusDifference(menus, other.menus);
		}
	}

	/**
	 * The first per-menu input class that differs between two drawn chains, HIT when the
	 * renderer would receive equal inputs for every menu. With one theme, config, set of icon sprites
	 * and level, HIT means the two chains render identical pixels: the same rule that lets the
	 * cache reuse an image. Callbacks and entry identity are deliberately not inputs.
	 */
	static Miss menusDifference(Menu[] menus, Menu[] other)
	{
		if (menus.length != other.length)
		{
			return Miss.CHAIN;
		}
		Miss found = Miss.HIT;
		for (int depth = 0; depth < menus.length && found == Miss.HIT; depth++)
		{
			Menu a = menus[depth];
			Menu b = other[depth];
			if (!a.bounds.equals(b.bounds))
			{
				found = Miss.BOUNDS;
			}
			else if (!Objects.equals(a.header, b.header) || a.headerKind != b.headerKind)
			{
				found = Miss.HEADER;
			}
			else if (a.scroll != b.scroll)
			{
				found = Miss.SCROLL;
			}
			else if (!Arrays.equals(a.options, b.options) || !Arrays.equals(a.targets, b.targets)
				|| !Arrays.equals(a.flags, b.flags))
			{
				found = Miss.ROWS;
			}
		}
		if (found != Miss.HIT)
		{
			return found;
		}
		// Hover last: when everything else matches, it alone decides.
		for (int depth = 0; depth < menus.length; depth++)
		{
			if (menus[depth].hovered != other[depth].hovered)
			{
				return Miss.HOVER;
			}
		}
		return Miss.HIT;
	}

	/**
	 * Diagnostics only: the first input that differs between two drawn chains, with its depth,
	 * row and both values, in the order {@link #menusDifference} checks them; null when equal.
	 */
	static String describeDifference(Menu[] menus, Menu[] other)
	{
		Miss miss = menusDifference(menus, other);
		if (miss == Miss.HIT)
		{
			return null;
		}
		if (miss == Miss.CHAIN)
		{
			return "CHAIN depth " + (menus.length - 1) + " vs " + (other.length - 1);
		}
		for (int depth = 0; depth < menus.length; depth++)
		{
			Menu a = menus[depth];
			Menu b = other[depth];
			String prefix = miss + " depth=" + depth;
			switch (miss)
			{
				case BOUNDS:
					if (!a.bounds.equals(b.bounds))
					{
						return prefix + " " + text(a.bounds) + " vs " + text(b.bounds);
					}
					break;
				case HEADER:
					if (!Objects.equals(a.header, b.header) || a.headerKind != b.headerKind)
					{
						return prefix + " '" + a.header + "'/" + a.headerKind + " vs '" + b.header + "'/" + b.headerKind;
					}
					break;
				case SCROLL:
					if (a.scroll != b.scroll)
					{
						return prefix + " " + a.scroll + " vs " + b.scroll;
					}
					break;
				case HOVER:
					if (a.hovered != b.hovered)
					{
						return prefix + " " + a.hovered + " vs " + b.hovered;
					}
					break;
				case ROWS:
					if (a.options.length != b.options.length)
					{
						return prefix + " count " + a.options.length + " vs " + b.options.length;
					}
					for (int row = 0; row < a.options.length; row++)
					{
						if (!Objects.equals(a.options[row], b.options[row]))
						{
							return prefix + " row=" + row + " option '" + a.options[row] + "' vs '" + b.options[row] + "'";
						}
						if (!Objects.equals(a.targets[row], b.targets[row]))
						{
							return prefix + " row=" + row + " target '" + a.targets[row] + "' vs '" + b.targets[row] + "'";
						}
						if (a.flags[row] != b.flags[row])
						{
							return prefix + " row=" + row + " flags(kind<<2|arrow<<1|arrowLeft) "
								+ a.flags[row] + " vs " + b.flags[row];
						}
					}
					break;
				default:
					break;
			}
		}
		return miss.name();
	}

	private static String text(Rectangle r)
	{
		return r.x + "," + r.y + "," + r.width + "x" + r.height;
	}

	static int configItemCount()
	{
		return CONFIG_ITEM_COUNT;
	}
}

package com.rightclickstyler;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.IdentityHashMap;
import java.util.List;
import net.runelite.api.Menu;
import net.runelite.api.MenuEntry;

/** A bounded, single-frame snapshot of the public menu hierarchy. */
final class SubmenuTree
{
	static final int MAX_DEPTH = 8;
	static final int MAX_ENTRIES = 512;
	// One root with the maximum permitted number of direct child menus. Nested
	// trees share this budget, and the total entry budget limits row storage.
	static final int MAX_MENUS = MAX_ENTRIES + 1;
	static final int MAX_TOTAL_ENTRIES = MAX_ENTRIES * (MAX_DEPTH + 1);

	final Menu root;
	final List<Node> nodes = new ArrayList<>();
	final List<Rectangle> candidateBounds = new ArrayList<>();
	final List<Integer> candidateParents = new ArrayList<>();
	private int totalEntries;
	private final int skippedRootRows;

	private SubmenuTree(Menu root, MenuEntry[] rootEntries, int skippedRootRows)
	{
		this.root = root;
		this.skippedRootRows = skippedRootRows;
		collect(root, rootEntries, -1, -1, null, false, 0, new IdentityHashMap<>());
	}

	static SubmenuTree capture(Menu root)
	{
		return capture(root, root == null ? null : root.getMenuEntries());
	}

	static SubmenuTree capture(Menu root, MenuEntry[] rootEntries)
	{
		return capture(root, rootEntries, 0);
	}

	static SubmenuTree capture(Menu root, MenuEntry[] rootEntries, int skippedRootRows)
	{
		if (root == null)
		{
			throw new IllegalArgumentException("missing root menu");
		}
		MenuEntry[] entries = rootEntries == null ? root.getMenuEntries() : rootEntries;
		if (entries != null && (skippedRootRows < 0 || skippedRootRows > entries.length))
		{
			throw new IllegalArgumentException("invalid root scroll skip=" + skippedRootRows
				+ " entries=" + entries.length);
		}
		return new SubmenuTree(root, entries, skippedRootRows);
	}

	private void collect(Menu menu, MenuEntry[] suppliedEntries, int parentNode,
		int parentEntryIndex, String header, boolean headerFromTarget, int depth,
		IdentityHashMap<Menu, Boolean> seen)
	{
		if (depth > MAX_DEPTH)
		{
			throw new IllegalArgumentException("menu depth limit exceeded depth=" + depth
				+ " limit=" + MAX_DEPTH);
		}
		if (nodes.size() >= MAX_MENUS)
		{
			throw new IllegalArgumentException("menu count limit exceeded nodes=" + nodes.size()
				+ " limit=" + MAX_MENUS + " depth=" + depth
				+ " rootEntries=" + nodes.get(0).entries.length
				+ " skippedRootRows=" + skippedRootRows);
		}
		if (seen.put(menu, Boolean.TRUE) != null)
		{
			throw new IllegalArgumentException("menu identity cycle or reuse depth=" + depth
				+ " parentEntryIndex=" + parentEntryIndex);
		}
		MenuEntry[] entries = suppliedEntries == null ? menu.getMenuEntries() : suppliedEntries;
		boolean rootMenu = parentNode < 0;
		if (entries == null)
		{
			entries = new MenuEntry[0];
		}
		if ((rootMenu && entries.length == 0) || entries.length > MAX_ENTRIES)
		{
			throw new IllegalArgumentException("invalid menu entry count depth=" + depth
				+ " entries=" + entries.length);
		}
		totalEntries += entries.length;
		if (totalEntries > MAX_TOTAL_ENTRIES)
		{
			throw new IllegalArgumentException("menu total entry count limit exceeded total="
				+ totalEntries + " limit=" + MAX_TOTAL_ENTRIES + " depth=" + depth);
		}
		Rectangle bounds = new Rectangle(menu.getMenuX(), menu.getMenuY(),
			menu.getMenuWidth(), menu.getMenuHeight());
		if (bounds.width < 0 || bounds.height < 0
			|| (rootMenu && (bounds.width == 0 || bounds.height == 0))
			|| (!rootMenu && entries.length == 0 && bounds.width > 0 && bounds.height > 0))
		{
			throw new IllegalArgumentException("invalid menu bounds depth=" + depth
				+ " bounds=" + bounds + " entries=" + entries.length);
		}
		int index = nodes.size();
		boolean[] childFlags = new boolean[entries.length];
		boolean[] childOpensLeft = new boolean[entries.length];
		nodes.add(new Node(menu, entries, childFlags, childOpensLeft,
			bounds, parentNode, parentEntryIndex, header, headerFromTarget));
		if (parentNode >= 0)
		{
			candidateBounds.add(bounds);
			candidateParents.add(parentNode == 0 ? -1 : parentNode - 1);
		}
		for (int j = 0; j < entries.length; j++)
		{
			MenuEntry entry = entries[j];
			if (entry != null)
			{
				Menu child = entry.getSubMenu();
				if (child != null)
				{
					childFlags[j] = true;
					// Native drawing skips rows above the root scroll offset before
					// recursing into their children. Rows below the canvas are still
					// visited, so they must remain probe candidates.
					if (rootMenu && entries.length - 1 - j < skippedRootRows)
					{
						continue;
					}
					childOpensLeft[j] = child.getMenuWidth() > 0
						&& child.getMenuX() < menu.getMenuX();
					String target = entry.getTarget();
					boolean fromTarget = target != null && !target.trim().isEmpty();
					String contextualHeader = fromTarget ? target : entry.getOption();
					collect(child, null, index, j, contextualHeader, fromTarget, depth + 1, seen);
				}
			}
		}
	}

	static final class Node
	{
		final Menu menu;
		final MenuEntry[] entries;
		final boolean[] childFlags;
		final boolean[] childOpensLeft;
		final Rectangle bounds;
		final int parentNode;
		final int parentEntryIndex;
		final String header;
		/** The header repeats the opening entry's target, rather than its option. */
		final boolean headerFromTarget;

		private Node(Menu menu, MenuEntry[] entries, boolean[] childFlags,
			boolean[] childOpensLeft,
			Rectangle bounds, int parentNode, int parentEntryIndex, String header,
			boolean headerFromTarget)
		{
			this.menu = menu;
			this.entries = entries;
			this.childFlags = childFlags;
			this.childOpensLeft = childOpensLeft;
			this.bounds = bounds;
			this.parentNode = parentNode;
			this.parentEntryIndex = parentEntryIndex;
			this.header = header;
			this.headerFromTarget = headerFromTarget;
		}
	}
}

