import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Owns the built-in and user themes, which theme is active, and the "working copy" that the overlay
 * and the sidebar preview both render live as the user edits. User themes are saved as JSON in
 * the {@code userThemes} config key and hidden {@code activeTheme} config item.
 * <p>
 * After startup, everything except {@link #effectiveTheme()} is only touched from the EDT (the
 * panel). The overlay reads {@link #effectiveTheme()} on the client thread; {@link Theme} is
 * immutable and the reference is volatile, so it always sees a complete theme.
 */
@Slf4j
@Singleton
class ThemeManager
{
	private static final String EXPORT_PREFIX = "rightclickstyler:";
	private static final String DEFAULT_THEME_NAME = "Theme";
	private static final String COPY_SUFFIX = " copy";

	static final String ERROR_FULL = "You already have the maximum of " + Limits.MAX_USER_THEMES + " themes.";
	private static final String ERROR_TOO_LONG = "That text is too long to be an exported theme.";
	private static final String ERROR_INVALID = "That doesn't look like a valid exported theme.";

	private final Supplier<String> themesReader;
	private final BiConsumer<String, String> configWriter;
	private final RightClickStylerConfig config;
	private final Gson gson;

	private final Map<String, Theme> userThemes = new LinkedHashMap<>();
	private String activeId = BuiltInThemes.DEFAULT_ID;
	private volatile Theme working = BuiltInThemes.find(BuiltInThemes.DEFAULT_ID);

	@Inject
	ThemeManager(ConfigManager configManager, RightClickStylerConfig config, Gson gson)
	{
		this(() -> configManager.getConfiguration(RightClickStylerConfig.GROUP,
			RightClickStylerConfig.KEY_USER_THEMES),
			(key, value) -> configManager.setConfiguration(RightClickStylerConfig.GROUP, key, value), config, gson);
	}

	ThemeManager(Supplier<String> themesReader, BiConsumer<String, String> configWriter,
		RightClickStylerConfig config, Gson gson)
	{
		this.themesReader = themesReader;
		this.configWriter = configWriter;
		this.config = config;
		this.gson = gson;
		reload();
	}

	Theme effectiveTheme()
	{
		return working;
	}

	void setWorking(Theme theme)
	{
		working = theme;
	}

	List<Theme> builtIns()
	{
		return BuiltInThemes.ALL;
	}

	List<Theme> userThemes()
	{
		return new ArrayList<>(userThemes.values());
	}

	String activeId()
	{
		return activeId;
	}

	Theme active()
	{
		Theme theme = find(activeId);
		return theme != null ? theme : BuiltInThemes.find(BuiltInThemes.DEFAULT_ID);
	}

	boolean isEdited()
	{
		return !working.sameStyle(active());
	}

	private boolean isFull()
	{
		return userThemes.size() >= Limits.MAX_USER_THEMES;
	}

	void applyTheme(String id)
	{
		Theme theme = find(id);
		if (theme == null)
		{
			return;
		}
		activeId = id;
		working = theme;
		persistActiveId();
	}

	void save()
	{
		Theme active = userThemes.get(activeId);
		if (active == null)
		{
			return;
		}
		Theme saved = working.withIdentity(active.id, active.name, false);
		userThemes.put(saved.id, saved);
		working = saved;
		persistUserThemes();
	}

	/**
	 * @return false if the user theme limit has been reached
	 */
	boolean saveAsNew(String name)
	{
		return addAndActivate(working, name);
	}

	void revert()
	{
		working = active();
	}

	void rename(String newName)
	{
		Theme active = userThemes.get(activeId);
		if (active == null)
		{
			return;
		}
		Theme renamed = active.withIdentity(active.id, cleanName(newName), false);
		userThemes.put(renamed.id, renamed);
		if (working.id.equals(active.id))
		{
			working = working.withIdentity(renamed.id, renamed.name, false);
		}
		persistUserThemes();
	}

	/**
	 * @return false if the user theme limit has been reached
	 */
	boolean duplicate()
	{
		Theme source = active();
		return addAndActivate(source, source.name + COPY_SUFFIX);
	}

	void delete(String id)
	{
		if (userThemes.remove(id) == null)
		{
			return;
		}
		persistUserThemes();
		if (activeId.equals(id))
		{
			applyTheme(BuiltInThemes.DEFAULT_ID);
		}
	}

	/**
	 * Exports the live working copy so sidebar edits are included without saving them.
	 */
	String exportWorking()
	{
		Theme theme = working;
		String json = gson.toJson(StoredTheme.from(theme));
		return EXPORT_PREFIX + Base64.getEncoder().encodeToString(json.getBytes(StandardCharsets.UTF_8));
	}

	/**
	 * Never throws.
	 *
	 * @return null on success, otherwise a message suitable for showing to the user
	 */
	String importTheme(String payload)
	{
		if (isFull())
		{
			return ERROR_FULL;
		}
		String trimmed = payload == null ? "" : payload.trim();
		if (trimmed.length() > Limits.MAX_IMPORT_LENGTH)
		{
			return ERROR_TOO_LONG;
		}
		if (trimmed.startsWith(EXPORT_PREFIX))
		{
			trimmed = trimmed.substring(EXPORT_PREFIX.length());
		}

		Theme theme;
		try
		{
			String json = new String(Base64.getDecoder().decode(trimmed), StandardCharsets.UTF_8);
			StoredTheme stored = gson.fromJson(json, StoredTheme.class);
			// an exported theme always carries an id; requiring one rejects arbitrary JSON objects
			theme = stored == null || stored.id == null || stored.id.isEmpty()
				? null : stored.toTheme(UUID.randomUUID().toString());
		}
		catch (RuntimeException e)
		{
			log.debug("Rejected theme import", e);
			return ERROR_INVALID;
		}
		if (theme == null)
		{
			return ERROR_INVALID;
		}

		addAndActivate(theme, theme.name);
		return null;
	}

	/**
	 * Replaces cached theme state from the active RuneLite configuration profile. This runs during
	 * construction and again after profile changes. Corrupt config loads as defaults rather than
	 * failing startup.
	 */
	void reload()
	{
		userThemes.clear();
		try
		{
			StoredTheme[] stored = gson.fromJson(themesReader.get(), StoredTheme[].class);
			if (stored != null)
			{
				for (StoredTheme s : stored)
				{
					if (userThemes.size() >= Limits.MAX_USER_THEMES)
					{
						break;
					}
					// first occurrence of a duplicated id wins
					if (s != null && isValidStoredId(s.id) && !userThemes.containsKey(s.id))
					{
						userThemes.put(s.id, s.toTheme(s.id));
					}
				}
			}
		}
		catch (RuntimeException e)
		{
			log.warn("Saved custom themes for Right Click Styler are corrupt; starting with none", e);
			userThemes.clear();
		}

		activeId = config.activeTheme();
		Theme theme = find(activeId);
		if (theme == null)
		{
			activeId = BuiltInThemes.DEFAULT_ID;
			theme = BuiltInThemes.find(activeId);
		}
		working = theme;
	}

	private static boolean isValidStoredId(String id)
	{
		return id != null && !id.isEmpty() && id.length() <= Limits.MAX_THEME_ID_LENGTH
			&& BuiltInThemes.find(id) == null;
	}

	private boolean addAndActivate(Theme source, String name)
	{
		if (isFull())
		{
			return false;
		}
		String id = UUID.randomUUID().toString();
		Theme theme = source.withIdentity(id, cleanName(name), false);
		userThemes.put(id, theme);
		activeId = id;
		working = theme;
		persistUserThemes();
		persistActiveId();
		return true;
	}

	private Theme find(String id)
	{
		if (id == null)
		{
			return null;
		}
		Theme builtIn = BuiltInThemes.find(id);
		return builtIn != null ? builtIn : userThemes.get(id);
	}

	private static String cleanName(String name)
	{
		String value = name == null ? "" : name;
		StringBuilder cleaned = null;
		for (int offset = 0; offset < value.length();)
		{
			int codePoint = value.codePointAt(offset);
			int width = Character.charCount(codePoint);
			if (Character.isISOControl(codePoint))
			{
				if (cleaned == null)
				{
					cleaned = new StringBuilder(value.length());
					cleaned.append(value, 0, offset);
				}
			}
			else if (cleaned != null)
			{
				cleaned.appendCodePoint(codePoint);
			}
			offset += width;
		}

		String trimmed = (cleaned == null ? value : cleaned.toString()).trim();
		return trimmed.isEmpty() ? DEFAULT_THEME_NAME : Limits.truncate(trimmed, Limits.MAX_THEME_NAME_LENGTH);
	}

	private void persistUserThemes()
	{
		List<StoredTheme> stored = new ArrayList<>(userThemes.size());
		for (Theme theme : userThemes.values())
		{
			stored.add(StoredTheme.from(theme));
		}
		configWriter.accept(RightClickStylerConfig.KEY_USER_THEMES, gson.toJson(stored));
	}

	private void persistActiveId()
	{
		configWriter.accept(RightClickStylerConfig.KEY_ACTIVE_THEME, activeId);
	}

	/**
	 * Gson-friendly shape for a theme: colours as plain ARGB ints, enums as names. Used for both the
	 * persisted user theme list and the clipboard export/import format. Boxed fields so that values
	 * missing from the JSON can be told apart. Most fields use the default built-in theme;
	 * legacy hover opacity uses the saved background opacity.
	 */
	private static final class StoredTheme
	{
		String id;
		String name;
		Integer bg;
		Integer border;
		Integer header;
		Integer headerText;
		Integer text;
		Integer hover;
		Integer accent;
		Integer radius;
		Integer opacity;
		Integer hoverOpacity;
		String hoverStyle;
		Boolean showBorder;
		Boolean showShadow;
		Boolean showHeader;
		String font;
		Integer fontSize;
		Boolean textShadow;

		static StoredTheme from(Theme t)
		{
			StoredTheme s = new StoredTheme();
			s.id = t.id;
			s.name = t.name;
			s.bg = t.bg.getRGB();
			s.border = t.border.getRGB();
			s.header = t.header.getRGB();
			s.headerText = t.headerText.getRGB();
			s.text = t.text.getRGB();
			s.hover = t.hover.getRGB();
			s.accent = t.accent.getRGB();
			s.radius = t.radius;
			s.opacity = t.opacity;
			s.hoverOpacity = t.hoverOpacity;
			s.hoverStyle = t.hoverStyle.name();
			s.showBorder = t.showBorder;
			s.showShadow = t.showShadow;
			s.showHeader = t.showHeader;
			s.font = t.font.name();
			s.fontSize = t.fontSize;
			s.textShadow = t.textShadow;
			return s;
		}

		Theme toTheme(String themeId)
		{
			Theme d = BuiltInThemes.find(BuiltInThemes.DEFAULT_ID);
			int backgroundOpacity = Limits.clamp(opacity != null ? opacity : d.opacity,
				Limits.MIN_OPACITY, Limits.MAX_OPACITY);
			// Older saved and exported themes used one opacity for both fills.
			int loadedHoverOpacity = Limits.clamp(hoverOpacity != null ? hoverOpacity : backgroundOpacity,
				Limits.MIN_OPACITY, Limits.MAX_OPACITY);
			return new Theme(themeId, cleanName(name), false,
				colour(bg, d.bg), colour(border, d.border), colour(header, d.header),
				colour(headerText, d.headerText), colour(text, d.text), colour(hover, d.hover),
				colour(accent, d.accent),
				Limits.clamp(radius != null ? radius : d.radius, Limits.MIN_RADIUS, Limits.MAX_RADIUS),
				backgroundOpacity, loadedHoverOpacity,
				enumOr(HoverStyle.class, hoverStyle, d.hoverStyle),
				showBorder != null ? showBorder : d.showBorder,
				showShadow != null ? showShadow : d.showShadow,
				showHeader != null ? showHeader : d.showHeader,
				enumOr(FontChoice.class, font, d.font),
				Limits.clamp(fontSize != null ? fontSize : d.fontSize, Limits.MIN_FONT_SIZE, Limits.MAX_FONT_SIZE),
				textShadow != null ? textShadow : d.textShadow);
		}

		private static Color colour(Integer argb, Color fallback)
		{
			return argb != null ? new Color(argb, true) : fallback;
		}

		private static <E extends Enum<E>> E enumOr(Class<E> type, String name, E fallback)
		{
			if (name == null)
			{
				return fallback;
			}
			try
			{
				return Enum.valueOf(type, name);
			}
			catch (IllegalArgumentException e)
			{
				return fallback;
			}
		}
	}
}

package com.rightclickstyler;

import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Arrays;
import java.util.List;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/**
 * Draws a fixed sample menu with the current working theme, for live feedback while editing. Paints
 * on the EDT, so it never touches {@code Client}; player details come from {@link LocalPlayerSnapshot}.
 */
class ThemePreview extends JPanel
{
	private static final int TOP_MARGIN = 10;
	private static final int SIDE_MARGIN = 8;
	private static final int MIN_MENU_WIDTH = 10;
	// Lowest possible combat level; used while logged out.
	private static final int PLACEHOLDER_COMBAT_LEVEL = 3;

	private static final List<MenuRenderer.Row> SAMPLE_ROWS = Arrays.asList(
		new MenuRenderer.Row("Attack", "<col=ffff00>Guard</col> <col=ffffff>(level-21)</col>", MenuRenderer.TargetKind.NPC),
		new MenuRenderer.Row("Pickpocket", "<col=ffff00>Guard</col>", MenuRenderer.TargetKind.NPC),
		new MenuRenderer.Row("Use", "<col=ff9040>Lobster</col>", MenuRenderer.TargetKind.ITEM),
		new MenuRenderer.Row("Walk here", "", MenuRenderer.TargetKind.OTHER),
		new MenuRenderer.Row("Examine", "<col=ffff00>Guard</col>", MenuRenderer.TargetKind.NPC),
		new MenuRenderer.Row("Cancel", "", MenuRenderer.TargetKind.OTHER)
	);

	private final LocalPlayerSnapshot localPlayer;
	private final ThemeManager themeManager;
	private final RightClickStylerConfig config;
	private final MenuRenderer renderer = new MenuRenderer();
	private final Rectangle bounds = new Rectangle();

	private int hoverIndex = -1;

	ThemePreview(LocalPlayerSnapshot localPlayer, ThemeManager themeManager, RightClickStylerConfig config)
	{
		this.localPlayer = localPlayer;
		this.themeManager = themeManager;
		this.config = config;
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		localPlayer.setOnChange(this::repaint);

		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				updateHover(e.getY());
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				setHover(-1);
			}
		};
		addMouseMotionListener(mouse);
		addMouseListener(mouse);
	}

	/**
	 * Call after any change that can affect the drawn menu; header/row heights change its size.
	 */
	void refresh()
	{
		revalidate();
		repaint();
	}

	// DynamicGridLayout scales each child's preferred width to fill the column, so a width of 0 (as
	// getWidth() is before the first layout) would stay 0. Any non-zero width gets stretched to fit.
	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(MIN_MENU_WIDTH + SIDE_MARGIN * 2,
			rowsTop(themeManager.effectiveTheme()) + rowsHeight() + TOP_MARGIN);
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		Theme theme = themeManager.effectiveTheme();
		int width = Math.max(MIN_MENU_WIDTH, getWidth() - SIDE_MARGIN * 2);
		// The renderer always leaves room for the header, so shift up when it's hidden.
		bounds.setBounds(SIDE_MARGIN, rowsTop(theme) - MenuRenderer.HEADER_HEIGHT, width,
			MenuRenderer.HEADER_HEIGHT + rowsHeight());
		int level = localPlayer.combatLevel();
		renderer.render((Graphics2D) g, null, theme, config, SAMPLE_ROWS, bounds, hoverIndex,
			level != LocalPlayerSnapshot.UNKNOWN ? level : PLACEHOLDER_COMBAT_LEVEL);
	}

	private void updateHover(int mouseY)
	{
		int relativeY = mouseY - rowsTop(themeManager.effectiveTheme());
		int index = relativeY < 0 ? -1 : relativeY / MenuRenderer.ROW_HEIGHT;
		setHover(index < SAMPLE_ROWS.size() ? index : -1);
	}

	private void setHover(int index)
	{
		if (index != hoverIndex)
		{
			hoverIndex = index;
			repaint();
		}
	}

	private static int rowsTop(Theme theme)
	{
		return TOP_MARGIN + (theme.showHeader ? MenuRenderer.HEADER_HEIGHT : 0);
	}

	private static int rowsHeight()
	{
		return MenuRenderer.ROW_HEIGHT * SAMPLE_ROWS.size();
	}
}

package com.rightclickstyler;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.IndexedSprite;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class MutableMenuIconsTest
{
	private final RightClickStylerConfig config = new RightClickStylerConfig() {};
	private final Theme theme = BuiltInThemes.ALL.get(0).withOpacity(100).withFont(FontChoice.SANS);
	private final List<MenuRenderer.Row> rows = List.of(new MenuRenderer.Row("Take", "<img=0>Coins", MenuRenderer.TargetKind.ITEM));
	private final Rectangle bounds = new Rectangle(0, 0, 240, 50);

	@Test
	public void opaqueMenusDrawUpdatedIconsOnTopOfTheirBackground()
	{
		Client client = mock(Client.class);
		IndexedSprite[] icons = {sprite(Color.MAGENTA)};
		when(client.getModIcons()).thenReturn(icons);
		MenuRenderer renderer = new MenuRenderer();
		for (int opacity : new int[]{30, 100})
		{
			icons[0] = sprite(Color.MAGENTA);
			assertTrue(contains(render(renderer, client, opacity), Color.MAGENTA));
			icons[0] = sprite(Color.CYAN);
			BufferedImage changed = render(renderer, client, opacity);
			assertTrue(contains(changed, Color.CYAN));
			assertFalse(contains(changed, Color.MAGENTA));
		}
	}

	@Test
	public void submenuCacheDetectsSpriteReplacementInTheSameArray()
	{
		IndexedSprite[] icons = {sprite(Color.MAGENTA)};
		SubmenuImageCache.Menu[] menus = {SubmenuImageCache.menu(bounds, "Coins", 0, -1, rows)};
		SubmenuImageCache cache = new SubmenuImageCache();
		cache.rendered(SubmenuImageCache.capture(theme, config, icons, 3, bounds, menus));
		assertEquals(SubmenuImageCache.Miss.HIT, cache.lookup(SubmenuImageCache.capture(theme, config, icons, 3, bounds, menus)));
		icons[0] = sprite(Color.CYAN);
		assertEquals(SubmenuImageCache.Miss.ICONS, cache.lookup(SubmenuImageCache.capture(theme, config, icons, 3, bounds, menus)));
	}

	private BufferedImage render(MenuRenderer renderer, Client client, int opacity)
	{
		BufferedImage image = new BufferedImage(240, 50, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			renderer.render(graphics, client, theme.withOpacity(opacity), config, rows, bounds, -1, 3);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}

	private static IndexedSprite sprite(Color color)
	{
		IndexedSprite sprite = mock(IndexedSprite.class);
		when(sprite.getWidth()).thenReturn(2);
		when(sprite.getHeight()).thenReturn(2);
		when(sprite.getPixels()).thenReturn(new byte[]{1, 1, 1, 1});
		when(sprite.getPalette()).thenReturn(new int[]{0, color.getRGB() & 0xffffff});
		return sprite;
	}

	private static boolean contains(BufferedImage image, Color color)
	{
		for (int y = 0; y < image.getHeight(); y++)
			for (int x = 0; x < image.getWidth(); x++)
				if (image.getRGB(x, y) == color.getRGB())
					return true;
		return false;
	}
}

package com.rightclickstyler;

import com.google.gson.Gson;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.function.BooleanSupplier;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class RightClickStylerPanelTest
{
	private static final RightClickStylerConfig DEFAULTS = new RightClickStylerConfig() {};
	private static final RightClickStylerConfig CUSTOMISED = new RightClickStylerConfig()
	{
		@Override
		public Color itemColour()
		{
			return Color.MAGENTA;
		}

		@Override
		public Color higherLevelColour()
		{
			return Color.MAGENTA;
		}
	};

	@Test
	public void combatColourResetUnsetsOnlyTheLevelColours()
	{
		List<String> unset = new ArrayList<>();
		RightClickStylerPanel.resetCombatColourSettings(unset::add);
		assertEquals(Arrays.asList(RightClickStylerConfig.KEY_LOWER_LEVEL_COLOUR,
			RightClickStylerConfig.KEY_SAME_LEVEL_COLOUR, RightClickStylerConfig.KEY_HIGHER_LEVEL_COLOUR), unset);
		assertFalse(unset.contains(RightClickStylerConfig.KEY_COMBAT_LEVEL_MODE));
	}

	@Test
	public void targetColourResetKeepsTheTargetMode()
	{
		List<String> unset = new ArrayList<>();
		RightClickStylerPanel.resetTargetColourSettings(unset::add);
		assertEquals(5, unset.size());
		assertFalse(unset.contains(RightClickStylerConfig.KEY_TARGET_MODE));
	}

	@Test
	public void cancelledColourResetChangesNothing()
	{
		int[] asked = {0};
		boolean reset = RightClickStylerPanel.resetColoursIfConfirmed(
			RightClickStylerPanel.combatColours(CUSTOMISED), RightClickStylerPanel.combatColours(DEFAULTS),
			() ->
			{
				asked[0]++;
				return false;
			}, () -> fail("reset after Cancel"));
		assertFalse(reset);
		assertEquals(1, asked[0]);
	}

	@Test
	public void confirmedColourResetRunsTheReset()
	{
		int[] resets = {0};
		assertTrue(RightClickStylerPanel.resetColoursIfConfirmed(
			RightClickStylerPanel.targetColours(CUSTOMISED), RightClickStylerPanel.targetColours(DEFAULTS),
			() -> true, () -> resets[0]++));
		assertEquals(1, resets[0]);
	}

	@Test
	public void colourResetAtDefaultsDoesNotAsk()
	{
		BooleanSupplier neverAsk = () ->
		{
			throw new AssertionError("asked to confirm with nothing to reset");
		};
		assertFalse(RightClickStylerPanel.resetColoursIfConfirmed(RightClickStylerPanel.targetColours(DEFAULTS),
			RightClickStylerPanel.targetColours(DEFAULTS), neverAsk, () -> fail("reset at defaults")));
		assertFalse(RightClickStylerPanel.resetColoursIfConfirmed(RightClickStylerPanel.combatColours(DEFAULTS),
			RightClickStylerPanel.combatColours(DEFAULTS), neverAsk, () -> fail("reset at defaults")));
	}

	@Test
	public void cancelledRevertKeepsTheUnsavedEdits()
	{
		ThemeManager themes = themeManager();
		Theme edited = themes.effectiveTheme().withText(Color.MAGENTA);
		themes.setWorking(edited);

		assertFalse(RightClickStylerPanel.revertEdits(themes, () -> false));
		assertSame(edited, themes.effectiveTheme());
		assertTrue(themes.isEdited());
	}

	@Test
	public void confirmedRevertRestoresTheSavedTheme()
	{
		ThemeManager themes = themeManager();
		themes.setWorking(themes.effectiveTheme().withText(Color.MAGENTA));

		assertTrue(RightClickStylerPanel.revertEdits(themes, () -> true));
		assertFalse(themes.isEdited());
		assertTrue(themes.effectiveTheme().sameStyle(themes.active()));
	}

	@Test
	public void revertWithoutUnsavedEditsDoesNotAsk()
	{
		ThemeManager themes = themeManager();
		assertTrue(RightClickStylerPanel.revertEdits(themes, () ->
		{
			throw new AssertionError("asked to confirm with nothing to discard");
		}));
		assertFalse(themes.isEdited());
	}

	private static ThemeManager themeManager()
	{
		return new ThemeManager(() -> null, (key, value) ->
		{
		}, mock(RightClickStylerConfig.class), new Gson());
	}
}

package com.rightclickstyler;

import java.awt.Color;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.events.ClientTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PluginMessage;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class StylePublisherTest
{
	@Test
	public void publishesOnClientQueueAtStartupOnRequestAndAfterThemeChange()
	{
		Fixture f = new Fixture();
		f.publisher.start();
		assertTrue(f.received.values.isEmpty());
		f.drain();
		assertEquals(1, f.received.values.size());
		for (int tick = 0; tick < 100; tick++)
			f.bus.post(new ClientTick());
		assertEquals(1, f.received.values.size());
		f.bus.post(new PluginMessage(StylePublisher.NAMESPACE, "style-request"));
		assertEquals(1, f.received.values.size());
		f.drain();
		assertEquals(2, f.received.values.size());
		when(f.themes.effectiveTheme()).thenReturn(f.theme.withText(Color.MAGENTA));
		f.bus.post(new ClientTick());
		assertEquals(Color.MAGENTA, f.received.values.get(2).getData().get("text"));
	}

	@Test
	public void shutdownCancelsPendingPublicationAndReportsInactive()
	{
		Fixture f = new Fixture();
		f.publisher.start();
		f.publisher.stop();
		f.drain();
		assertEquals(1, f.received.values.size());
		Map<String, Object> inactive = f.received.values.get(0).getData();
		assertEquals(2, inactive.size());
		assertEquals(Integer.valueOf(1), inactive.get("version"));
		assertEquals(Boolean.FALSE, inactive.get("active"));
		assertThrows(UnsupportedOperationException.class, () -> inactive.put("active", true));
		f.bus.post(new ClientTick());
		f.bus.post(new PluginMessage(StylePublisher.NAMESPACE, "style-request"));
		f.drain();
		assertEquals(1, f.received.values.size());
		f.publisher.start();
		f.drain();
		assertEquals(true, f.received.values.get(1).getData().get("active"));
	}

	public static class Received
	{
		final List<PluginMessage> values = new ArrayList<>();
		@Subscribe
		public void onPluginMessage(PluginMessage message)
		{
			if ("style".equals(message.getName()))
				values.add(message);
		}
	}

	private static class Fixture
	{
		final EventBus bus = new EventBus(error -> { throw new AssertionError(error); });
		final ClientThread clientThread = mock(ClientThread.class);
		final ThemeManager themes = mock(ThemeManager.class);
		final Theme theme = BuiltInThemes.ALL.get(0);
		final Received received = new Received();
		final List<Runnable> queue = new ArrayList<>();
		final StylePublisher publisher = new StylePublisher(bus, clientThread, themes);

		Fixture()
		{
			bus.register(received);
			when(themes.effectiveTheme()).thenReturn(theme);
			doAnswer(call -> { queue.add(call.getArgument(0)); return null; })
				.when(clientThread).invokeLater(any(Runnable.class));
		}

		void drain()
		{
			while (!queue.isEmpty())
				queue.remove(0).run();
		}
	}
}

package com.rightclickstyler;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TargetColourTest
{
	private static final Color NATIVE_ITEM = new Color(0xFF9040);
	private static final Color NATIVE_NPC = Color.YELLOW;
	private static final Color CUSTOM_ITEM = new Color(0xE700FF);
	private static final Color CUSTOM_NPC = new Color(0x00C0FF);
	private static final Color CUSTOM_OTHER = new Color(0x808080);
	private static final Color LOWER_LEVEL = new Color(0x00FF80);
	private static final int LOCAL_LEVEL = 50;

	@Test
	public void customItemColourReplacesSingleNativeInventoryTag()
	{
		assertRuns(custom(), "<col=ff9040>Drakan's medallion", MenuRenderer.TargetKind.ITEM,
			"Drakan's medallion", CUSTOM_ITEM);
	}

	@Test
	public void customItemColourReplacesLootFiltersDuplicateNativeTag()
	{
		assertRuns(custom(), "<col=ff9040><col=ff9040>Drakan's medallion</col>", MenuRenderer.TargetKind.ITEM,
			"Drakan's medallion", CUSTOM_ITEM);
		assertRuns(custom(), "<col=ff9040><col=ff9040>Coins (1.2K)</col>", MenuRenderer.TargetKind.ITEM,
			"Coins (1.2K)", CUSTOM_ITEM);
	}

	@Test
	public void explicitThirdPartyColoursArePreserved()
	{
		// Loot Filters rule colour written after the native tag
		assertRuns(custom(), "<col=ff9040><col=00ff00>Rune scimitar</col>", MenuRenderer.TargetKind.ITEM,
			"Rune scimitar", Color.GREEN);
		// Ground Items highlight, which replaces the native tag
		assertRuns(custom(), "<col=ffff00>Coins", MenuRenderer.TargetKind.ITEM,
			"Coins", Color.YELLOW);
		// The item orange is not a native colour for other kinds
		assertRuns(custom(), "<col=ff9040>Lobster", MenuRenderer.TargetKind.OTHER,
			"Lobster", NATIVE_ITEM);
	}

	@Test
	public void laterTextSpansKeepTheirOwnColour()
	{
		assertRuns(custom(), "<col=ff9040>Coins</col><col=ffffff> (100)", MenuRenderer.TargetKind.ITEM,
			"Coins", CUSTOM_ITEM, " (100)", Color.WHITE);
		assertRuns(custom(), "<col=ff9040><col=ff9040>Coins</col><col=ff9040> (100)",
			MenuRenderer.TargetKind.ITEM,
			"Coins", CUSTOM_ITEM, " (100)", NATIVE_ITEM);
	}

	@Test
	public void uncolouredPrefixMakesTheFirstTagALaterSpan()
	{
		assertRuns(custom(), "Noted <col=ff9040>Bones", MenuRenderer.TargetKind.ITEM,
			"Noted ", CUSTOM_ITEM, "Bones", NATIVE_ITEM);
	}

	@Test
	public void iconWithoutTextDoesNotStartANewSpan()
	{
		assertRuns(custom(), "<col=ff9040><img=3><col=ff9040>Coins", MenuRenderer.TargetKind.ITEM,
			"Coins", CUSTOM_ITEM);
		assertRuns(custom(), "<col=ff9040>Coins<img=3><col=ff9040> (100)", MenuRenderer.TargetKind.ITEM,
			"Coins", CUSTOM_ITEM, " (100)", NATIVE_ITEM);
	}

	@Test
	public void duplicateNativeNpcTagTakesCustomColourAndKeepsCustomLevelColour()
	{
		assertRuns(custom(), "<col=ffff00><col=ffff00>Guard</col><col=ff00>  (level-21)",
			MenuRenderer.TargetKind.NPC,
			"Guard", CUSTOM_NPC, "(level-21)", LOWER_LEVEL);
	}

	@Test
	public void gameModeKeepsEveryTagColour()
	{
		RightClickStylerConfig game = config(TargetMode.GAME, CombatLevelMode.GAME);
		assertRuns(game, "<col=ff9040>Drakan's medallion", MenuRenderer.TargetKind.ITEM,
			"Drakan's medallion", NATIVE_ITEM);
		assertRuns(game, "<col=ff9040><col=ff9040>Drakan's medallion</col>", MenuRenderer.TargetKind.ITEM,
			"Drakan's medallion", NATIVE_ITEM);
		assertRuns(game, "<col=ff9040><col=00ff00>Rune scimitar</col>", MenuRenderer.TargetKind.ITEM,
			"Rune scimitar", Color.GREEN);
		assertRuns(game, "<col=ffff00><col=ffff00>Guard</col><col=ff00>  (level-21)",
			MenuRenderer.TargetKind.NPC,
			"Guard", NATIVE_NPC, "(level-21)", Color.GREEN);
	}

	private static RightClickStylerConfig custom()
	{
		return config(TargetMode.CUSTOM, CombatLevelMode.CUSTOM);
	}

	private static RightClickStylerConfig config(TargetMode targetMode, CombatLevelMode levelMode)
	{
		RightClickStylerConfig config = mock(RightClickStylerConfig.class);
		when(config.targetMode()).thenReturn(targetMode);
		when(config.combatLevelMode()).thenReturn(levelMode);
		when(config.itemColour()).thenReturn(CUSTOM_ITEM);
		when(config.npcColour()).thenReturn(CUSTOM_NPC);
		when(config.playerColour()).thenReturn(Color.PINK);
		when(config.objectColour()).thenReturn(Color.ORANGE);
		when(config.otherColour()).thenReturn(CUSTOM_OTHER);
		when(config.lowerLevelColour()).thenReturn(LOWER_LEVEL);
		when(config.sameLevelColour()).thenReturn(Color.LIGHT_GRAY);
		when(config.higherLevelColour()).thenReturn(Color.RED);
		return config;
	}

	/** Expected alternates each visible run's text with its colour, in drawing order. */
	private static void assertRuns(RightClickStylerConfig config, String target, MenuRenderer.TargetKind kind,
		Object... expected)
	{
		List<Map.Entry<String, Color>> runs = new MenuRenderer().targetRunColours(config, target, kind, LOCAL_LEVEL);
		List<Object> actual = new ArrayList<>();
		for (Map.Entry<String, Color> run : runs)
		{
			actual.add(run.getKey());
			actual.add(run.getValue());
		}
		assertEquals(target, Arrays.asList(expected), actual);
	}
}
